;---------------------------------------------------------------
; RSTEP - execute one Robot Language instruction
;
; The interpreter's whole cycle.  It first offers the instruction at the user PC
; to SSTEP, which runs any genuine 6800 instruction natively (on the stack) and
; advances the PC itself.  Only if SSTEP rejects the opcode (it is one of the 59
; undefined 6800 opcodes, flagged in OPBITMAP) is it looked up in ROBOT_TAB.  A
; handler does the work and returns A = instruction length, which is added to
; the PC here (A = 0 when the handler set the PC itself, as a taken branch does).
; An opcode in neither set goes to the RAM hook RI_BADOP; the default hook sets
; C, which makes the run loop stop and show the PC.  Emulator: a user hook
; "INC $0500; LDAA #1; CLC; RTS" at RI_BADOP let a program of three $00 bytes run
; through (count 3).  The Repeat-mode run loop ($F5B5) calls SSTEP and then
; RSTEP, so it executes two instructions per pass; breakpoints are compared only
; between passes (emulator: on a NOP run from $0400 a breakpoint at $0402 hit,
; ones at $0401 and $0403 never did).  A native instruction costs about 650-800
; cycles (~0.8 ms) per step in Robot Language (measured).
;
; In:        USERFRAME -> user registers; user PC = next instruction
; Out:       C = 0 executed (user PC advanced), C = 1 unknown opcode (contract)
; Memory:    writes CURPC; user frame PC; whatever the handler touches
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 12,122 calls, 3/4 branches]
; Stack:     12 bytes max, including callees (observed 58)
; Cycles:    observed 411-71,653,444 E cycles over 12,122 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; indirect JSR at $E02C
; Calls:     SSTEP, RAM hook $0012, RAM hook $0015
; Called from: MON_DO, MON_RUN, RUN_STEP, KEY_SS
;---------------------------------------------------------------
RSTEP:       CLI      ; interrupts on: motor/speech services run between steps
             JSR   >RI_HOOK   ; RI_HOOK: per-step user hook (default RTS)
             LDX   USERFRAME   ; X = user frame
             LDX   $06,X   ; X = user PC
             STX   CURPC   ; remember where this instruction starts (ABORT shows it)
             JSR   SSTEP   ; SSTEP: run it natively if it is a 6800 instruction
             BCC   LE03A   ; C = 0: done, SSTEP already advanced the PC
             LDX   CURPC   ; C = 1: not 6800 - it is a robot opcode
             LDAA  $00,X   ; A = robot opcode
             LDX   #ROBOT_TAB   ; X = dispatch table (op, handler) entries
LE019:       CMPA  $00,X   ; this entry?
             BEQ   LE02A
             INX      ; next 3-byte entry
             INX   
             INX   
             TST   $00,X   ; $00 ends the table
             BNE   LE019
             JSR   >RI_BADOP   ; RI_BADOP: unknown opcode hook (default SEC = stop)
             BCC   LE02E   ; hook returned C = 0: A = length, carry on
             RTS      ; C = 1: report unknown opcode to the run loop
LE02A:       LDX   $01,X   ; X = handler address
             JSR   $00,X   ; call the handler; it returns A = instruction length (0 = PC already set)
LE02E:       LDX   USERFRAME   ; user PC += A
             CLRB  
             ADDA  $07,X
             ADCB  $06,X
             STAA  $07,X
             STAB  $06,X
LE03A:       CLC      ; C = 0: instruction executed
             RTS   
* Robot opcode dispatch table: opcode byte, handler address; $00 ends it.
* 36 of the 59 non-6800 opcodes are robot instructions; the other 23 ($00,$12-$15,$18,
* $1A,$38,$3C,$3D,$65,$6B,$75,$7B,$93,$9D,$A3,$B3,$C7,$CD,$CF,$DD,$ED) go to RI_BADOP.
ROBOT_TAB:   FCB   $02   ; ABORT DRIVE
             FDB   ABT_DRIVE
             FCB   $03   ; ABORT STEERING
             FDB   ABT_STEER
             FCB   $04   ; ABORT ARM
             FDB   ABT_ARM
             FCB   $05   ; ABORT SPEECH
             FDB   ABT_SPEECH
             FCB   $1C   ; BRANCH IF DRIVE BUSY
             FDB   BR_DRIVE
             FCB   $1D   ; BRANCH IF STEERING BUSY
             FDB   BR_STEER
             FCB   $1E   ; BRANCH IF ARM BUSY
             FDB   BR_ARM
             FCB   $1F   ; BRANCH IF SPEECH BUSY
             FDB   BR_SPEECH
             FCB   $21   ; ZERO
             FDB   R_ZERO
             FCB   $3A   ; RETURN TO EXECUTIVE
             FDB   R_EXEC
             FCB   $41   ; ENABLE LIGHT
             FDB   EN_LIGHT
             FCB   $42   ; ENABLE SOUND
             FDB   EN_SOUND
             FCB   $45   ; ENABLE SONAR
             FDB   EN_SONAR
             FCB   $4B   ; ENABLE MOTION
             FDB   EN_MOTION
             FCB   $4E   ; ENABLE DISPLAY
             FDB   EN_DISPLAY
             FCB   $51   ; DISABLE LIGHT
             FDB   DIS_LIGHT
             FCB   $52   ; DISABLE SOUND
             FDB   DIS_SOUND
             FCB   $55   ; DISABLE SONAR
             FDB   DIS_SONAR
             FCB   $5B   ; DISABLE MOTION
             FDB   DIS_MOTION
             FCB   $5E   ; DISABLE DISPLAY
             FDB   DIS_DISPLAY
             FCB   $61   ; SPEAK $00,X
             FDB   SPK_IDX
             FCB   $62   ; SPEAK $00,X, WAIT
             FDB   SPK_IDX_W
             FCB   $71   ; SPEAK $0000
             FDB   SPK_EXT
             FCB   $72   ; SPEAK $0000, WAIT
             FDB   SPK_EXT_W
             FCB   $83   ; CHANGE TO MACHINE LANGUAGE
             FDB   TO_MACHINE
             FCB   $87   ; SLEEP 0 x 10 s
             FDB   R_SLEEP
             FCB   $8F   ; PAUSE 0/16 s
             FDB   R_PAUSE
             FCB   $C3   ; MOVE DRIVE TO  $000 SLOW, WAIT
             FDB   MV_IMM_W
             FCB   $CC   ; MOVE DRIVE TO  $000 SLOW
             FDB   MV_IMM
             FCB   $D3   ; MOVE DRIVE REL + $000 SLOW, WAIT
             FDB   MV_REL_W
             FCB   $DC   ; MOVE DRIVE REL + $000 SLOW
             FDB   MV_REL
             FCB   $E3   ; MOVE ABS $00,X, WAIT
             FDB   MV_IDX_W
             FCB   $EC   ; MOVE ABS $00,X
             FDB   MV_IDX
             FCB   $F3   ; MOVE ABS ($0000), WAIT
             FDB   MV_EXT_W
             FCB   $FC   ; MOVE ABS ($0000)
             FDB   MV_EXT
             FCB   $FD   ; MOVE ALL TO 00 00 00 00 00 00 00
             FDB   MOVE_ALL
             FCB   $00   ; end of table

;---------------------------------------------------------------
; EN_LIGHT - robot op $41: enable the light detector
;
; Selects the eye (POWER bit 7) and powers the sense board (bit 5).
;
; Out:       A = 1 (instruction length)                         (contract)
; Memory:    POWER, POWER_SH
;
; Changes:   A, B, X, flags I N Z V
; Preserves: none   [static + measured: 1 call]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 32,817 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SET
;---------------------------------------------------------------
EN_LIGHT:    LDAB  #$A0   ; bit 7 eye select + bit 5 sense power
             BRA   EN_SET

;---------------------------------------------------------------
; EN_SOUND - robot op $42: enable the sound detector
;
; Clears the eye/ear select (bit 7 = 0 selects the ear) and powers the sense board.
;
; Out:       A = 1                                              (contract)
; Memory:    POWER, POWER_SH
;
; Changes:   A, B, X, flags I N Z V
; Preserves: none   [static + measured: 1 call]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 32,823 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SET
;---------------------------------------------------------------
EN_SOUND:    SEI      ; interrupts off (redundant: PWR_SET masks again)
             NOP   
             LDAB  POWER_SH
             ANDB  #$7F   ; bit 7 = 0: ear selected
             ORAB  #$20   ; sense board power on
             BRA   LE0C5

;---------------------------------------------------------------
; EN_SONAR - robot op $45: power the sonar (POWER bit 1)
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, B, X, flags I N Z V
; Preserves: none   [static + measured: 2 calls]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 32,817 E cycles on every call over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SET
;---------------------------------------------------------------
EN_SONAR:    LDAB  #$02
             BRA   EN_SET

;---------------------------------------------------------------
; EN_MOTION - robot op $4B: power the motion detector (POWER bit 2)
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, B, X, flags I N Z V
; Preserves: none   [static + measured: 2 calls]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 32,817 E cycles on every call over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SET
;---------------------------------------------------------------
EN_MOTION:   LDAB  #$04
             BRA   EN_SET

;---------------------------------------------------------------
; EN_DISPLAY - robot op $4E: power the display (POWER bit 4)
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, B, X, flags I N Z V
; Preserves: none   [static + measured: 2 calls]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 32,813 E cycles on every call over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SET
;---------------------------------------------------------------
EN_DISPLAY:  LDAB  #$10
EN_SET:      ORAB  POWER_SH   ; add the bit(s) to the current power state
LE0C5:       BSR   PWR_SET   ; PWR_SET: write POWER and let it settle
             LDAA  #$01   ; length 1
             RTS   

;---------------------------------------------------------------
; DIS_LIGHT - robot op $51: disable the light detector
;
; Turns the sense board off only if the eye is the selected input; if the ear is
; selected the sense board stays on (disabling the unselected detector is a no-op).
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, B, X, flags I N Z V ; on some paths: X
; Preserves: none   [static + measured: 1 call, 0/1 branches]
; Stack:     2 bytes max, including callees (observed 0)
; Cycles:    observed 17 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SET
;---------------------------------------------------------------
DIS_LIGHT:   LDAB  POWER_SH
             BITB  #$80   ; eye selected?
             BEQ   RET_LEN1   ; no: leave the sound detector running
             LDAB  #$DF   ; clear bit 5: sense board off
             BRA   DIS_CLR

;---------------------------------------------------------------
; DIS_SOUND - robot op $52: disable the sound detector
;
; Turns the sense board off only if the ear is the selected input.
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, B, X, flags I N Z V ; on some paths: X
; Preserves: none   [static + measured: 1 call, 0/1 branches]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 32,827 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SET
;---------------------------------------------------------------
DIS_SOUND:   LDAB  POWER_SH
             BITB  #$80   ; eye selected?
             BNE   RET_LEN1   ; yes: leave the light detector running
             LDAB  #$DF   ; clear bit 5: sense board off
             BRA   DIS_CLR

;---------------------------------------------------------------
; DIS_SONAR - robot op $55: sonar power off (POWER bit 1)
;
; The manual's table names $55 "Disable Motion"; the ROM clears the sonar bit.
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, B, X, flags I N Z V
; Preserves: none   [static + measured: 1 call]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 32,817 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SET
;---------------------------------------------------------------
DIS_SONAR:   LDAB  #$FD
             BRA   DIS_CLR

;---------------------------------------------------------------
; DIS_MOTION - robot op $5B: motion detector power off (POWER bit 2)
;
; The manual's table names $5B "Disable Ultrasonic"; the ROM clears the motion bit.
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, B, X, flags I N Z V
; Preserves: none   [static + measured: 1 call]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 32,817 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SET
;---------------------------------------------------------------
DIS_MOTION:  LDAB  #$FB
             BRA   DIS_CLR

;---------------------------------------------------------------
; DIS_DISPLAY - robot op $5E: display power off (POWER bit 4)
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, B, X, flags I N Z V
; Preserves: none   [static + measured: 1 call]
;            measured: B written but equal at exit on every call
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 32,813 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SET
;---------------------------------------------------------------
DIS_DISPLAY: LDAB  #$EF
DIS_CLR:     ANDB  POWER_SH   ; remove the bit from the current power state
             BSR   PWR_SET   ; PWR_SET: write POWER and let it settle
RET_LEN1:    LDAA  #$01   ; length 1
             RTS   

;---------------------------------------------------------------
; PWR_SET - write the power-control port and wait for it to settle
;
; Writes POWER and its shadow inside an interrupt-masked window, then idles
; $1000 x 8 cycles (about 37 ms) so a newly powered board can settle.
;
; In:        B = new POWER value
; Memory:    POWER, POWER_SH
;
; Changes:   X, flags I N Z V
; Preserves: A, B   [static + measured: 12 calls, 1/1 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 32,792 E cycles on every call over 12 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: EN_LIGHT, EN_SOUND, EN_SONAR, EN_MOTION, EN_DISPLAY, DIS_LIGHT, DIS_SOUND, DIS_SONAR, DIS_MOTION, DIS_DISPLAY
;---------------------------------------------------------------
PWR_SET:     SEI      ; mask IRQs: the IRQ code also rewrites POWER from the shadow
             NOP      ; (NOP after SEI: Heath's habit throughout this ROM)
             STAB  POWER
             STAB  POWER_SH   ; keep the shadow in step
             CLI      ; end of masked window
             LDX   #$1000   ; about 37 ms settling delay
LE0FE:       DEX   
             BNE   LE0FE
             RTS   

;---------------------------------------------------------------
; R_EXEC - robot op $3A: return to the Executive ("ready")
;
; Abandons the program: jumps to the Executive restart, which resets the stack.
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call]
; Stack:     9 bytes max, including callees (observed 0)
; Cycles:    observed 81 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      tail-JMP to EXEC
; Calls:     EXEC
; Called from: PB_BACKUP, PB_RETURN, PTR_BACK3
;---------------------------------------------------------------
R_EXEC:      JMP   EXEC

;---------------------------------------------------------------
; MV_IMM_W - robot op $C3: move motor (immediate word), wait
;
; Same as MV_IMM but waits until the motor's channel is idle again.
;
; Out:       A = 3                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 5 calls]
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 49,390-710,726 E cycles over 5 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into MOT_START
; Calls:     CCB_BUILD, DRV_SETUP
;---------------------------------------------------------------
MV_IMM_W:    LDAA  #$07   ; wait for every channel bit (masked to this channel later)
             BRA   MV_IMM_GO

;---------------------------------------------------------------
; MV_IMM - robot op $CC: move motor (immediate word), continue
;
; The two bytes after the opcode are the motor word mmmssDdd dddddddd
; (motor, speed, direction, 10-bit position or drive distance).
;
; Out:       A = 3                                              (contract)
; Memory:    MOTWORD, WAITMASK; starts the motor via MOT_START
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 3 calls]
;            measured: B written but equal at exit on every call
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 792-838 E cycles over 3 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into MOT_START
; Calls:     CCB_BUILD, DRV_SETUP
;---------------------------------------------------------------
MV_IMM:      CLRA     ; 0 = do not wait
MV_IMM_GO:   STAA  WAITMASK
             LDX   USERFRAME   ; X = user frame
             LDX   $06,X   ; X = user PC (the opcode)
             LDX   $01,X   ; motor word from the two operand bytes
             STX   MOTWORD
             LDAA  #$03   ; length 3
             BRA   MOT_START   ; MOT_START

;---------------------------------------------------------------
; MV_EXT_W - robot op $F3: move motor, word at an extended address, wait
;
; Out:       A = 3                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call]
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 3,470,427 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into MOT_START
; Calls:     CCB_BUILD, DRV_SETUP
;---------------------------------------------------------------
MV_EXT_W:    LDAA  #$07
             BRA   MV_EXT_GO

;---------------------------------------------------------------
; MV_EXT - robot op $FC: move motor, word at an extended address, continue
;
; The operand is the address of the motor word, so a program can build or
; change the word in RAM.  Emulator: F3 0500 with $D0,$40 at $0500 moved the
; head to $40.
;
; Out:       A = 3                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call]
;            measured: B written but equal at exit on every call
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 844 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into MOT_START
; Calls:     CCB_BUILD, DRV_SETUP
;---------------------------------------------------------------
MV_EXT:      CLRA  
MV_EXT_GO:   STAA  WAITMASK
             LDX   USERFRAME
             LDX   $06,X
             LDX   $01,X   ; X = operand address
             LDX   $00,X   ; motor word from that address
             STX   MOTWORD
             LDAA  #$03
             BRA   MOT_START

;---------------------------------------------------------------
; MV_IDX_W - robot op $E3: move motor, word at offset,X, wait
;
; Out:       A = 2                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call]
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 4,048,527 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into MOT_START
; Calls:     CCB_BUILD, DRV_SETUP
;---------------------------------------------------------------
MV_IDX_W:    LDAA  #$07
             BRA   LE138

;---------------------------------------------------------------
; MV_IDX - robot op $EC: move motor, word at offset,X, continue
;
; Adds the unsigned offset byte to the user's X register (from the frame) and
; takes the motor word from there.
;
; Out:       A = 2                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call]
;            measured: B written but equal at exit on every call
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 870 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into MOT_START
; Calls:     CCB_BUILD, DRV_SETUP
;---------------------------------------------------------------
MV_IDX:      CLRA  
LE138:       STAA  WAITMASK
             LDX   USERFRAME   ; X = user frame
             LDAA  $05,X   ; A:B = user X (low, high)
             LDAB  $04,X
             LDX   $06,X   ; X = user PC
             ADDA  $01,X   ; + unsigned offset byte
             ADCB  #$00
             STAA  MOTWORDL   ; build the address in MOTWORD (used as scratch)
             STAB  MOTWORD
             LDX   MOTWORD   ; X = user X + offset
             LDX   $00,X   ; fetch the motor word
             STX   MOTWORD
             LDAA  #$02   ; length 2
             BRA   MOT_START

;---------------------------------------------------------------
; MV_REL_W - robot op $D3: move motor relative, wait
;
; Out:       A = 3                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call]
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 902,562 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into MOT_START
; Calls:     CCB_BUILD, DRV_SETUP
;---------------------------------------------------------------
MV_REL_W:    LDAA  #$07
             BRA   LE15F

;---------------------------------------------------------------
; MV_REL - robot op $DC: move motor relative, continue
;
; Turns a relative word into an absolute one: target = position byte -/+ the
; low 8 bits of the distance (D = 1 subtracts), 8-bit wraparound, bits 9-8 are
; ignored.  A target that wraps past 0 lands high, so the motor runs to its top
; limit - the manual's "reverse and go all the way to the other end".  Emulator:
; head at $61, D3 CC 70 (-$70) gave target $F1 and the head stopped at $C2.
; Drive words (motor 0) pass through unchanged: drive distances are always
; relative.
;
; Out:       A = 3                                              (contract)
; Memory:    MOTWORD/MOTWORDL rewritten to the absolute target
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 3 calls, 2/2 branches]
;            measured: B written but equal at exit on every call
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 263-918 E cycles over 3 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into MOT_START
; Calls:     CCB_BUILD, DRV_SETUP
;---------------------------------------------------------------
MV_REL:      CLRA  
LE15F:       STAA  WAITMASK
             LDX   USERFRAME
             LDX   $06,X
             LDX   $01,X
             STX   MOTWORD   ; motor word from the operand
             LDAA  MOTWORD
             TAB      ; B keeps the high byte for the D bit
             ROLA     ; rotate mmm (bits 7-5) round to bits 2-0
             ROLA  
             ROLA  
             ROLA  
             ANDA  #$07   ; A = motor number
             BEQ   LE192   ; drive: distance stays relative
             DECA     ; position byte address = $0000 + motor - 1
             PSHA     ; build X = $00,(m-1) through the stack
             CLRA  
             PSHA  
             TSX      ; X = the position byte's address
             LDX   $00,X
             INS      ; drop the scratch word
             INS   
             LDAA  $00,X   ; A = current position
             BITB  #$04   ; D bit (bit 10 of the word)?
             BEQ   LE18C
             SUBA  MOTWORDL   ; D = 1: position - distance
             BRA   LE18F
LE18C:       ADDA  MOTWORDL   ; D = 0: position + distance
LE18F:       STAA  MOTWORDL   ; absolute target, 8-bit wrap
LE192:       LDAA  #$03   ; length 3

;---------------------------------------------------------------
; MOT_START - start (and optionally wait for) the move in MOTWORD
;
; Common motor start for every move opcode, MOVE_LIST and the Learn-mode
; MOT_GO.  The motor field picks the channel: 0 drive, 7 steering (CCB_STEER,
; busy bit 1), 1-6 the shared arm channel (CCB_ARM, busy bit 2).  It first waits
; for that channel to go idle - so a second arm command queues behind the first
; (the manual's "one arm motor at a time") - then builds the control block, sets
; the busy bit (the IRQ motor service then steps the motor) and, if WAITMASK
; asks for it, waits for the bit to clear.
;
; In:        MOTWORD/MOTWORDL = absolute motor word; WAITMASK = 0 or busy bits
;            A = value to hand back (the instruction length)
; Out:       A = same value                                     (contract)
; Memory:    BUSY, ABORTREQ, BUSYBIT, WAITMASK, a CCB, DRVTARGET, CTRL
;
; Changes:   B, X, flags H I N Z V C
; Preserves: A   [static + measured: 21 calls, 4/5 branches]
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 4,184-17,072,809 E cycles over 21 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     CCB_BUILD, DRV_SETUP
; Called from: MOVE_ALL, MOVE_LIST, MOT_GO
;---------------------------------------------------------------
MOT_START:   PSHA     ; keep the instruction length
             LDAB  WAITMASK
             LDAA  MOTWORD   ; motor field mmm
             ANDA  #$E0
             BEQ   MS_DRIVE   ; 000 = drive
             CMPA  #$E0   ; 111 = steering
             BNE   MS_ARM
             LDX   #$0EE4   ; steering control block
             ANDB  #$02   ; wait only if the caller wants to
             STAB  WAITMASK
             LDAB  #$02   ; steering busy bit
             BRA   MS_CHAN
MS_ARM:      LDX   #$0EF0   ; motors 1-6 share the arm control block
             ANDB  #$04   ; wait only if the caller wants to
             STAB  WAITMASK
             LDAB  #$04   ; arm busy bit
MS_CHAN:     STAB  BUSYBIT
MS_WAITFREE: BITB  BUSY   ; wait until the channel is idle (IRQs on)
             BNE   MS_WAITFREE
             BSR   CCB_BUILD   ; CCB_BUILD: fill the control block for this move
             BRA   MS_BUSY
MS_DRIVE:    ANDB  #$01   ; drive: wait only if the caller wants to
             STAB  WAITMASK
             LDAB  #$01
MS_DRVFREE:  BITB  BUSY   ; wait for the previous drive move to end
             BNE   MS_DRVFREE
             SEI      ; masked window: clear stale drive abort requests
             NOP   
             LDAA  ABORTREQ
             ANDA  #$EE   ; bits 4 and 0
             STAA  ABORTREQ
             CLI   
             LDAB  #$11   ; drive busy = distance (bit 0) + ramp (bit 4)
             STAB  BUSYBIT
             JSR   DRV_SETUP   ; DRV_SETUP: distance, odometer, A = wanted DRIVE value
             STAA  DRVTARGET   ; the 1024 Hz ramp walks DRIVE toward this
MS_BUSY:     LDAA  BUSYBIT   ; masked window: mark the channel busy - the IRQ service starts now
             SEI   
             NOP   
             ORAA  BUSY
             STAA  BUSY
             CLI   
             PULA     ; recover the length
             LDAB  WAITMASK
MS_WAITDONE: BITB  BUSY   ; wait while a waited-on bit is still busy
             BNE   MS_WAITDONE
             RTS   

;---------------------------------------------------------------
; MOVE_ALL - robot op $FD: move all seven position motors, absolute
;
; Seven position bytes follow the opcode (extend, shoulder, rotate, pivot,
; gripper, head, steering).  Falls into MOVE_LIST.
;
; Out:       A = 8                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call]
; Stack:     7 bytes max, including callees (observed 7)
; Cycles:    observed 5,197,424 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into MOVE_LIST
; Calls:     MOT_START
;---------------------------------------------------------------
MOVE_ALL:    LDX   USERFRAME   ; X = user frame
             LDX   $06,X   ; X = user PC
             INX      ; X = first position byte

;---------------------------------------------------------------
; MOVE_LIST - move motors 1-7 in turn to the 7 positions at X
;
; Builds word $28xx (motor 1, slow) and adds $20 per motor up to $E8xx
; (steering); each move waits for its channel, so the motors run one after
; another at slow speed.  Used by MOVE_ALL and twice by R_ZERO.
;
; In:        X = 7 position bytes
; Out:       A = 8                                              (contract)
; Memory:    MALL_PTR, MOTWORD, WAITMASK; moves the motors
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 2 calls, 1/1 branches]
; Stack:     7 bytes max, including callees (observed 7)
; Cycles:    observed 13,197,633-58,455,135 E cycles over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     MOT_START
; Called from: R_ZERO
;---------------------------------------------------------------
MOVE_LIST:   STX   MALL_PTR
             LDAA  #$28   ; motor 1 (extend), speed 01 slow, D = 0
ML_LOOP:     STAA  MOTWORD
             LDX   MALL_PTR
             LDAA  $00,X   ; next position byte
             INX   
             STX   MALL_PTR
             STAA  MOTWORDL   ; target
             LDAA  #$06   ; wait on arm (4) and steering (2) - each move completes in turn
             STAA  WAITMASK
             JSR   MOT_START   ; MOT_START: run this motor to its position
             LDAA  MOTWORD
             ADDA  #$20   ; next motor number
             BITA  #$E0   ; past steering (111) the field wraps to 000: done
             BNE   ML_LOOP
             LDAA  #$08   ; length 8
             RTS   

;---------------------------------------------------------------
; CCB_BUILD - fill a motor control block from MOTDESC and the motor word
;
; Picks descriptor E29F + 11 x motor (motors 1-7) and copies its first 7 bytes
; into the block.  The speed field picks the step rate byte (descriptor byte 8,
; 9 or 10 for slow, medium, fast; speed 00, undocumented, falls on byte 7 - the
; select byte - giving a very slow $40/$80/$100 ticks per step).  Direction and
; distance come from comparing the target with the position byte, and the
; distance in units is scaled to steps by shifting it once per bit of the
; steps-per-unit mask.  Finally the arm motor's select bit goes to CTRL.
;
; In:        X = control block, A = motor word & $E0, MOTWORD/MOTWORDL
; Memory:    CCB_PTR, CB_DST, CB_SRC, the block, CTRL, CTRL_SH
;
; Changes:   A, B, flags H I N Z V C
; Preserves: X   [static + measured: 46 calls, 4/4 branches]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 621-719 E cycles over 46 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     CB_COPY
; Called from: MV_IMM_W, MV_IMM, MV_EXT_W, MV_EXT, MV_IDX_W, MV_IDX, MV_REL_W, MV_REL, MOT_START
;---------------------------------------------------------------
CCB_BUILD:   STX   CCB_PTR   ; remember the block
             STX   CB_DST   ; copy destination
             LSRA     ; A = motor x 8 (mmm000)
             LSRA  
             TAB   
             LSRB     ; B = motor x 2
             LSRB  
             ABA      ; A = motor x 10
             LSRB     ; B = motor
             ABA      ; A = motor x 11
             CLRB  
             ADDA  #LO(LE29D+2)   ; + (MOTDESC - 11): the descriptor for this motor
             ADCB  #HI(LE29D+2)
             STAA  CB_SRCL
             STAB  CB_SRC   ; CB_SRC -> descriptor
             LDAB  #$07   ; copy bytes 0-6
             BSR   CB_COPY   ; CB_COPY
             LDX   CB_SRC   ; X -> descriptor byte 7
             LDAA  $00,X   ; byte 7 = CTRL select bit(s) for this motor
             PSHA  
             LDAA  MOTWORD   ; speed field ss
             ANDA  #$18
CB_SPEED:    BEQ   CB_RATE   ; step to byte 7 + ss
             INX   
             SUBA  #$08
             BRA   CB_SPEED
CB_RATE:     LDAB  $00,X   ; ticks per step for this speed
             LDX   CCB_PTR
             STAB  $07,X   ; +7 countdown
             STAB  $08,X   ; +8 reload
             LDX   $04,X   ; X -> position byte
             LDAA  $00,X   ; current position
             SUBA  MOTWORDL   ; - target
             BCC   CB_DOWN   ; no borrow: target <= position, run down
             CLRB     ; target above: direction 0 (position increases)
             NEGA     ; A = target - position
             BRA   CB_DIR
CB_DOWN:     LDAB  #$04   ; direction 4 (position decreases)
CB_DIR:      LDX   CCB_PTR
             STAB  $09,X   ; +9 = direction, phase index 0
             STAA  $0B,X   ; +$B = distance in units (low byte)
             CLR   $0A,X   ; +$A = 0 (high byte)
             LDAA  $01,X   ; steps-per-unit mask ($1F, $07 or $03)
CB_SCALE:    ASL   $0B,X   ; distance x 2 per mask bit: units -> steps
             ROL   $0A,X
             LSRA  
             BNE   CB_SCALE
             PULA     ; select byte for CTRL
             TSTA  
             BEQ   LE290   ; steering has none
             SEI      ; masked window: CTRL bits 7/6 pick which motor of a phase pair is driven
             NOP   
             LDAB  CTRL_SH
             ANDB  #$3F   ; keep the clock-register/strobe bits
             ABA   
             STAA  CTRL_SH
             STAA  CTRL
             CLI      ; end of masked window
LE290:       RTS   

;---------------------------------------------------------------
; CB_COPY - copy B bytes from (CB_SRC) to (CB_DST), advancing both
;
; In:        B = count, CB_SRC, CB_DST
; Out:       CB_SRC, CB_DST advanced by B                       (contract)
;
; Changes:   A, B, X, flags N Z V C ; on some paths: A, B, X
; Preserves: none   [static + measured: 46 calls, 1/1 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 382 E cycles on every call over 46 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: CCB_BUILD
;---------------------------------------------------------------
CB_COPY:     TSTB  
             BEQ   LE2A9
             LDX   CB_SRC
             LDAA  $00,X
             INX   
             STX   CB_SRC
LE29D:       LDX   CB_DST   ; the copy destination pointer (LE29D+2 = MOTDESC-11 is only an address)
             STAA  $00,X
             INX   
             STX   CB_DST
             DECB  
             BRA   CB_COPY
LE2A9:       RTS   
* Motor descriptors, 11 bytes per motor 1-7.  Bytes 0-6 are copied into the 12-byte
* control block (CCB_STEER / CCB_ARM), which the 1024 Hz IRQ motor service steps:
* +0  phase nibble mask: $F0 upper or $0F lower half of the port
* +1  steps per position unit - 1 ($1F 32, $07 8, $03 4); also the scale shift
* +2  phase port, word ($C260 / $C280)
* +4  address of the position byte, word ($0000-$0006)
* +6  limit switch mask on $C260 ($00 = no switch).  The IRQ service (LF0EF) checks
* bits 6-4 while the position decreases (a closed switch zeroes the position byte:
* automatic re-homing) and bits 3-1 while it increases, so to the ROM bits 6-4 are
* the position-0 end.  The brief/emulator names (bit 6 steer CW, 5 arm up) put the
* steering and shoulder switches the other way round - unresolved.
* Descriptor only:
* +7  CTRL select bits ($80 rotate/shoulder/head, $40 pivot/gripper/extend, $00 steering)
* +8  ticks per step, slow   +9 medium   +10 fast  (1024 Hz ticks)
* Control block only: +7 tick countdown, +8 reload, +9 phase index (bits 1-0) and
* direction (bit 2 = decreasing), +$A/+$B steps still to go.
* Emulator: head 15 units took 2.82/1.88/1.41 s at slow/medium/fast = 480 steps x 6/4/3 ticks.
MOTDESC:     FCB   $F0,$1F,$C2,$80,$00,$00,$00,$40,$06,$04,$03   ; motor 1 extend:   upper $C280, 32 steps/unit, pos $0000, no switch, sel $40, 6/4/3
             FCB   $0F,$1F,$C2,$80,$00,$01,$24,$80,$06,$03,$02   ; motor 2 shoulder: lower $C280, 32 steps/unit, pos $0001, switches $24, sel $80, 6/3/2
             FCB   $0F,$07,$C2,$60,$00,$02,$00,$80,$06,$03,$02   ; motor 3 rotate:   lower $C260, 8 steps/unit, pos $0002, no switch, sel $80, 6/3/2
             FCB   $0F,$07,$C2,$60,$00,$03,$00,$40,$07,$05,$03   ; motor 4 pivot:    lower $C260, 8 steps/unit, pos $0003, no switch, sel $40, 7/5/3
             FCB   $0F,$03,$C2,$80,$00,$04,$00,$40,$06,$03,$02   ; motor 5 gripper:  lower $C280, 4 steps/unit, pos $0004, no switch, sel $40, 6/3/2
             FCB   $F0,$1F,$C2,$80,$00,$05,$12,$80,$06,$04,$03   ; motor 6 head:     upper $C280, 32 steps/unit, pos $0005, switches $12, sel $80, 6/4/3
             FCB   $F0,$07,$C2,$60,$00,$06,$48,$00,$06,$03,$02   ; motor 7 steering: upper $C260, 8 steps/unit, pos $0006, switches $48, sel $00, 6/3/2

;---------------------------------------------------------------
; DRV_SETUP - prepare a drive move from the motor word
;
; Loads the 10-bit encoder distance into DRVDIST (counted down by the drive
; encoder IRQ), clears the travelled counter DRVCOUNT and returns the DRIVE
; value to ramp to: speed byte from DRV_SPEEDS, bit 7 set for D = 1 (reverse).
;
; In:        MOTWORD/MOTWORDL = drive word 000ssDdd dddddddd
; Out:       A = wanted DRIVE value                             (contract)
; Memory:    DRVDIST, DRVSPD, DRVCOUNT
;
; Changes:   A, B, X, flags N Z V C
; Preserves: none   [static + measured: 2 calls, 1/2 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 104 E cycles on every call over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: MV_IMM_W, MV_IMM, MV_EXT_W, MV_EXT, MV_IDX_W, MV_IDX, MV_REL_W, MV_REL, MOT_START
;---------------------------------------------------------------
DRV_SETUP:   LDAB  MOTWORD   ; distance bits 9-8
             ANDB  #$03
             STAB  DRVDIST
             LDAB  MOTWORDL   ; distance bits 7-0
             STAB  $0EFE
             LDAA  MOTWORD
             LDX   #DRV_SPEEDS
             ANDA  #$18   ; speed field ss
             LSRA     ; to 0-3
             LSRA  
             LSRA  
             STAA  DRVSPD
DS_IDX:      BEQ   DS_SPEED
             INX   
             DECA  
             BRA   DS_IDX
DS_SPEED:    LDAA  $00,X   ; DRIVE value for this speed
             LDAB  MOTWORD
             BITB  #$04   ; D bit: reverse?
             BEQ   DS_CLR
             ORAA  #$80   ; bit 7 = reverse
DS_CLR:      CLR   >DRVCOUNT   ; restart the travelled-distance counter
             CLR   >$0008
             RTS   
DRV_SPEEDS:  FCB   $00,$64,$72,$7F   ; DRIVE values for ss = 00 off, 01 on+$24, 10 on+$32, 11 on+$3F

;---------------------------------------------------------------
; SPK_IDX_W - robot op $62: speak the phrase at offset,X and wait
;
; Out:       A = 2                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call]
; Stack:     5 bytes max, including callees (observed 4)
; Cycles:    observed 396,733 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     SPK_PUSH
;---------------------------------------------------------------
SPK_IDX_W:   LDAA  #$08   ; wait on the speech busy bit
             BRA   SPK_IDX_GO

;---------------------------------------------------------------
; SPK_IDX - robot op $61: speak the phrase at offset,X, continue
;
; Out:       A = 2                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call]
;            measured: B written but equal at exit on every call
; Stack:     5 bytes max, including callees (observed 4)
; Cycles:    observed 80,245 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     SPK_PUSH
;---------------------------------------------------------------
SPK_IDX:     CLRA  
SPK_IDX_GO:  STAA  WAITMASK
             LDAA  #$02   ; length 2, popped at the end
             PSHA  
             LDX   USERFRAME
             LDAA  $05,X   ; A:B = user X (low, high)
             LDAB  $04,X
             LDX   $06,X
             ADDA  $01,X   ; + unsigned offset: phrase address
             ADCB  #$00
             BRA   SPK_START

;---------------------------------------------------------------
; SPK_EXT_W - robot op $72: speak the phrase at an extended address, wait
;
; Out:       A = 3                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 3 calls]
; Stack:     5 bytes max, including callees (observed 4)
; Cycles:    observed 396,362-1,731,038 E cycles over 3 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     SPK_PUSH
;---------------------------------------------------------------
SPK_EXT_W:   LDAA  #$08
             BRA   SPK_EXT_GO

;---------------------------------------------------------------
; SPK_EXT - robot op $71: speak the phrase at an extended address, continue
;
; Out:       A = 3                                              (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 2 calls]
;            measured: B written but equal at exit on every call
; Stack:     5 bytes max, including callees (observed 4)
; Cycles:    observed 80,238 E cycles on every call over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     SPK_PUSH
;---------------------------------------------------------------
SPK_EXT:     CLRA  
SPK_EXT_GO:  STAA  WAITMASK
             LDAA  #$03   ; length 3, popped at the end
             PSHA  
             LDX   USERFRAME
             LDX   $06,X
             LDAA  $02,X   ; A:B = phrase address (low, high)
             LDAB  $01,X
             BRA   SPK_START

;---------------------------------------------------------------
; SPEAK_AB - start speaking the phrase at B:A (ROM entry, used by the start-up
; "HEro 1" greeting)
;
; Pushes a dummy "length" so it shares the exit of the speak opcodes.  Powers
; the speech board, idles about 89 ms for it to come up, hands the phrase to
; the speech engine (which says the first phoneme now and the rest on
; speech-request interrupts), sets busy bit 3 and waits if WAITMASK bit 3 is
; set.  There is no wait for a phrase already playing: a new phrase simply
; replaces it (resets the BF nesting stack).
;
; In:        B:A = phrase address (high, low); WAITMASK
; Out:       A = the value pushed first (instruction length)    (contract)
; Memory:    POWER, POWER_SH, BUSY, speech pointers
;
; Changes:   B, X, flags H I N Z V C ; on some paths: B
; Preserves: A   [static + measured: 65 calls, 2/3 branches]
; Stack:     5 bytes max, including callees (observed 4)
; Cycles:    observed 80,204 E cycles on every call over 65 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     SPK_PUSH
; Called from: SAY_READY
;---------------------------------------------------------------
SPEAK_AB:    PSHA     ; dummy length = A (meaningless to this caller)
SPK_START:   PSHA     ; save phrase address low byte
             LDAA  #$08   ; speech board power bit
             SEI      ; masked window: POWER and shadow together
             NOP   
             ORAA  POWER_SH
             STAA  POWER_SH
             STAA  POWER
             CLI      ; end of masked window
             LDX   #$2710   ; 10000 x 8 cycles = 89 ms for the SC-01 to power up
SPK_DELAY:   DEX   
             BNE   SPK_DELAY
             PULA     ; A = phrase address low byte
             LDX   SPK_BASE   ; X = bottom of the speech nesting stack
             JSR   SPK_PUSH   ; store B:A there and say the first phoneme
             BCS   SPK_DONE   ; C = 1: phrase was empty (FF straight away)
             LDAA  #$08   ; masked window: speech busy
             SEI   
             NOP   
             ORAA  BUSY
             STAA  BUSY
             CLI   
             LDAB  WAITMASK
SPK_WAIT:    BITB  BUSY   ; wait for the phrase to finish if asked to
             BNE   SPK_WAIT
SPK_DONE:    PULA     ; A = instruction length
             RTS   

;---------------------------------------------------------------
; ABT_DRIVE - robot op $02: stop the drive motor
;
; Sets the ramp target to stop and requests aborts for the distance and ramp
; bits; returns once the IRQ service has cleared them.  Also called by SLEEP.
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, flags I N Z V
; Preserves: B, X   [static + measured: 2 calls]
; Stack:     1 byte max, including callees (observed 1)
; Cycles:    observed 33-105,306 E cycles over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: R_SLEEP
;---------------------------------------------------------------
ABT_DRIVE:   LDAA  #$3F   ; ramp target: motor off
             STAA  DRVTARGET
             LDAA  #$11   ; drive distance (0) + ramp (4) bits
             BRA   ABT_CHAN

;---------------------------------------------------------------
; ABT_STEER - robot op $03: stop the steering motor
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, flags I N Z V
; Preserves: B, X   [static + measured: 5 calls]
; Stack:     1 byte max, including callees (observed 1)
; Cycles:    observed 26-8,608 E cycles over 5 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: R_SLEEP, MANUAL, MAN_LOOP, REC_FLUSH, ROOM_CHK
;---------------------------------------------------------------
ABT_STEER:   LDAA  #$02
             BRA   ABT_CHAN

;---------------------------------------------------------------
; ABT_ARM - robot op $04: stop the arm channel (head, shoulder, extend,
; rotate, pivot, gripper)
;
; Sets the channel's bit in ABORTREQ if it is busy; the IRQ motor service
; zeroes the step count and drops the busy bit on its next step.  Waits for
; that, so the motor is stopped when this returns.
;
; In:        (ABT_CHAN) A = busy bit(s)
; Out:       A = 1                                              (contract)
; Memory:    ABORTREQ
;
; Changes:   A, flags I N Z V
; Preserves: B, X   [static + measured: 425 calls, 2/2 branches]
; Stack:     1 byte max, including callees (observed 1)
; Cycles:    observed 22-73,802 E cycles over 425 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: R_SLEEP, LEARN, LRN_LOOP, MANUAL, MAN_LOOP, REC_FLUSH, ROOM_CHK
;---------------------------------------------------------------
ABT_ARM:     LDAA  #$04
ABT_CHAN:    SEI      ; masked window while testing BUSY
             NOP   
             BITA  BUSY
             BEQ   ABT_DONE   ; not running: nothing to abort
             PSHA  
             ORAA  ABORTREQ   ; request the abort
             STAA  ABORTREQ
             PULA  
             CLI      ; end of masked window
ABT_WAIT:    BITA  BUSY   ; wait for the IRQ service to stop it
             BNE   ABT_WAIT
             BRA   ABT_DONE

;---------------------------------------------------------------
; ABT_SPEECH - robot op $05: stop speech
;
; Cuts the speech board's power and clears the speech busy bit at once.
;
; Out:       A = 1                                              (contract)
; Memory:    POWER, POWER_SH, BUSY
;
; Changes:   A, B, flags I N Z V
; Preserves: X   [static + measured: 2 calls]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 40 E cycles on every call over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: R_SLEEP
;---------------------------------------------------------------
ABT_SPEECH:  LDAA  #$F7   ; clear busy bit 3
             LDAB  #$F7   ; clear POWER bit 3 (speech power)
             SEI      ; masked window: power and busy change together
             NOP   
             ANDB  POWER_SH
             STAB  POWER_SH
             STAB  POWER
             NOP   
             ANDA  BUSY
             STAA  BUSY
ABT_DONE:    CLI      ; end of masked window
             LDAA  #$01   ; length 1
             RTS   

;---------------------------------------------------------------
; BR_DRIVE - robot op $1C: branch if the drive is busy
;
; Out:       A = 2 not taken, 0 taken (PC set)                  (contract)
;
; Changes:   A, B, X, flags H N Z V C ; on some paths: B, X
; Preserves: none   [static + measured: 1,717 calls]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 20-91 E cycles over 1,717 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
;---------------------------------------------------------------
BR_DRIVE:    LDAA  #$01
             BRA   BR_TEST

;---------------------------------------------------------------
; BR_STEER - robot op $1D: branch if the steering is busy
;
; Out:       A = 2 not taken, 0 taken (PC set)                  (contract)
;
; Changes:   A, B, X, flags H N Z V C ; on some paths: B, X
; Preserves: none   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
;---------------------------------------------------------------
BR_STEER:    LDAA  #$02
             BRA   BR_TEST

;---------------------------------------------------------------
; BR_ARM - robot op $1E: branch if the arm channel is busy
;
; Out:       A = 2 not taken, 0 taken (PC set)                  (contract)
;
; Changes:   A, B, X, flags H N Z V C ; on some paths: B, X
; Preserves: none   [static + measured: 9,595 calls]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 20-91 E cycles over 9,595 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
;---------------------------------------------------------------
BR_ARM:      LDAA  #$04
             BRA   BR_TEST

;---------------------------------------------------------------
; BR_SPEECH - robot op $1F: branch if speech is busy
;
; Like a 6800 branch: target = address of the next instruction + signed
; offset.  "1E FE" waits for the arm (emulator: a head move then 1E FE looped
; on itself until the move ended).
;
; In:        (BR_TEST) A = busy bit to test
; Out:       A = 2 not taken, 0 taken (user PC already set)     (contract)
; Memory:    user frame PC
;
; Changes:   A, B, X, flags H N Z V C ; on some paths: B, X
; Preserves: none   [static + measured: 746 calls, 1/2 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 16-87 E cycles over 746 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
;---------------------------------------------------------------
BR_SPEECH:   LDAA  #$08
BR_TEST:     BITA  BUSY   ; channel busy?
             BNE   BR_TAKE
             LDAA  #$02   ; no: just step over the 2-byte instruction
             RTS   
BR_TAKE:     LDX   USERFRAME
             LDX   $06,X
             TST   $01,X   ; offset negative?
             BMI   BR_BACK
             LDX   USERFRAME
             LDAA  $07,X   ; A:B = user PC
             LDAB  $06,X
             LDX   $06,X
             ADDA  $01,X   ; + offset, high byte 0
             ADCB  #$00
             BRA   BR_SET
BR_BACK:     LDX   USERFRAME
             LDAA  $07,X
             LDAB  $06,X
             LDX   $06,X
             ADDA  $01,X   ; + offset, high byte $FF (sign extended)
             ADCB  #$FF
BR_SET:      ADDA  #$02   ; + 2: relative to the next instruction
             ADCB  #$00
             LDX   USERFRAME
             STAA  $07,X   ; user PC = branch target
             STAB  $06,X
             CLRA     ; length 0: PC already set
             RTS   

;---------------------------------------------------------------
; TO_MACHINE - robot op $83: change to Machine Language
;
; Clears ROBOTMODE; the run loop then runs the rest natively at full speed
; until an SWI ($3F) sets it again (see SS_SWI).
;
; Out:       A = 1                                              (contract)
;
; Changes:   A, flags N Z V C
; Preserves: B, X   [static + measured: 1 call]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 13 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
;---------------------------------------------------------------
TO_MACHINE:  CLR   ROBOTMODE
             LDAA  #$01
             RTS   

;---------------------------------------------------------------
; R_ZERO - robot op $21: initialise every position motor
;
; Pretends every motor is at its top end (writes the maxima to $0000-$0006),
; then moves all to 0: each runs the full travel downward and either stalls at
; its stop or hits its low-end limit switch, which zeroes the position byte.
; Then moves to the rest pose 00 00 4D 00 00 62 49.  Head uses $C9, above the
; manual's $C2 range, for margin (inference).  Emulator: about 120 s, ending
; with positions 00 00 4D 00 00 62 for motors 1-6.
;
; Out:       A = 1                                              (contract)
; Memory:    $0000-$0006; moves all seven motors
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call]
; Stack:     9 bytes max, including callees (observed 9)
; Cycles:    observed 71,652,841 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     MOVE_LIST
;---------------------------------------------------------------
R_ZERO:      LDAA  #$75   ; gripper max
             STAA  $04
             LDAA  #$A5   ; pivot max
             STAA  $03
             LDAA  #$93   ; rotate max
             STAA  $02
             LDAA  #$98   ; extend max
             STAA  $00
             LDAA  #$86   ; shoulder max
             STAA  $01
             LDAA  #$C9   ; head (above the $C2 limit)
             STAA  $05
             LDAA  #$93   ; steering max
             STAA  $06
             LDX   #ZERO_TAB   ; MOVE_LIST: all motors down to 0
             JSR   MOVE_LIST
             LDX   #LE449   ; MOVE_LIST: to the rest pose
             JSR   MOVE_LIST
             LDAA  #$01
             RTS   
ZERO_TAB:    FCB   $00,$00,$00,$00,$00,$00,$00   ; all motors to 0
LE449:       FCB   $00,$00,$4D,$00,$00,$62,$49   ; rest pose: rotate $4D, head $62 (ahead), steering $49 (straight)

;---------------------------------------------------------------
; R_SLEEP - robot op $87: sleep n x 10 s
;
; Obeyed only with the Sleep switch in Sleep and n <> 0.  Stores n in
; SLEEPCNT, aborts drive, steering, arm and speech, advances the user PC past
; itself (the handler does not expect to return) and sets POWER bit 6, which
; fires the sleep one-shot and drops +5 V.  Every 10 s the hardware wakes the
; CPU through RESET; the reset code counts SLEEPCNT down, sleeps again, and at
; 0 resumes the program at the saved PC from battery-backed RAM.  Emulator
; (which does not cut power): WAI was woken by the next tick IRQ, so E483 ran
; and the PC advanced by 3 a second time, skipping the next 3 bytes; on the
; real robot the supply is expected to fail first (inference).
;
; Out:       A = 3 (only if sleep is refused, or WAI returns)  (contract)
; Memory:    SLEEPCNT, POWER, user PC; aborts all motion and speech
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: B, X
; Preserves: none   [static + measured: 2 calls, 1/2 branches]
; Stack:     3 bytes max, including callees (observed 7)
; Cycles:    observed 17-247 E cycles over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; WAI
; Calls:     ABT_DRIVE, ABT_STEER, ABT_ARM, ABT_SPEECH
;---------------------------------------------------------------
R_SLEEP:     LDAA  MOTB   ; bit 1: 1 = switch in Normal
             BITA  #$02
             BNE   SLP_NONE   ; not in Sleep position: ignore the command
             LDX   USERFRAME
             LDX   $06,X
             LDX   $01,X   ; X = sleep count
             BEQ   SLP_NONE   ; zero periods: ignore
             STX   SLEEPCNT   ; the reset code counts this down
             JSR   ABT_DRIVE   ; ABT_DRIVE: stop the drive motor
             JSR   ABT_STEER   ; ABT_STEER: stop the steering motor
             JSR   ABT_ARM   ; ABT_ARM: stop the arm motor
             JSR   ABT_SPEECH   ; ABT_SPEECH: stop speech
             LDX   USERFRAME   ; user PC += 3 now: resumption is through RESET, not through RSTEP
             LDAA  $07,X
             LDAB  $06,X
             ADDA  #$03
             ADCB  #$00
             STAA  $07,X
             STAB  $06,X
             LDAA  #$40   ; POWER = sleep bit only: everything else off
             STAA  POWER
             WAI      ; wait here while +5 V collapses
SLP_NONE:    LDAA  #$03   ; length 3
             RTS   

;---------------------------------------------------------------
; R_PAUSE - robot op $8F: pause n/16 s
;
; Each unit waits for TICKS to advance by $40 (64 ticks = 62.5 ms).  Emulator:
; 8F 00 10 took 1.000 s.  Needs IRQs enabled (the CMPA wait is for an exact
; value).  PAUSE_DEX is also called by Learn mode with X = count + 1.
;
; Out:       A = 3                                              (contract)
;
; Changes:   A, X, flags H N Z V C
; Preserves: B   [static + measured: 1 call, 2/2 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 327,620 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into PAUSE_DEX
;---------------------------------------------------------------
R_PAUSE:     LDX   USERFRAME
             LDX   $06,X
             LDX   $01,X   ; X = unit count
PS_LOOP:     BEQ   PS_DONE
             LDAA  TICKS   ; target tick count = now + 64
             ADDA  #$40
PS_TICK:     CMPA  TICKS   ; wait for it
             BNE   PS_TICK

;---------------------------------------------------------------
; PAUSE_DEX - mid-loop entry of R_PAUSE: wait (X - 1) x 62.5 ms
;
; Learn mode calls it with X = count + 1 to dwell between records.  Returns
; A = 3 like the opcode.
;
; In:        X = units + 1
; Out:       A = 3, X = 0                                       (contract)
;
; Changes:   A, X, flags H N Z V C
; Preserves: B   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
; Called from: REC_IDLE
;---------------------------------------------------------------
PAUSE_DEX:   DEX   
             BRA   PS_LOOP
PS_DONE:     LDAA  #$03   ; length 3
             RTS   

;---------------------------------------------------------------
; DEMO - built-in Robot Language exercise loop (runs in Robot Language)
;
; Nothing in the ROM jumps to, loads or tabulates $E49F (searched for the
; address as a word and as split LDAA/LDAB pairs); it runs only when keyed in by
; hand (A, DO, E49F) - probably a factory or service exercise (inference).  It
; mixes native and robot instructions and never ends: whenever a channel is
; free it gives it more work - the arm/head walks through the 14 words at
; DEMO_MOVES (head sweeps $80-$B0 with shoulder nods, pivot down once),
; steering swings between $25 and $6E, the drive shuttles 32 counts forward and
; back (B bit 0 picks the direction), and the phrase at DEMO_TALK repeats.
; Emulator: all four ran concurrently for 24 s and more.
;
; Registers: X walks DEMO_MOVES, B counts drive legs
;---------------------------------------------------------------
DEMO:        CLRB     ; B = drive leg counter
DEMO_TOP:    LDX   #DEMO_MOVES   ; X = first arm word
LE4A3:       FCB   $1E,LE4A9-*-2   ; BRANCH IF ARM BUSY  arm still moving: skip
             FCB   $EC,$00   ; MOVE ABS $00,X  next arm/head word, continue
             INX      ; advance to the next word
             INX      ; (interpreted)
LE4A9:       FCB   $1D,LE4B9-*-2   ; BRANCH IF STEERING BUSY  steering still moving: skip
             FCB   $CC,$E8,$25   ; MOVE STEERING TO  $025 SLOW  swing one way...
             FCB   $8F,$00,$02   ; PAUSE 2/16 s  ...
             FCB   $1D,LE4B9-*-2   ; BRANCH IF STEERING BUSY  (normally still busy here)
             FCB   $CC,$E8,$6E   ; MOVE STEERING TO  $06E SLOW  ...and back
             FCB   $8F,$00,$02   ; PAUSE 2/16 s
LE4B9:       BITB  #$01   ; odd leg?
             BNE   LE4C4   ; (interpreted)
             FCB   $1C,LE4CA-*-2   ; BRANCH IF DRIVE BUSY  drive still moving: skip
             FCB   $CC,$18,$20   ; MOVE DRIVE TO  $020 FAST  forward 32 counts, fast
             BRA   LE4C9   ; (interpreted)
LE4C4:       FCB   $1C,LE4CA-*-2   ; BRANCH IF DRIVE BUSY  drive still moving: skip
             FCB   $CC,$1C,$20   ; MOVE DRIVE TO  $020 FAST  reverse 32 counts, fast
LE4C9:       INCB     ; next leg
LE4CA:       FCB   $1F,LE4CF-*-2   ; BRANCH IF SPEECH BUSY  still talking: skip
             FCB   $71,HI(DEMO_TALK),LO(DEMO_TALK)   ; SPEAK $E4F2  say it again
LE4CF:       CPX   #DEMO_TALK   ; end of the move list?
             BNE   LE4A3   ; (interpreted)
             BRA   DEMO_TOP   ; start the list again
* DEMO motor words (mmmssDdd dddddddd), used by "EC 00" (MOVE ABS 0,X)
DEMO_MOVES:  FCB   $D0,$80   ; head to $80, medium
             FCB   $50,$5A   ; shoulder to $5A, medium
             FCB   $90,$A5   ; pivot to $A5 (down), medium
             FCB   $50,$37   ; shoulder to $37, medium
             FCB   $50,$5A   ; shoulder to $5A, medium
             FCB   $D0,$90   ; head to $90, medium
             FCB   $50,$37   ; shoulder to $37, medium
             FCB   $50,$5A   ; shoulder to $5A, medium
             FCB   $D0,$A0   ; head to $A0, medium
             FCB   $50,$37   ; shoulder to $37, medium
             FCB   $50,$5A   ; shoulder to $5A, medium
             FCB   $D0,$B0   ; head to $B0, medium
             FCB   $50,$37   ; shoulder to $37, medium
             FCB   $50,$5A   ; shoulder to $5A, medium
DEMO_TALK:   FCB   $19,$3B,$0D,$1A,$2C,$3E,$28,$2B,$15,$2A,$15,$3E,$3E,$3E,$3E,$3E,$FF   ; DEMO phrase, roughly "KEN-JEE OO-RAH-TAH" (probably a name; inference) + pauses

;---------------------------------------------------------------
; UTIL - executive key 3: the utility menu
;
; Shows "3." and waits for a second key, echoes it, then runs entry
; key+1 of UTILTAB with the same RTS dispatch as the executive. Keys
; 1-8 are used; 0 and 9-F do nothing. In ROM 1.0 there are no RS-232
; utilities (39, 3A): the owners' FAQ lists those for later ROMs.
;
; In:        none (entered by RTS dispatch from EXEC_KEY)
; Out:       never returns; loops until a utility exits to RESET or EXEC
;
; Changes:   flags H N Z V C
; Preserves: A, B, X   [static]
; Stack:     9 bytes max, including callees
; Exit:      none
; Calls:     KEYDISP, CLRDIS, INCH, OUTHEX, OUTSTR
;---------------------------------------------------------------
UTIL:        JSR   CLRDIS
             JSR   OUTSTR   ; inline string follows: "3."
             FCB   $F9   ; display "3."
             LDX   #$C15F   ; put the echoed key in digit 2
             STX   DIGADD
             JSR   INCH   ; INCH: wait for a key (A = 0-F)
             JSR   OUTHEX   ; OUTHEX: show it
             LDX   #UTILTAB-2   ; table base minus 2: KEYDISP adds 2 per key, plus 2
             JSR   KEYDISP   ; KEYDISP: push the routine address and RTS to it
LE51C:       BRA   UTIL   ; a utility that returns comes back to the menu

;---------------------------------------------------------------
; (UTILTAB entry for keys 0 and 9-F) - no utility: return to the menu
;
; Changes:   nothing
; Preserves: A, B, X   [static + measured: 8 calls]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 5 E cycles on every call over 8 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
;---------------------------------------------------------------
LE51E:       RTS      ; key 0, 9-F: no utility
UTILTAB:     FDB   LE51E,UT_INIT,UT_REST,UT_SAVE,UT_LOAD,UT_SETTIME,UT_SETDATE,UT_SHOWTIME   ; 1 init, 2 rest pose, 3 save, 4 load, 5 set time, 6 set date, 7 show time, 8 show date
             FDB   UT_SHOWDATE,LE51E,LE51E,LE51E,LE51E,LE51E,LE51E,LE51E

;---------------------------------------------------------------
; UT_INIT - utility 1 (keys 3 1): initialize every motor
;
; Points the user PC in the SWI frame at INIT_PROG and enters the
; Robot Language run loop, so the ROM's own Robot Language program
; does the work: ZERO, then RETURN TO EXECUTIVE.
;
; In:        USERFRAME = monitor's register frame
; Out:       never returns (runs INIT_PROG)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     14 bytes max, including callees
; Exit:      tail-JMP to RUN_STEP
; Calls:     RUN_STEP
;---------------------------------------------------------------
UT_INIT:     LDX   USERFRAME
             LDAA  #LO(INIT_PROG)   ; robot PC := INIT_PROG
             LDAB  #HI(INIT_PROG)
             STAA  $07,X
             STAB  $06,X
             JMP   RUN_STEP   ; RUN_STEP: run it in Robot Language
* INIT_PROG - Robot Language, run by UT_INIT. The first two lines are 6800 code that the
* interpreter executes: if the robot is not already in Robot Language mode, SWI enters it.
INIT_PROG:   FCB   $7D,$0E,$E1   ; TST ROBOTMODE (interpreted)
             BNE   LE553   ; already in Robot Language: skip the SWI (interpreted)
             SWI      ; SWI: switch the interpreter into Robot Language
LE553:       FCB   $21   ; ZERO
             FCB   $3A   ; RETURN TO EXECUTIVE

;---------------------------------------------------------------
; UT_REST - utility 2 (keys 3 2): move to the rest pose
;
; Same pattern as UT_INIT: runs REST_PROG in Robot Language, which
; moves every arm motor, the head and the steering to the rest pose
; with one MOVE ALL.
;
; In:        USERFRAME = monitor's register frame
; Out:       never returns (runs REST_PROG)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     14 bytes max, including callees
; Exit:      tail-JMP to RUN_STEP
; Calls:     RUN_STEP
;---------------------------------------------------------------
UT_REST:     LDX   USERFRAME
             LDAA  #LO(REST_PROG)
             LDAB  #HI(REST_PROG)
             STAA  $07,X
             STAB  $06,X
             JMP   RUN_STEP
* REST_PROG - Robot Language: TST ROBOTMODE / BNE +1 / SWI, then
* MOVE ALL to extend 00, shoulder 00, rotate 4D, pivot 00, gripper 00, head 62, steering 49,
* then RETURN TO EXECUTIVE.
REST_PROG:   FCB   $7D,$0E,$E1,$26,$01,$3F,$FD,$00
             FCB   $00,$4D,$00,$00,$62,$49,$3A

;---------------------------------------------------------------
; UT_SAVE - utility 3 (keys 3 3): save memory to cassette
;
; Prompts "Fr." and "LA." for the first and last addresses (two bytes
; each, keyed in hex), then writes Motorola S1 records with an S9 end
; record to the cassette output, and restarts through RESET.
;
; In:        keys: first address, last address
; Out:       never returns (JMP RESET)
; Memory:    writes CASS_FROM, CASS_LAST; toggles POWER bit 0 (tape out)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     21 bytes max, including callees
; Exit:      tail-JMP to RESET
; Calls:     SREC_WRITE, RESET, OUTSTR4, REDIS, KEYBYTES
;---------------------------------------------------------------
UT_SAVE:     SEI      ; no interrupts while timing the tape signal
             NOP   
             LDAA  #$10   ; power: display only
             STAA  POWER
             STAA  POWER_SH
             JSR   OUTSTR4   ; OUTSTR4: show the prompt at digit 4
             FCB   $47,$85   ; inline string: "Fr." (from)
             JSR   REDIS   ; REDIS: home the display pointer
             LDX   #$003B   ; two bytes into CASS_FROM
             LDAB  #$02
             JSR   KEYBYTES   ; KEYBYTES: read B bytes from the keypad into X
             JSR   OUTSTR4   ; prompt "LA." (last)
             FCB   $0E,$FD   ; inline string: "LA."
             JSR   REDIS
             LDX   #$003D
             LDAB  #$02
             JSR   KEYBYTES   ; KEYBYTES
             LDAB  #$08   ; B = 8: cassette (a negative B would select the serial output)
             JSR   SREC_WRITE   ; SREC_WRITE: send the block as S-records
TO_RESET:    JMP   RESET   ; always leave through RESET (the robot was stopped for timing)

;---------------------------------------------------------------
; UT_LOAD - utility 4 (keys 3 4): load memory from cassette
;
; Reads S-records from the cassette input until the S9 record, storing
; each data byte at the address in its record. A checksum error shows
; "Error." and starts listening again.
;
; In:        cassette signal on MOTB bit 7
; Out:       never returns (RESET on success)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     1967 bytes max, including callees
; Exit:      tail-JMP to RESET
; Calls:     SREC_READ, RESET, REDIS, OUTSTR
;---------------------------------------------------------------
UT_LOAD:     SEI   
             NOP   
             LDAA  #$10
             STAA  POWER
             STAA  POWER_SH
             LDAB  #$08   ; B = 8: cassette timing
             JSR   SREC_READ   ; SREC_READ: C clear = S9 seen, C set = checksum error
             BCC   TO_RESET
             JSR   REDIS   ; REDIS
             JSR   OUTSTR
             FCB   $4F,$05,$05,$1D,$85   ; inline string: "Error."
             BRA   UT_LOAD

;---------------------------------------------------------------
; SREC_READ - read S-records until S9
;
; Waits for an "S", then a type digit. "1": reads count, address and
; data bytes, storing the data, and checks the record's checksum.
; "9": done. Anything else: keep looking.
;
; In:        B = 8 (cassette)
; Out:       C clear = S9 reached, C set = checksum error  (contract)
; Memory:    writes the loaded bytes; uses CASS_CNT; lights DISP_LEFT while a record loads
;
; Changes:   A, X, flags H N Z V C
; Preserves: B   [static]
; Stack:     1965 bytes max, including callees
; Exit:      RTS
; Calls:     GET_BYTE, GET_CHAR
; Called from: UT_LOAD
;---------------------------------------------------------------
SREC_READ:   DES      ; two bytes of stack: the record address is built here
             DES   
LE5C4:       JSR   GET_CHAR   ; GET_CHAR
             ANDA  #$7F   ; ignore the parity bit
             CMPA  #$53   ; "S"?
             BNE   LE5C4
             JSR   GET_CHAR   ; GET_CHAR: record type
             ANDA  #$7F
             CMPA  #$39   ; "9": end of file
             BEQ   LE60C
             DES   
             CMPA  #$31   ; "1": a data record
             BNE   LE5C4
             STAA  DISP_LEFT   ; activity light: leftmost digit on while a record loads
             CLRA  
             TSX   
             JSR   GET_BYTE   ; GET_BYTE: count (also starts the checksum in A)
             JSR   GET_BYTE   ; GET_BYTE: address high, onto the stack
             JSR   GET_BYTE   ; GET_BYTE: address low
             TSX   
             LDX   $01,X
             STAB  CASS_CNT
             PULB     ; data bytes = count - 3 (address and checksum)
             SUBB  #$03
LE5F1:       PSHB  
             LDAB  CASS_CNT
             JSR   GET_BYTE   ; GET_BYTE: one data byte, stored at X
             STAB  CASS_CNT
             PULB  
             DECB  
             BNE   LE5F1
             CLR   DISP_LEFT
             LDAB  CASS_CNT
             LDX   #$0039
             JSR   GET_BYTE   ; GET_BYTE: the checksum byte
             INCA     ; a good record sums to $FF; INCA makes it 0
             BEQ   LE5C4
             SEC      ; checksum error: C set
LE60C:       INS   
             INS   
             RTS   

;---------------------------------------------------------------
; SREC_WRITE - write CASS_FROM..CASS_LAST as S1 records and an S9
;
; Sends a leader, then records of up to 16 data bytes ("S1", count,
; address, data, checksum, each as two ASCII hex digits). The bit timing
; is done entirely with counted delay loops; the NOPs and the
; "DECA/BNE" pads balance every path to the same length per bit.
;
; In:        B > 0 cassette (B = bit-cell count), B <= 0 serial
;            CASS_FROM, CASS_LAST = block to save
; Out:       C clear
; Cycles:    cycle-exact by design: every path is padded so each bit cell is the same length [hand count]
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: B
; Preserves: none   [static]
; Stack:     19 bytes max, including callees
; Exit:      RTS
; Calls:     SEND_STR, SEND_DBYTE, SEND_BYTE, SEND_HEX2, SEND_LEADER
; Called from: UT_SAVE
