SREC_WRITE:  TSTB  
             BLE   LE619
             JSR   SEND_LEADER   ; SEND_LEADER: a long run of 1 cells before the first record
             LDAA  #$07
             BRA   LE61B
LE619:       LDAA  #$04
LE61B:       DECA  
             BNE   LE61B
             PSHB  
             LDAB  CASS_LAST   ; bytes remaining = last - from
             LDAA  $3E
             SUBA  $3C
             SBCB  CASS_FROM
             BCS   LE681
             CMPA  #$0F
             SBCB  #$00
             PULB  
             BCC   LE632
             BRA   LE635
LE632:       LDAA  #$0F   ; 16 data bytes in this record
             NOP   
LE635:       STAA  CASS_CNT   ; count byte = data bytes + 3 (address and checksum)
             ADDA  #$04
             STAA  CASS_LEN
             LDX   #SREC_S1   ; "\r\nS1"
             TSTB  
             BPL   LE644
             LDX   #SREC_CRLF   ; serial uses the shorter string table entry
LE644:       BSR   SEND_STR   ; SEND_STR
             LDX   #$003B
             CLRA  
             NOP   
             TSTB  
             BMI   LE651
             DEX   
             BITA  $00,X
LE651:       NOP   
             NOP   
             BSR   SEND_BYTE
             NOP   
             BNE   LE651
             LDX   CASS_FROM
LE65A:       BSR   SEND_DBYTE
             DEC   >CASS_CNT
             BPL   LE65A
             COMA  
             PSHA  
             NOP   
             LDAA  #$07   ; timing pad
LE666:       DECA  
             BNE   LE666
             PULA  
             TSTB  
             BMI   LE66F
             BSR   SEND_HEX2
LE66F:       LDAA  DRIVE   ; DRIVE read: on the serial path this is the receive line (inference)
             COMA  
             CLC   
             STX   CASS_FROM
             STX   CASS_FROM
             BHI   LE619
             INX   
             PSHB  
             LDAA  #$06
LE67E:       DECA  
             BNE   LE67E
LE681:       PULB  
             NOP   
             LDAA  #$03
LE685:       DECA  
             BNE   LE685
             LDX   #SREC_S9   ; finished: "\r\nS9" end record
             TSTB  
             BMI   LE69B
             BSR   SEND_STR   ; SEND_STR
             TSTB  
             BEQ   LE69B
             LDAA  #$13
LE695:       DECA  
             BNE   LE695
             BSR   SEND_LEADER   ; SEND_LEADER: trailing tone
             CLC   
LE69B:       RTS   
SREC_S1:     FCB   $0D,$0A,$53,$31,$00   ; "\r\nS1": carriage return, line feed, then the S1 record type (a 0 ends each string)
SREC_S9:     FCB   $0D,$0A,$53,$39,$00   ; "\r\nS9": the end-of-file record type
SREC_CRLF:   FCB   $0D,$0A,$00   ; "\r\n"

;---------------------------------------------------------------
; SEND_STR - send a 0-terminated string
;
; In:        X = string, B = output mode
; Out:       X = byte after the terminator
