; low tone (a 0).
;
; Out:       C = bit (high tone sets C)
;
; Changes:   A, flags N Z V C
; Preserves: B, X   [static]
; Stack:     3 bytes max, including callees
; Exit:      RTS; falls into TAPE_HALFP
; Calls:     TAPE_HALFP
; Called from: GET_CHAR
;---------------------------------------------------------------
TAPE_PERIOD: LDAA  MOTA
             BSR   TAPE_HALFP
             BCC   LE857

;---------------------------------------------------------------
; TAPE_HALFP - time one half-cycle of the cassette input
;
; In:        A = last $C260 reading
; Out:       A = new reading; C set if the half-cycle was shorter than $1D passes
;
; Changes:   A, flags N Z V C
; Preserves: B, X   [static]
; Stack:     1 byte max, including callees
; Exit:      RTS
; Called from: TAPE_PERIOD
;---------------------------------------------------------------
TAPE_HALFP:  PSHB  
             CLRB  
LE84B:       INCB  
             CMPA  MOTA
             BEQ   LE84B
             LDAA  MOTA
             CMPB  #$1D
             PULB  
LE857:       RTS   

;---------------------------------------------------------------
; LEARN - executive key 7: record a program from the teaching pendant
;
; Asks for the program's start and end addresses, then loops forever:
; read the pendant, and while the trigger is held, move the selected
; motor and append Robot Language records (see the helpers from $EA06).
; Keys pick the sub-mode: F record, B back up, 7 retrace (LRN_KEY).
;
; In:        keys: start address, end address; pendant on MOTB
; Out:       never returns (RESET or ABORT leaves)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     19 bytes max, including callees
; Exit:      falls into LRN_LOOP; tail-JMP to LRN_LOOP
; Calls:     ABT_ARM, LRN_LOOP, LRN_SETUP, LRN_SHOWPTR, RD_PENDANT, SET_DRVOP, REC_FLUSH, REC_IDLE, LRN_KEY, PB_BACKUP, PB_RETURN, DRV_RELEG, MAN_BODY, MAN_ARM, DRV_GATE, REC_MOVE, KEYPOLL
;---------------------------------------------------------------
LEARN:       JSR   LRN_SETUP   ; LRN_SETUP: addresses, prompts, first MOVE ALL record

;---------------------------------------------------------------
; LRN_LOOP - Learn mode main loop (re-entered after each pass; see LEARN)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     14 bytes max, including callees
; Exit:      tail-JMP to LRN_LOOP
; Calls:     ABT_ARM, LRN_LOOP, LRN_SHOWPTR, RD_PENDANT, SET_DRVOP, REC_FLUSH, REC_IDLE, LRN_KEY, PB_BACKUP, PB_RETURN, DRV_RELEG, MAN_BODY, MAN_ARM, DRV_GATE, REC_MOVE, KEYPOLL
; Called from: LEARN, LRN_LOOP
;---------------------------------------------------------------
LRN_LOOP:    JSR   LRN_SHOWPTR
             JSR   RD_PENDANT
             JSR   SET_DRVOP
             TST   PND_TRIG
             BEQ   LE8B8
             LDAA  LRN_MODE
             BNE   LE8AA
             LDAA  PND_ROT
             CMPA  PREV_ROT
             BNE   LE886
             LDAA  PND_MOT
             CMPA  PREV_MOT
             BNE   LE886
             LDAA  PREV_ARM
             CMPA  PND_ARM
             BEQ   LE889
LE886:       JSR   REC_FLUSH
LE889:       TST   PND_ARM
             BEQ   LE893
             JSR   MAN_ARM
             BRA   LE8E0
LE893:       TST   DRV_ON
             BEQ   LE8A5
             JSR   DRV_RELEG
             BCC   LE8A5
             LDAA  #$CC
             STAA  REC_OP
             JSR   REC_MOVE
LE8A5:       JSR   MAN_BODY
             BRA   LE8E0
LE8AA:       CMPA  #$02
             BNE   LE8B3
             JSR   PB_RETURN
             BRA   LE8E0
LE8B3:       JSR   PB_BACKUP
             BRA   LE8E0
LE8B8:       TST   PB_WAIT
             BEQ   LE8C5
             LDAA  #$01
             STAA  PB_PAUSED
             JSR   ABT_ARM
LE8C5:       JSR   REC_FLUSH
             TST   LRN_MODE
             BNE   LE8D8
             LDAA  #$FF
             STAA  PREV_ROT
             STAA  PREV_MOT
             JSR   REC_IDLE
LE8D8:       JSR   KEYPOLL   ; KEYPOLL: a key pressed?
             BCC   LE8E0
             JSR   LRN_KEY
LE8E0:       LDAA  PND_ARM
             STAA  PREV_ARM
             JSR   DRV_GATE
             JMP   LRN_LOOP

;---------------------------------------------------------------
; MANUAL - executive key 4: drive the robot from the teaching pendant
;
; Loops forever: read the pendant; when the selection changes, stop
; whatever was moving; while the trigger is held, run the selected arm
; motor or the drive and steering. Nothing is recorded.
;
; In:        pendant on MOTB
; Out:       never returns
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     11 bytes max, including callees
; Exit:      falls into MAN_LOOP; tail-JMP to MAN_LOOP
; Calls:     ABT_STEER, ABT_ARM, MAN_LOOP, MAN_SETUP, MAN_SHOW, RD_PENDANT, DRV_RELEG, MAN_BODY, MAN_ARM, DRV_ABORT, DRV_GATE
;---------------------------------------------------------------
MANUAL:      JSR   MAN_SETUP   ; MAN_SETUP: show "4." and clear the motion state

;---------------------------------------------------------------
; MAN_LOOP - Manual mode main loop (re-entered after each pass; see MANUAL)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     11 bytes max, including callees
; Exit:      tail-JMP to MAN_LOOP
; Calls:     ABT_STEER, ABT_ARM, MAN_LOOP, MAN_SHOW, RD_PENDANT, DRV_RELEG, MAN_BODY, MAN_ARM, DRV_ABORT, DRV_GATE
; Called from: MANUAL, MAN_LOOP
;---------------------------------------------------------------
MAN_LOOP:    JSR   RD_PENDANT
             TST   PND_TRIG
             BNE   LE8FF
             LDAA  #$FF
             STAA  PREV_ROT
             STAA  PND_MOT
LE8FF:       LDAA  PND_ARM
             CMPA  PREV_ARM
             BEQ   LE919
             JSR   DRV_ABORT
             JSR   ABT_STEER
             JSR   ABT_ARM
             CLR   DRV_ON
             CLR   STR_ON
             CLR   ARM_ON
LE919:       TST   PND_ARM
             BEQ   LE93E
             LDAB  PND_ROT
             CMPB  PREV_ROT
             BNE   LE92E
             LDAB  PND_MOT
             CMPB  PREV_MOT
             BEQ   LE934
LE92E:       JSR   ABT_ARM
             CLR   ARM_ON
LE934:       TST   PND_TRIG
             BEQ   LE96A
             JSR   MAN_ARM
             BRA   LE96A
LE93E:       LDAB  PND_ROT
             CMPB  PREV_ROT
             BEQ   LE94C
             JSR   DRV_ABORT
             CLR   DRV_ON
LE94C:       LDAB  PND_MOT
             CMPB  PREV_MOT
             BEQ   LE95A
             JSR   ABT_STEER
             CLR   STR_ON
LE95A:       TST   DRV_ON
             BEQ   LE962
             JSR   DRV_RELEG
LE962:       TST   PND_TRIG
             BEQ   LE96A
             JSR   MAN_BODY
LE96A:       JSR   DRV_GATE
             JSR   MAN_SHOW
             LDAA  PND_ARM
             STAA  PREV_ARM
             JMP   MAN_LOOP

;---------------------------------------------------------------
; LRN_SETUP - Learn mode set-up
;
; Reads the record pointer (LRN_PTR) and end address (LRN_END) from the
; keypad, points the user PC at the program so it can be run later,
; clears the motion state and records a MOVE ALL of the current pose.
;
; Out:       LRN_START = first record address
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     17 bytes max, including callees
; Exit:      RTS
; Calls:     LRN_ADDR, REC_POSALL, CLRDIS, OUTSTR
; Called from: LEARN
;---------------------------------------------------------------
LRN_SETUP:   LDX   #$0F2E
             STX   ADR_VAR
             BSR   LRN_ADDR
             LDAA  LRN_PTRL
             LDAB  LRN_PTR
             LDX   USERFRAME
             STAA  $07,X
             STAB  $06,X
             LDX   #$0F34
             STX   ADR_VAR
             BSR   LRN_ADDR
             CLR   LRN_MODE
             LDAA  #$C7
             STAA  MODE_CHAR
             COMA  
             STAA  MODE_SHOWN
             CLR   DRV_ON
             CLR   STR_ON
             CLR   ARM_ON
             CLR   PB_WAIT
             CLR   PB_PAUSED
             LDAA  #$00
             STAA  PND_MOT
             STAA  PREV_ROT
             JSR   CLRDIS
             JSR   OUTSTR
             FCB   $F0   ; display "7."
             JSR   REC_POSALL
             STAA  LRN_STARTL
             STAB  LRN_START
             RTS   

;---------------------------------------------------------------
; LRN_ADDR - show "7." and read a two-byte address into (ADR_VAR)
;
; In:        ADR_VAR = where to store it
;
; Changes:   A, B, X, flags H N Z V C
; Preserves: none   [static + measured: 3 calls]
;            measured: X written but equal at exit on every call
; Stack:     15 bytes max, including callees (observed 15)
; Cycles:    observed 2,020,285-3,986,565 E cycles over 3 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     CLRDIS, KEYBYTES, KEYUP, OUTSTR
; Called from: LRN_SETUP
;---------------------------------------------------------------
LRN_ADDR:    JSR   CLRDIS
             JSR   OUTSTR
             FCB   $F0   ; display "7."
             LDX   #$C14F
             STX   DIGADD
             LDX   ADR_VAR
             LDAB  #$02
             JSR   KEYBYTES
             JSR   KEYUP
             RTS   

;---------------------------------------------------------------
; MAN_SETUP - Manual mode set-up: clear the motion state, show "4."
;
; Changes:   A, B, X, flags N Z V C
; Preserves: none   [static + measured: 2 calls]
;            measured: B written but equal at exit on every call
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 2,589 E cycles on every call over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     CLRDIS, OUTSTR
; Called from: MANUAL
;---------------------------------------------------------------
MAN_SETUP:   CLR   PREV_ROT
             CLR   PREV_MOT
             CLR   PREV_ARM
             CLR   DRV_ON
             CLR   STR_ON
             CLR   ARM_ON
             LDX   #$FFFF
             STX   SHOW_LAST
             JSR   CLRDIS
             JSR   OUTSTR
             FCB   $B3   ; display "4."
             CLR   MODE_SHOWN   ; tail of manual-mode setup at $E9E3: no mode letter shown yet
             RTS   
* $EA06-$EFC8: Manual (key 4) and Learn (key 7) mode helpers, driven by the teaching pendant on $C280.
* Most of it never runs in the recorded sessions (the stock emulator holds the pendant idle); every
* instruction in this block was reached with a scratch emulator copy that models the pendant byte,
* by driving Manual mode, Learn record/backup/return, a long drive, an over-full program and bad opcodes.

;---------------------------------------------------------------
; LRN_SHOWPTR - show the Learn mode letter and record pointer
;
; Redraws digits 1-5 ("F.0508", "b.0511", "r.0514") only when the record
; pointer or the mode letter has changed since the last call, so the display
; does not flicker in the polling loop.
;
; In:        LRN_PTR, MODE_CHAR
; Out:       LRN_SHOWN = LRN_PTR, MODE_SHOWN = MODE_CHAR       (contract)
; Memory:    writes DIGADD ($0FF2), display latches
;
; Changes:   A, X, flags N Z V C
; Preserves: B   [static]
; Stack:     9 bytes max, including callees
; Exit:      RTS
; Calls:     OUTBYT, OUTCH
; Called from: LEARN, LRN_LOOP
;---------------------------------------------------------------
LRN_SHOWPTR: LDX   LRN_PTR
             LDAA  MODE_CHAR
             CPX   LRN_SHOWN   ; pointer unchanged since last shown?
             BNE   LEA16
             CMPA  MODE_SHOWN   ; ... and the mode letter too?
             BEQ   LEA34   ; yes: nothing to do
LEA16:       LDX   #$C15F   ; digit 1 (second from left)
             STX   DIGADD
             STAA  MODE_SHOWN
             JSR   OUTCH   ; OUTCH: mode letter (or blank while blinking)
             LDAA  LRN_PTR
             JSR   OUTBYT   ; OUTBYT: pointer high byte
             LDAA  LRN_PTRL
             JSR   OUTBYT   ; OUTBYT: pointer low byte
             LDX   LRN_PTR
             STX   LRN_SHOWN
LEA34:       RTS   

;---------------------------------------------------------------
; MAN_SHOW - Manual mode position readout
;
; BODY: digits 2-5 show the drive distance counter ($0007/$0008) in hex.
; ARM: digits 2-3 blank, 4-5 show the position byte of the motor picked by the
; rotary switch (blank at N). Redraws only on change; a change of the
; ARM/BODY switch forces a full redraw. (Emulator: ARM with the rotary at Head shows "4.   61".)
;
; In:        PND_ARM, PREV_ARM, PND_ROT, SHOW_LAST, MODE_SHOWN
; Out:       SHOW_LAST updated                                  (contract)
; Memory:    writes DIGADD ($0FF2), display latches; reads $0000-$0008
;
; Changes:   A, B, X, flags N Z V C
; Preserves: none   [static + measured: 6,532 calls, 1/1 branches]
; Stack:     9 bytes max, including callees (observed 9)
; Cycles:    observed 1,162-2,163 E cycles over 6,532 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into MAN_SHOWNOW
; Calls:     MOTPOS, OUTBYT, OUTCH
; Called from: MANUAL, MAN_LOOP
;---------------------------------------------------------------
MAN_SHOW:    LDAB  PND_ARM
             CMPB  PREV_ARM   ; function switch moved since last pass?
             BEQ   LEA43

;---------------------------------------------------------------
; MAN_SHOWNOW - MAN_SHOW entry that always redraws
;
; Learn mode jumps in here while key 4 is held to show the live position.
;
; In:        B = PND_ARM ($80 arm, 0 body)
; Memory:    as MAN_SHOW
;
; Changes:   A, B, X, flags N Z V C ; on some paths: B
; Preserves: none   [static]
; Stack:     9 bytes max, including callees
; Exit:      RTS
; Calls:     MOTPOS, OUTBYT, OUTCH
; Called from: LRN_KEY
;---------------------------------------------------------------
MAN_SHOWNOW: LDX   #$FFFF   ; $FFFF never matches a real value: force a redraw
             STX   SHOW_LAST
LEA43:       LDX   #$C15F   ; digit 1
             STX   DIGADD
             LDAA  MODE_SHOWN
             JSR   OUTCH   ; OUTCH: mode letter (blank in Manual mode)
             TSTB     ; B = PND_ARM: Z set = BODY
             BEQ   LEA7F
             CLRA     ; blank pattern
             JSR   OUTCH   ; OUTCH: digit 2 blank
             JSR   OUTCH   ; OUTCH: digit 3 blank
             LDAB  PND_ROT
             CMPB  #$00
             BNE   LEA6E   ; rotary not at N: show that motor
             JSR   OUTCH   ; OUTCH: digit 4 blank
             JSR   OUTCH   ; OUTCH: digit 5 blank
             LDX   #$FFFF   ; force a redraw when a motor is selected again
             STX   SHOW_LAST
             BRA   LEA93
LEA6E:       TBA   
             JSR   MOTPOS   ; MOTPOS: A = current position of the selected motor
             CMPA  SHOW_LASTL   ; same as shown? (low byte of SHOW_LAST)
             BEQ   LEA93
             STAA  SHOW_LASTL
             JSR   OUTBYT   ; OUTBYT: position, digits 4-5
             BRA   LEA93
LEA7F:       LDX   DRVCOUNT   ; BODY: drive distance counter $0007/$0008
             CPX   SHOW_LAST
             BEQ   LEA93
             STX   SHOW_LAST
             LDAA  DRVCOUNT
             JSR   OUTBYT   ; OUTBYT: distance high
             LDAA  $08
             JSR   OUTBYT   ; OUTBYT: distance low
LEA93:       RTS   

;---------------------------------------------------------------
; RD_PENDANT - read and debounce the teaching pendant
;
; Reads $C280 until it returns the same value 127 times running, then splits
; it: bit 0 trigger, bits 6-4 rotary (N=0, wrist pivot=1, wrist rotate=2,
; gripper=3, arm pivot (shoulder)=5, extend=6, head=7), bits 3-2 motion (active
; low: bit 3 low = RIGHT, bit 2 low = LEFT per the manual's pendant chart),
; bit 7 function (1 = ARM).
;
; In:        MOTB ($C280) pendant inputs
; Out:       PND_TRIG 0/1, PND_ROT 0-7, PND_MOT 0 clear/1 left/2 right,
;            PND_ARM $80 ARM or 0 BODY                          (contract)
; Memory:    writes PND_TRIG, PND_ROT, PND_MOT, PND_ARM
;
; Changes:   A, B, flags N Z V C
; Preserves: X   [static + measured: 6,532 calls, 2/2 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 1,837-2,705 E cycles over 6,532 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: LEARN, LRN_LOOP, MANUAL, MAN_LOOP
;---------------------------------------------------------------
RD_PENDANT:  LDAA  MOTB
             LDAB  #$7F   ; need 127 identical reads
LEA99:       CMPA  MOTB   ; changed? start over
             BNE   RD_PENDANT
             DECB  
             BNE   LEA99
             TAB   
             ANDB  #$01   ; bit 0: trigger (1 = pulled)
             STAB  PND_TRIG
             TAB   
             ANDB  #$70   ; bits 6-4: rotary switch
             LSRB  
             LSRB  
             LSRB  
             LSRB  
             STAB  PND_ROT
             TAB   
             LSRB     ; bits 3-2 down to 1-0
             LSRB  
             COMB     ; active low: invert
             ANDB  #$03   ; 1 = LEFT (bit 2 low), 2 = RIGHT (bit 3 low)
             STAB  PND_MOT
             ANDA  #$80   ; bit 7: function switch ARM
             STAA  PND_ARM
             RTS   

;---------------------------------------------------------------
; SET_DRVOP - choose the opcode for the next drive record
;
; A drive leg recorded while the steering is also moving is written as
; $CC (move, continue) so that on playback the steering record that follows
; runs at the same time; otherwise $C3 (move, wait).
;
; In:        DRV_ON, STR_ON
; Out:       DRV_OP = $CC or $C3                                (contract)
;
; Changes:   A, flags N Z V
; Preserves: B, X   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
; Called from: LEARN, LRN_LOOP
;---------------------------------------------------------------
SET_DRVOP:   LDAA  DRV_ON
             ANDA  STR_ON
             BEQ   LEACC
             LDAA  #$CC
             BRA   LEACE
LEACC:       LDAA  #$C3
LEACE:       STAA  DRV_OP
             RTS   

;---------------------------------------------------------------
; REC_FLUSH - end every pendant motion in progress and record it
;
; Drive: stop it and write C3/CC (drive, speed/direction from the rotary,
; distance travelled so far). Steering: abort it and write "C3 E8 pp", an
; absolute steering move to where it stopped. Arm: abort it and write
; "D3 m8 dd", a slow relative move from ARM_START to where it stopped.
; (Emulator: extend moved $4C->$55 recorded as D3 28 09.)
;
; In:        DRV_ON, STR_ON, ARM_ON, PREV_ROT, ARM_START, DRV_OP
; Out:       the three flags cleared; records appended at LRN_PTR (contract)
; Memory:    writes REC_xxx, LRN_PTR, the program area
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: A, B, X
; Preserves: none   [static]
; Stack:     9 bytes max, including callees
; Exit:      RTS
; Calls:     ABT_STEER, ABT_ARM, DRV_ABORT, MOTPOS, DRV_FIELDS, REC_MOVE
; Called from: LEARN, LRN_LOOP, LRN_KEY, PB_RETURN
;---------------------------------------------------------------
REC_FLUSH:   TST   DRV_ON   ; drive leg running?
             BEQ   LEAEE
             LDX   DRVCOUNT   ; distance counted so far
             STX   REC_DIR
             JSR   DRV_ABORT   ; DRV_ABORT: stop the drive motor
             LDAA  PREV_ROT   ; A = rotary code the leg was started with
             LDX   REC_DIR
             JSR   DRV_FIELDS   ; DRV_FIELDS: fill REC_xxx for a drive move of X counts
             JSR   REC_MOVE   ; REC_MOVE: append the record
             CLR   DRV_ON
LEAEE:       TST   STR_ON   ; steering move running?
             BEQ   LEB13
             JSR   ABT_STEER   ; abort steering and wait until it has stopped
             LDAA  $06   ; steering position now
             STAA  REC_POS
             CLR   REC_DIR
             LDAA  #$08   ; speed bits 01 (slow)
             STAA  REC_SPEED
             LDAA  #$E0   ; motor 7 = steering
             STAA  REC_MOTOR
             LDAA  #$C3   ; C3: absolute move, wait
             STAA  REC_OP
             JSR   REC_MOVE   ; REC_MOVE: append "C3 E8 pp"
             CLR   STR_ON
LEB13:       TST   ARM_ON   ; arm move running?
             BEQ   LEB4D
             JSR   ABT_ARM   ; abort the arm channel and wait until it has stopped
             LDAA  PREV_ROT   ; motor that was moving
             JSR   MOTPOS   ; MOTPOS: A = its position now
             CMPA  ARM_START
             BCS   LEB31   ; moved below where it started?
             SUBA  ARM_START   ; distance = now - start, direction bit 0 (increase)
             STAA  REC_POS
             CLR   REC_DIR
             BRA   LEB3D
LEB31:       SUBA  ARM_START   ; distance = start - now
             NEGA  
             STAA  REC_POS
             LDAA  #$04   ; direction bit set (decrease)
             STAA  REC_DIR
LEB3D:       LDAA  #$08   ; speed bits 01 (slow)
             STAA  REC_SPEED
             LDAA  #$D3   ; D3: relative move, wait
             STAA  REC_OP
             JSR   REC_MOVE   ; REC_MOVE: append "D3 m8 dd"
             CLR   ARM_ON
LEB4D:       RTS   

;---------------------------------------------------------------
; REC_IDLE - record a pause when the operator lets go
;
; In Record mode with the trigger released, BODY selected and the rotary at N,
; appends "8F 00 20" (PAUSE 2 s) once (not if the last record is already a
; pause or the program is empty), then actually waits about 2 s so that live
; operation keeps step with what playback will do.
;
; In:        PND_ARM, PND_ROT, LRN_PTR, LRN_START
; Memory:    may append 4 bytes at LRN_PTR
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: A, B, X
; Preserves: none   [static]
; Stack:     9 bytes max, including callees
; Exit:      RTS
; Calls:     PAUSE_DEX, REC_PAUSE
; Called from: LEARN, LRN_LOOP
;---------------------------------------------------------------
REC_IDLE:    TST   PND_ARM
             BNE   LEB72   ; ARM selected: no pause
             TST   PND_ROT
             BNE   LEB72   ; rotary not at N: no pause
             LDX   LRN_PTR
             CPX   LRN_START
             BEQ   LEB72   ; nothing recorded yet
             DEX      ; back up to the last record
             DEX   
             DEX   
             LDAA  $00,X
             CMPA  #$8F   ; already a PAUSE?
             BEQ   LEB72
             JSR   REC_PAUSE   ; REC_PAUSE: append 8F 00 20
             LDX   #$0020   ; 31 x 1/16 s
             JSR   PAUSE_DEX   ; wait loop inside the SLEEP/PAUSE handler (counts $0EFC in steps of 64 ticks)
LEB72:       RTS   

;---------------------------------------------------------------
; LRN_KEY - act on a keypad key in Learn mode
;
; 4 = show the live position (BODY: distance, ARM: motor position) while held.
; F = back to Record (forward) mode; if a Backup/Return arm move is under way,
;     its partial movement is recorded first.
; B = Backup: step back through the program undoing arm moves and erasing them.
; 7 = Return: retrace the program backwards to the starting pose, recording
;     the return moves so the program ends where it began.
; Other keys are ignored. Waits for the key to be released.
;
; In:        A = key code 0-F
; Memory:    LRN_MODE, MODE_CHAR, LRN_PTR, REV_PTR, PB_xxx
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: A, X
; Preserves: none   [static]
; Stack:     12 bytes max, including callees
; Exit:      RTS
; Calls:     MAN_SHOWNOW, REC_FLUSH, SET_LMODE, PTR_BACK3, KEYUP
; Called from: LEARN, LRN_LOOP
;---------------------------------------------------------------
LRN_KEY:     PSHA  
             CMPA  #$04   ; key 4?
             BNE   LEB81
             CLR   MODE_SHOWN   ; forces LRN_SHOWPTR to redraw afterwards
             LDAB  PND_ARM
             JSR   MAN_SHOWNOW   ; MAN_SHOWNOW: live readout while the key is held
LEB81:       JSR   KEYUP   ; wait until the key has been released
             PULA  
             CMPA  #$0F   ; key F: Record
             BNE   LEB9E
             TST   PB_WAIT   ; a playback arm move in progress?
             BEQ   LEB96
             LDAA  #$01   ; yes: treat it as a pendant arm move ...
             STAA  ARM_ON
             JSR   REC_FLUSH   ; REC_FLUSH: ... and record how far it got (overwrites the record being undone)
LEB96:       CLRA     ; mode 0 ...
             LDAB  #$C7   ; ... letter "F."
             JSR   SET_LMODE   ; SET_LMODE
             BRA   LEBD4
LEB9E:       CMPA  #$0B   ; key B: Backup
             BNE   LEBBA
             LDAA  LRN_PTRL
             LDAB  LRN_PTR
             JSR   PTR_BACK3   ; PTR_BACK3: step back onto the last record (to Executive if none)
             STAA  LRN_PTRL
             STAB  LRN_PTR
             LDAA  #$01   ; mode 1 ...
             LDAB  #$9F   ; ... letter "b."
             JSR   SET_LMODE   ; SET_LMODE
             BRA   LEBD4
LEBBA:       CMPA  #$07   ; key 7: Return
             BNE   LEBD4
             LDAA  LRN_PTRL
             LDAB  LRN_PTR
             JSR   PTR_BACK3   ; PTR_BACK3: last record (to Executive if none)
             STAA  REV_PTRL   ; REV_PTR walks backwards; LRN_PTR keeps appending
             STAB  REV_PTR
             LDAA  #$02   ; mode 2 ...
             LDAB  #$85   ; ... letter "r."
             JSR   SET_LMODE   ; SET_LMODE
LEBD4:       RTS   

;---------------------------------------------------------------
; PB_BACKUP - one pass of Backup mode (trigger held)
;
; Takes the record at LRN_PTR. A D3 arm move is undone by an absolute move back
; to where it started; C3/CC (drive, steering) and 8F records are stepped over
; without moving anything. Then dwells PB_TIMER passes with "b." blinking and
; moves LRN_PTR back one record, which erases it. Below LRN_START it returns to
; the Executive. A move cut short by releasing the trigger restarts here.
; Any other opcode (e.g. one keyed in by hand) also exits to the Executive.
;
; In:        LRN_PTR, PB_TIMER, PB_WAIT, PB_PAUSED
; Memory:    REC_xxx, PREV_ROT, ARM_START, MODE_CHAR, LRN_PTR
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: B
; Preserves: none   [static]
; Stack:     11 bytes max, including callees
; Exit:      RTS; falls into LEC82; tail-JMP to R_EXEC; tail-JMP to LEC82
; Calls:     R_EXEC, LEC82, MOT2ROT, MOTPOS, MOT_GO, PTR_BACK3
; Called from: LEARN, LRN_LOOP
;---------------------------------------------------------------
PB_BACKUP:   TST   PB_PAUSED   ; resuming after the trigger was released mid-move?
             BEQ   LEBE3
             JSR   MOT_GO   ; MOT_GO: restart the same move (REC_xxx still hold it)
             CLR   PB_PAUSED
             JMP   LEC82   ; return
LEBE3:       LDX   PB_TIMER   ; dwelling or waiting?
             BNE   LEC48
             LDX   LRN_PTR   ; fetch the record at LRN_PTR
             LDAA  $01,X
             TAB      ; B = byte 1 (direction bit 2)
             ANDA  #$E0   ; motor bits
             STAA  REC_MOTOR
             LDAA  $02,X   ; distance
             STAA  REC_POS
             CLR   REC_DIR
             LDAA  $00,X
             STAA  REC_OP
             CMPA  #$D3   ; arm relative move?
             BNE   LEC31
             LDAA  REC_MOTOR
             JSR   MOT2ROT   ; MOT2ROT: motor bits -> rotary code
             STAA  PREV_ROT   ; remember which motor
             JSR   MOTPOS   ; MOTPOS: A = its position now
             BITB  #$04   ; recorded as a decrease?
             BEQ   LEC19
             ADDA  REC_POS   ; undo a decrease: add the distance back
             BRA   LEC1C
LEC19:       SUBA  REC_POS   ; undo an increase: subtract it
LEC1C:       STAA  REC_POS   ; target = where the move started
             STAA  ARM_START
             LDAA  #$08
             STAA  REC_SPEED
             JSR   MOT_GO   ; MOT_GO: start the absolute move back, without waiting
             LDAA  #$01   ; wait for it before dwelling
             STAA  PB_WAIT
             BRA   LEC40
LEC31:       CMPA  #$CC   ; drive, steering and pause records are skipped
             BEQ   LEC40
             CMPA  #$C3
             BEQ   LEC40
             CMPA  #$8F
             BEQ   LEC40
             JMP   R_EXEC   ; unknown opcode: back to the Executive
LEC40:       LDX   #$0400   ; dwell count
             STX   PB_TIMER
             BRA   LEC82
LEC48:       TST   PB_WAIT   ; waiting for the arm?
             BEQ   LEC58
             LDAA  BUSY   ; arm channel still busy ($0B bit 2)?
             BITA  #$04
             BNE   LEC82
             CLR   PB_WAIT
             BRA   LEC82
LEC58:       DEX      ; count down the dwell
             STX   PB_TIMER
             LDAA  PB_TIMERL
             BITA  #$80   ; blink: blank while bit 7 of the count is set
             BEQ   LEC69
             CLRA  
             STAA  MODE_CHAR
             BRA   LEC6E
LEC69:       LDAA  #$9F   ; "b."
             STAA  MODE_CHAR
LEC6E:       LDX   PB_TIMER   ; dwell over?
             BNE   LEC82
             LDAA  LRN_PTRL
             LDAB  LRN_PTR
             JSR   PTR_BACK3   ; PTR_BACK3: drop this record (to Executive past the start)
             STAA  LRN_PTRL
             STAB  LRN_PTR

;---------------------------------------------------------------
; (shared RTS) - a bare RTS that nearby code branches to as its exit
;
; Changes:   nothing
; Preserves: A, B, X   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
; Called from: PB_BACKUP
;---------------------------------------------------------------
LEC82:       RTS      ; (also the JMP target used as a shared return)

;---------------------------------------------------------------
; PB_RETURN - one pass of Return mode (trigger held)
;
; Walks REV_PTR backwards through the program. Each D3 arm move is undone by an
; absolute move to where it started; when it completes, the undo is recorded
; at LRN_PTR as a new D3 (via REC_FLUSH), so after a full Return the program
; ends in its starting pose. Drive, steering and pause records are stepped over
; and NOT retraced. When REV_PTR passes LRN_START it returns to the Executive.
; (Emulator: "D3 28 09 D3 48 09" gained "D3 4C 09 D3 2C 09".)
; If the trigger was released mid-move, the partial record REC_FLUSH wrote is
; dropped and the move is restarted from REV_SAVE.
;
; In:        REV_PTR, LRN_PTR, PB_TIMER, PB_WAIT, PB_PAUSED, REV_SAVE
; Memory:    REC_xxx, PREV_ROT, ARM_START, ARM_ON, MODE_CHAR, LRN_PTR, REV_PTR
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: B
; Preserves: none   [static]
; Stack:     11 bytes max, including callees
; Exit:      RTS; falls into LED56; tail-JMP to R_EXEC; tail-JMP to LED56
; Calls:     R_EXEC, REC_FLUSH, LED56, MOT2ROT, MOTPOS, MOT_GO, PTR_BACK3
; Called from: LEARN, LRN_LOOP
;---------------------------------------------------------------
PB_RETURN:   TST   PB_PAUSED   ; resuming after the trigger was released mid-move?
             BEQ   LECAB
             LDAA  LRN_PTRL
             LDAB  LRN_PTR
             JSR   PTR_BACK3   ; PTR_BACK3: drop the partial record written at the release
             STAA  LRN_PTRL
             STAB  LRN_PTR
             LDX   REV_SAVE   ; target word saved when the move began
             STX   REC_DIR
             JSR   MOT_GO   ; MOT_GO: restart the move
             CLR   PB_PAUSED
             LDAA  #$01   ; record it again when it finishes
             STAA  ARM_ON
             JMP   LED56   ; return
LECAB:       LDX   PB_TIMER   ; dwelling or waiting?
             BNE   LED19
             LDX   REV_PTR   ; fetch the record at REV_PTR
             LDAA  $01,X
             TAB      ; B = byte 1 (direction bit 2)
             ANDA  #$E0
             STAA  REC_MOTOR
             LDAA  $02,X
             STAA  REC_POS
             CLR   REC_DIR
             LDAA  $00,X
             STAA  REC_OP
             CMPA  #$D3   ; arm relative move?
             BNE   LED02
             LDAA  REC_MOTOR
             JSR   MOT2ROT   ; MOT2ROT: motor bits -> rotary code
             STAA  PREV_ROT
             JSR   MOTPOS   ; MOTPOS: A = its position now
             STAA  ARM_START   ; start of the undo = start of what gets recorded
             BITB  #$04   ; recorded as a decrease?
             BEQ   LECE4
             ADDA  REC_POS   ; undo a decrease
             BRA   LECE7
LECE4:       SUBA  REC_POS   ; undo an increase
LECE7:       STAA  REC_POS
             LDX   REC_DIR   ; save ($00,target) in case of a pause
             STX   REV_SAVE
             LDAA  #$08
             STAA  REC_SPEED
             JSR   MOT_GO   ; MOT_GO: start the absolute move, without waiting
             LDAA  #$01
             STAA  PB_WAIT
             STAA  ARM_ON   ; ARM_ON: record it when it ends
             BRA   LED11
LED02:       CMPA  #$CC   ; drive, steering and pause records are skipped
             BEQ   LED11
             CMPA  #$C3
             BEQ   LED11
             CMPA  #$8F
             BEQ   LED11
             JMP   R_EXEC   ; unknown opcode: back to the Executive
LED11:       LDX   #$0400   ; dwell count
             STX   PB_TIMER
             BRA   LED56
LED19:       TST   PB_WAIT   ; waiting for the arm?
             BEQ   LED2C
             LDAA  BUSY   ; arm channel still busy ($0B bit 2)?
             BITA  #$04
             BNE   LED56
             JSR   REC_FLUSH   ; REC_FLUSH: record the completed return move
             CLR   PB_WAIT
             BRA   LED56
LED2C:       DEX      ; count down the dwell
             STX   PB_TIMER
             LDAA  PB_TIMERL
             BITA  #$80   ; blink: blank while bit 7 of the count is set
             BEQ   LED3D
             CLRA  
             STAA  MODE_CHAR
             BRA   LED42
LED3D:       LDAA  #$85   ; "r."
             STAA  MODE_CHAR
LED42:       LDX   PB_TIMER
             BNE   LED56
             LDAA  REV_PTRL
             LDAB  REV_PTR
             JSR   PTR_BACK3   ; PTR_BACK3: previous record (to Executive past the start)
             STAA  REV_PTRL
             STAB  REV_PTR

;---------------------------------------------------------------
; (shared RTS) - a bare RTS that nearby code branches to as its exit
;
; Changes:   nothing
; Preserves: A, B, X   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
; Called from: PB_RETURN
;---------------------------------------------------------------
LED56:       RTS      ; (also the JMP target used as a shared return)

;---------------------------------------------------------------
; DRV_RELEG - start another drive leg when one runs out
;
; A pendant drive leg is started for the maximum distance ($3FF counts). If the
; drive has gone idle while the trigger is still held, the leg ran its full
; length: start an identical one and report it so the caller records a full
; "CC" leg. (Emulator: a long drive recorded "CC 1B FF CC 1B FF ...".)
;
; In:        PND_ROT, $0B busy bit 0 (drive)
; Out:       C set = new leg started, REC_xxx describe it (distance $3FF);
;            C clear = drive still running                      (contract)
; Memory:    writes REC_xxx, starts the drive motor
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: A, X
; Preserves: none   [static]
; Stack:     9 bytes max, including callees
; Exit:      RTS
; Calls:     DRV_FIELDS, MOT_GO
; Called from: LEARN, LRN_LOOP, MANUAL, MAN_LOOP
;---------------------------------------------------------------
DRV_RELEG:   LDAB  BUSY
             BITB  #$01   ; drive still busy?
             BNE   LED6B
             LDAA  PND_ROT
             LDX   #$03FF   ; full leg
             JSR   DRV_FIELDS   ; DRV_FIELDS: fill REC_xxx for a drive move
             JSR   MOT_GO   ; MOT_GO: start it
             SEC      ; C = 1: record a leg
             RTS   
LED6B:       CLC   
             RTS   

;---------------------------------------------------------------
; MAN_BODY - pendant BODY control (trigger held)
;
; Rotary 1-3 drive forward slow/medium/fast, 5-7 reverse slow/medium/fast, N no
; drive; the leg is started once for $3FF counts. Motion LEFT steers to the
; left stop ($00), RIGHT to the right stop ($93), clear returns the wheel to
; centre ($49); each as a slow absolute steering move. Used by Manual mode and
; Learn Record mode.
;
; In:        PND_ROT, PND_MOT, DRV_ON, STR_ON, steering position $0006
; Out:       PREV_ROT, PREV_MOT updated                         (contract)
; Memory:    DRV_ON, STR_ON, REC_xxx; starts drive/steering motors
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: B, X
; Preserves: none   [static]
; Stack:     9 bytes max, including callees
; Exit:      RTS
; Calls:     DRV_FIELDS, MOT_GO
; Called from: LEARN, LRN_LOOP, MANUAL, MAN_LOOP
;---------------------------------------------------------------
MAN_BODY:    TST   DRV_ON   ; drive already running?
             BNE   LED87
             LDAA  PND_ROT
             CMPA  #$00   ; rotary at N: no drive
             BEQ   LED87
             LDX   #$03FF   ; maximum leg
             JSR   DRV_FIELDS   ; DRV_FIELDS: speed/direction from the rotary code
             LDAA  #$01
             STAA  DRV_ON
             JSR   MOT_GO   ; MOT_GO: start the drive leg
LED87:       TST   STR_ON   ; steering already moving?
             BNE   LEDD1
             LDAA  $06   ; current steering position
             STAA  REC_POS
             LDAB  PND_MOT
             CMPB  #$00   ; motion switch clear?
             BEQ   LEDAA
             CMPB  #$01   ; LEFT?
             BNE   LEDA2
             TSTA     ; (A is 0 already, or becomes 0: left stop)
             BEQ   LEDB0
             CLRA  
             BRA   LEDB0
LEDA2:       CMPA  #$93   ; RIGHT: right stop $93
             BEQ   LEDB0
             LDAA  #$93
             BRA   LEDB0
LEDAA:       CMPA  #$49   ; clear: centre $49
             BEQ   LEDB0
             LDAA  #$49
LEDB0:       CMPA  $06   ; already there?
             BEQ   LEDD1
             STAA  REC_POS
             CLR   REC_DIR
             LDAA  #$C3   ; C3 absolute move, wait
             STAA  REC_OP
             LDAA  #$E0   ; motor 7 = steering
             STAA  REC_MOTOR
             LDAA  #$08   ; speed bits 01 (slow)
             STAA  REC_SPEED
             JSR   MOT_GO   ; MOT_GO: start the steering move
             LDAA  #$01
             STAA  STR_ON
LEDD1:       LDAA  PND_MOT
             STAA  PREV_MOT
             LDAA  PND_ROT
             STAA  PREV_ROT
             RTS   

;---------------------------------------------------------------
; MAN_ARM - pendant ARM control (trigger held)
;
; When the rotary or motion switch has changed and both select something,
; starts a slow absolute move of the chosen arm/head motor toward its end of
; travel in the direction of the motion switch (ARM_LIMIT table), noting the
; start position in ARM_START. The caller aborts the move (and records it in
; Learn) when a switch changes again or the trigger is released.
;
; In:        PND_ROT, PND_MOT, PREV_ROT, PREV_MOT
; Out:       PREV_ROT, PREV_MOT updated                         (contract)
; Memory:    ARM_ON, ARM_START, REC_xxx; starts an arm motor
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: X
; Preserves: none   [static + measured: 6,115 calls, 1/4 branches]
; Stack:     9 bytes max, including callees (observed 0)
; Cycles:    observed 29-51 E cycles over 6,115 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     ROT2MOT, MOTPOS, ARM_LIMIT, MOT_GO
; Called from: LEARN, LRN_LOOP, MANUAL, MAN_LOOP
;---------------------------------------------------------------
MAN_ARM:     LDAA  PND_ROT
             LDAB  PND_MOT
             CMPA  PREV_ROT   ; anything changed?
             BNE   LEDEE
             CMPB  PREV_MOT
             BEQ   LEE26
LEDEE:       CMPA  #$00   ; rotary at N: nothing to move
             BEQ   LEE1A
             CMPB  #$00   ; motion switch clear: nothing to move
             BEQ   LEE1A
             JSR   ARM_LIMIT   ; ARM_LIMIT: REC_POS = end of travel in that direction
             LDAA  PND_ROT
             JSR   MOTPOS   ; MOTPOS: A = position now
             CMPA  REC_POS   ; already at the end?
             BEQ   LEE1A
             STAA  ARM_START   ; remember where the move began
             LDAA  PND_ROT
             JSR   ROT2MOT   ; ROT2MOT: REC_MOTOR = motor bits
             LDAA  #$08   ; speed bits 01 (slow)
             STAA  REC_SPEED
             JSR   MOT_GO   ; MOT_GO: start the absolute move without waiting
             LDAA  #$01   ; ARM_ON
             STAA  ARM_ON
LEE1A:       LDAA  PND_ROT
             STAA  PREV_ROT
             LDAA  PND_MOT
             STAA  PREV_MOT
LEE26:       RTS   

;---------------------------------------------------------------
; DRV_ABORT - ask the interrupt code to stop the drive motor
;
; If the drive is busy, clears its busy bit, sets the target speed to $3F
; (stopped) and raises the drive abort request bit in $0C, all with interrupts
; masked (SEI ... CLI window).
;
; In:        $0B busy bits
; Memory:    $0B bit 0, $0C bit 0, $0F01 (drive target speed)
;
; Changes:   A, flags I N Z V
; Preserves: B, X   [static + measured: 3 calls, 0/1 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 14 E cycles on every call over 3 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: MANUAL, MAN_LOOP, REC_FLUSH, ROOM_CHK
;---------------------------------------------------------------
DRV_ABORT:   LDAA  BUSY
             BITA  #$01
             BEQ   LEE41
             SEI      ; interrupts masked from here ...
             NOP   
             LDAA  BUSY
             ANDA  #$FE   ; drive no longer busy
             STAA  BUSY
             LDAA  #$3F   ; target speed $3F = stopped
             STAA  DRVTARGET
             LDAA  #$01
             ORAA  ABORTREQ   ; request the abort
             STAA  ABORTREQ
             CLI      ; ... to here
LEE41:       RTS   

;---------------------------------------------------------------
; DRV_GATE - cut the drive unless the pendant is driving it
;
; The drive may run only while the trigger is held with BODY selected and the
; rotary off N; otherwise both current and target drive speed ($0F00/$0F01)
; are forced to $3F (stopped) at once, without the ramp.
;
; In:        PND_TRIG, PND_ARM, PND_ROT
; Memory:    may write $0F00, $0F01
;
; Changes:   A, flags N Z V C ; on some paths: A
; Preserves: B, X   [static + measured: 6,532 calls, 1/2 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 27-37 E cycles over 6,532 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: LEARN, LRN_LOOP, MANUAL, MAN_LOOP
;---------------------------------------------------------------
DRV_GATE:    TST   PND_TRIG
             BEQ   LEE51
             TST   PND_ARM
             BNE   LEE51
             TST   PND_ROT
             BNE   LEE59   ; trigger, BODY, rotary off N: leave it running
LEE51:       LDAA  #$3F   ; stop: speed $3F
             STAA  DRVNOW
             STAA  DRVTARGET
LEE59:       RTS   

;---------------------------------------------------------------
; SET_LMODE - select a Learn sub-mode
;
; In:        A = mode (0 record, 1 backup, 2 return), B = its letter pattern
; Out:       LRN_MODE, MODE_CHAR set; PB_TIMER, PB_WAIT, PB_PAUSED cleared
;
; Changes:   X, flags N Z V C
; Preserves: A, B   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
; Called from: LRN_KEY
;---------------------------------------------------------------
SET_LMODE:   STAA  LRN_MODE
             STAB  MODE_CHAR
             LDX   #$0000
             STX   PB_TIMER
             CLR   PB_WAIT
             CLR   PB_PAUSED
             RTS   

;---------------------------------------------------------------
; ROT2MOT - pendant rotary code -> motor select bits
;
; Searches ROTTAB for the rotary code. There is no end marker: code 4 (which
; the pendant's diode encoder never produces) would run the search on into the
; code that follows.
;
; In:        A = rotary code (0-3, 5-7)
; Out:       A = REC_MOTOR = motor bits (mmm00000)              (contract)
; Memory:    writes REC_MOTOR
;
; Changes:   A, X, flags N Z V C
; Preserves: B   [static + measured: 6,532 calls, 0/1 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 27 E cycles on every call over 6,532 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: MAN_ARM, MOTPOS
;---------------------------------------------------------------
ROT2MOT:     LDX   #ROTTAB
LEE70:       CMPA  $00,X
             BEQ   LEE78
             INX   
             INX   
             BRA   LEE70
LEE78:       LDAA  $01,X
             STAA  REC_MOTOR
             RTS   

;---------------------------------------------------------------
; MOT2ROT - motor select bits -> pendant rotary code
;
; Reverse search of ROTTAB, used to replay D3 records. Unbounded like ROT2MOT:
; a D3 record for the drive ($00 -> N) is harmless, one for steering ($E0)
; would scan past the table (only possible in a hand-edited program).
;
; In:        A = motor bits (mmm00000)
; Out:       A = rotary code                                    (contract)
;
; Changes:   A, X, flags N Z V C
; Preserves: B   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
; Called from: PB_BACKUP, PB_RETURN
;---------------------------------------------------------------
MOT2ROT:     LDX   #ROTTAB
LEE81:       CMPA  $01,X
             BEQ   LEE89
             INX   
             INX   
             BRA   LEE81
LEE89:       LDAA  $00,X
             RTS   
* rotary code, motor bits: head, extend, shoulder, wrist pivot, wrist rotate, gripper, N
ROTTAB:      FCB   $07,$C0   ; head=7 ext=6 shoulder=5 pivot=1 rotate=2 grip=3 N=0
             FCB   $06,$20
             FCB   $05,$40
             FCB   $01,$80
             FCB   $02,$60
             FCB   $03,$A0
             FCB   $00,$00

;---------------------------------------------------------------
; MOTPOS - current position of the motor picked by a rotary code
;
; Converts the rotary code to a motor number (ROT2MOT, then rotate the top
; three bits down) and reads that motor's byte in the position table
; $0000-$0005 (motor 1 extend ... 6 head).
;
; In:        A = rotary code, not 0
; Out:       A = position byte, X = its address ($0000-$0005)  (contract)
; Memory:    writes REC_MOTOR, TMP_PTR
;
; Changes:   A, X, flags N Z V C
; Preserves: B   [static + measured: 6,532 calls]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 81 E cycles on every call over 6,532 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     ROT2MOT
; Called from: MAN_SHOW, MAN_SHOWNOW, REC_FLUSH, PB_BACKUP, PB_RETURN, MAN_ARM
;---------------------------------------------------------------
MOTPOS:      BSR   ROT2MOT   ; ROT2MOT: A = mmm00000
             ROLA     ; four 9-bit rotates bring mmm down to bits 2-0 (C is clear after the CMPA match)
             ROLA  
             ROLA  
             ROLA  
             DECA     ; motor 1-6 -> table offset 0-5
             STAA  TMP_PTRL
             CLR   TMP_PTR
             LDX   TMP_PTR   ; X = $00xx
             LDAA  $00,X   ; position byte
             STAA  TMP_PTRL
             LDX   TMP_PTR
             RTS   

;---------------------------------------------------------------
; ARM_LIMIT - end-of-travel target for a pendant arm move
;
; In:        A = rotary code (1-3, 5-7), B = motion (1 left, 2 right)
; Out:       REC_POS = target position, REC_DIR = 0             (contract)
;
; Changes:   A, B, X, flags N Z V C
; Preserves: none   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
; Called from: MAN_ARM
;---------------------------------------------------------------
ARM_LIMIT:   LDX   #LIMTAB
LEEB6:       CMPA  $00,X
             BEQ   LEEBF
             INX   
             INX   
             INX   
             BRA   LEEB6
LEEBF:       INX      ; step to the LEFT (1) or RIGHT (2) column
             DECB  
             BNE   LEEBF
             LDAA  $00,X
             STAA  REC_POS
             CLR   REC_DIR
             RTS   
* rotary code, LEFT target, RIGHT target. Wrist pivot and gripper run the other way;
* the head target $C9 lies past the $C2 home-table limit (the switch is released first).
LIMTAB:      FCB   $07,$00,$C9   ; head, extend, shoulder, pivot, rotate, gripper
             FCB   $06,$00,$98
             FCB   $05,$00,$86
             FCB   $01,$A5,$00
             FCB   $02,$00,$93
             FCB   $03,$75,$00

;---------------------------------------------------------------
; DRV_FIELDS - fill the record fields for a drive move
;
; Rotary codes double as drive settings: bits 1-0 = speed (1 slow, 2 medium,
; 3 fast), bit 2 = reverse.
;
; In:        A = rotary code, X = distance in encoder counts (10 bits)
; Out:       REC_MOTOR = 0 (drive), REC_SPEED = speed<<3,
;            REC_DIR:REC_POS = direction bit | distance, REC_OP = DRV_OP (contract)
; Memory:    writes TMP_PTR
;
; Changes:   A, B, X, flags H N Z V C
; Preserves: none   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
; Called from: REC_FLUSH, DRV_RELEG, MAN_BODY
;---------------------------------------------------------------
DRV_FIELDS:  LDAB  #$00   ; motor 0 = drive
             STAB  REC_MOTOR
             TAB   
             ANDB  #$03   ; speed 1-3 ...
             ASLB     ; ... into bits 4-3
             ASLB  
             ASLB  
             STAB  REC_SPEED
             ANDA  #$04   ; reverse bit
             STX   TMP_PTR
             LDAB  TMP_PTR   ; distance bits 9-8
             ANDB  #$03
             ABA      ; merge with the direction bit
             STAA  TMP_PTR
             LDX   TMP_PTR
             STX   REC_DIR
             LDAA  DRV_OP   ; C3 or CC (SET_DRVOP)
             STAA  REC_OP
             RTS   

;---------------------------------------------------------------
; REC_MOVE - append a 3-byte motor record to the Learn program
;
; Writes REC_OP and the motor word at LRN_PTR, advances LRN_PTR by 3 and puts
; a $3A (RETURN TO EXECUTIVE) after it, so the program is always runnable.
;
; In:        REC_OP, REC_MOTOR, REC_SPEED, REC_DIR, REC_POS, LRN_PTR
; Out:       LRN_PTR += 3                                       (contract)
; Memory:    writes 4 bytes of the program area
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     7 bytes max, including callees
; Exit:      RTS
; Calls:     PUT_WORD, ROOM_CHK
; Called from: LEARN, LRN_LOOP, REC_FLUSH
;---------------------------------------------------------------
REC_MOVE:    LDAA  #$04
             BSR   ROOM_CHK   ; ROOM_CHK: 4 bytes free? (hangs on "FULL" otherwise)
             LDAA  REC_OP
             STAA  $00,X
             INX   
             BSR   PUT_WORD   ; PUT_WORD: motor word bytes
             INX   
             INX   
             STX   LRN_PTR
             LDAA  #$3A   ; terminator (not counted in LRN_PTR)
             STAA  $00,X
             RTS   

;---------------------------------------------------------------
; REC_PAUSE - append "8F 00 20" (PAUSE 2 s) to the Learn program
;
; In:        LRN_PTR
; Out:       LRN_PTR += 3, $3A written after it                 (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     7 bytes max, including callees
; Exit:      RTS
; Calls:     ROOM_CHK
; Called from: REC_IDLE
;---------------------------------------------------------------
REC_PAUSE:   LDAA  #$04
             BSR   ROOM_CHK   ; ROOM_CHK: 4 bytes free?
             LDAA  #$8F   ; PAUSE ...
             STAA  $00,X
             CLR   $01,X
             LDAA  #$20   ; ... 32/16 s
             STAA  $02,X
             LDAA  #$3A   ; terminator
             STAA  $03,X
             INX   
             INX   
             INX   
             STX   LRN_PTR
             RTS   

;---------------------------------------------------------------
; PUT_WORD - store the motor word built in REC_xxx at X
;
; In:        X = destination
; Out:       0,X = REC_MOTOR+REC_SPEED+REC_DIR, 1,X = REC_POS  (contract)
;
; Changes:   A, flags H N Z V C
; Preserves: B, X   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
; Called from: REC_MOVE, MOT_GO
;---------------------------------------------------------------
PUT_WORD:    LDAA  REC_MOTOR
             ADDA  REC_SPEED
             ADDA  REC_DIR
             STAA  $00,X
             LDAA  REC_POS
             STAA  $01,X
             RTS   

;---------------------------------------------------------------
; MOT_GO - start the motor move described by REC_xxx, no wait
;
; Builds the motor word in $0F1E/$0F1F with "no wait" in $0F20 and calls the
; Robot Interpreter's absolute motor-start code.
;
; In:        REC_MOTOR, REC_SPEED, REC_DIR, REC_POS
; Memory:    writes $0F1E-$0F20
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     7 bytes max, including callees
; Exit:      RTS
; Calls:     MOT_START, PUT_WORD
; Called from: PB_BACKUP, PB_RETURN, DRV_RELEG, MAN_BODY, MAN_ARM
;---------------------------------------------------------------
MOT_GO:      LDX   #$0F1E
             BSR   PUT_WORD   ; PUT_WORD: word into $0F1E/$0F1F
             CLR   WAITMASK   ; 0 = do not wait for completion
             JSR   MOT_START   ; start the motor from the word at $0F1E
             RTS   

;---------------------------------------------------------------
; ROOM_CHK - make sure the Learn program has room
;
; If LRN_PTR + A passes LRN_END, stops the drive, steering and arm, shows
; "FULL" and hangs at FULL_HANG until RESET (confirmed in the emulator with a
; 16-byte program area).
;
; In:        A = bytes needed
; Out:       X = LRN_PTR                                        (contract)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     5 bytes max, including callees
; Exit:      RTS
; Calls:     ABT_STEER, ABT_ARM, DRV_ABORT, CLRDIS, OUTSTR
; Called from: REC_MOVE, REC_PAUSE, REC_POSALL
;---------------------------------------------------------------
ROOM_CHK:    CLRB  
             ADDA  LRN_PTRL   ; B:A = LRN_PTR + A
             ADCB  LRN_PTR
             CMPB  LRN_END   ; compare with LRN_END (high, then low)
             BNE   LEF62
             CMPA  LRN_ENDL
LEF62:       BLS   LEF7A   ; fits
             JSR   DRV_ABORT   ; DRV_ABORT: stop the drive
             JSR   ABT_STEER   ; abort steering and wait
             JSR   ABT_ARM   ; abort the arm and wait
             JSR   CLRDIS   ; CLRDIS: clear the display
             JSR   OUTSTR   ; OUTSTR: inline string follows
             FCB   $47,$3E,$0E,$0E,$A0   ; display "FULL'."
FULL_HANG:   BRA   FULL_HANG   ; hang here; only RESET leaves
LEF7A:       LDX   LRN_PTR
             RTS   

;---------------------------------------------------------------
; REC_POSALL - append "FD p1..p7" (move all to the current pose)
;
; Opens a Learn program: the FD record holds the seven current motor
; positions $0000-$0006 so playback first returns to the starting pose.
;
; In:        LRN_PTR
; Out:       LRN_PTR += 8, $3A written after it                 (contract)
; Memory:    writes 9 bytes of the program area
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     7 bytes max, including callees
; Exit:      RTS
; Calls:     ROOM_CHK
; Called from: LRN_SETUP
;---------------------------------------------------------------
REC_POSALL:  LDAA  #$09
             BSR   ROOM_CHK   ; ROOM_CHK: 9 bytes free?
             LDAA  #$FD   ; MOVE ALL
             STAA  $00,X
             LDAA  $00
             STAA  $01,X
             LDAA  $01
             STAA  $02,X
             LDAA  $02
             STAA  $03,X
             LDAA  $03
             STAA  $04,X
             LDAA  $04
             STAA  $05,X
             LDAA  $05
             STAA  $06,X
             LDAA  $06
             STAA  $07,X
             LDAA  #$3A   ; terminator
             STAA  $08,X
             LDAA  LRN_PTRL
             LDAB  LRN_PTR
             ADDA  #$08   ; LRN_PTR += 8
             ADCB  #$00
             STAA  LRN_PTRL
             STAB  LRN_PTR
             RTS   

;---------------------------------------------------------------
; PTR_BACK3 - step a program pointer back one 3-byte record
;
; Leaves Learn mode for the Executive ($E102 -> $F423) when the result would
; fall below LRN_START, which is how Backup and Return end.
;
; In:        A = pointer low byte, B = pointer high byte (note: low in A)
; Out:       B:A = pointer - 3                                  (contract)
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: X
; Preserves: none   [static]
; Stack:     9 bytes max, including callees
; Exit:      RTS; tail-JMP to R_EXEC
; Calls:     R_EXEC
; Called from: LRN_KEY, PB_BACKUP, PB_RETURN
;---------------------------------------------------------------
PTR_BACK3:   SUBA  #$03
             SBCB  #$00
             CMPB  LRN_START   ; compare with LRN_START (high, then low)
             BNE   LEFC3
             CMPA  LRN_STARTL
LEFC3:       BCC   LEFC8   ; still at or above the start
             JMP   R_EXEC   ; past the start: back to the Executive
LEFC8:       RTS   

;---------------------------------------------------------------
; IRQ - interrupt dispatcher (IRQ vector $FFF8)
;
; Reads all eight flip-flops from IRQFLAGS once, acknowledges them, then
; services each set flag in a fixed order: sonar, drive encoder, 1,024 Hz
; tick, logic battery low, motor battery low, then the three user vectors
; (motion $0027, trigger $002A, experimental $002D). A holds the flag byte
; throughout; every service routine preserves A.
;
; Acknowledge: writing $C200 resets each flip-flop whose bit is 0 and
; enables those whose bit is 1. The ROM writes $01 (reset everything except
; sonar, so an echo arriving after the read is not lost) and then IRQMASK.
; Only when sonar was serviced is it reset too (CLR at $EFD6). A non-sonar
; flag that sets between the read and the $01 write is lost.
;
; Interrupt masking: the CPU enters with I=1, but TICK executes CLI at $F034,
; so when a tick was pending everything after it (battery handlers and the
; three user vectors) runs with interrupts enabled (follows from the code;
; the manual says the vectors run masked).
;
; In:        IRQFLAGS, IRQMASK
; Memory:    writes IRQFLAGS; calls HK_IRQ, VEC_MOTION, VEC_TRIG, VEC_EXP
;
; Changes:   flags H N Z V C only inside the handler (RTI restores CC)
; Saves:     CC, B, A, X, PC (7-byte hardware frame); restored by RTI
; Preserves: A, B, X, CC for the interrupted code   [static + measured: 630,086 calls, 8/8 branches]
; Stack:     12 bytes max, including callees (observed 12)
; Cycles:    observed 134-2,786,155 E cycles over 630,086 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTI
; Calls:     TICK, ENCODER, SONAR, LOGIC_LOW, MOTOR_LOW, RAM hook $0018, RAM hook $0027, RAM hook $002A, RAM hook $002D
;---------------------------------------------------------------
IRQ:         LDAA  IRQFLAGS   ; A = pending flags (bit set = request)
             JSR   >HK_IRQ   ; hook HK_IRQ: user code may inspect or edit A (default RTS)
             BITA  #$01   ; bit 0: sonar echo/timeout?
             BEQ   IRQ_ACK
             JSR   SONAR   ; SONAR: store range in SONARRANGE, count the hit
             CLR   IRQFLAGS   ; reset the sonar flip-flop (all bits 0 = all reset)
IRQ_ACK:     LDAB  #$01   ; $01: reset every flip-flop except sonar
             STAB  IRQFLAGS
             LDAB  IRQMASK   ; then re-enable the sources in IRQMASK
             STAB  IRQFLAGS
             BITA  #$40   ; bit 6: drive wheel encoder pulse?
             BEQ   LEFEB
             JSR   ENCODER   ; ENCODER: count distance and odometers
LEFEB:       BITA  #$10   ; bit 4: 1,024 Hz clock tick?
             BEQ   LEFF2
             JSR   TICK   ; TICK: motor stepping, drive ramp, speech (leaves I=0)
LEFF2:       BITA  #$08   ; bit 3: logic battery low?
             BEQ   LEFF9
             JSR   LOGIC_LOW   ; LOGIC_LOW: warn, speak, maybe sleep, wait for a key
LEFF9:       BITA  #$04   ; bit 2: motor battery low?
             BEQ   LF000
             JSR   MOTOR_LOW   ; MOTOR_LOW: stop drive, show "dr Lo.", wait for a key
LF000:       BITA  #$02   ; bit 1: motion detector?
             BEQ   LF007
             JSR   >VEC_MOTION   ; user motion vector (default RTS)
LF007:       BITA  #$20   ; bit 5: pendant trigger?
             BEQ   LF00E
             JSR   >VEC_TRIG   ; user trigger vector (default RTS)
LF00E:       BITA  #$80   ; bit 7: experimental board?
             BEQ   LF015
             JSR   >VEC_EXP   ; user experimental vector (default RTS)
LF015:       RTI   

;---------------------------------------------------------------
; TICK - 1,024 Hz real-time-clock service
;
; Per-tick schedule (one tick = 976.6 us = 874 E cycles):
;   every tick:  TICKS += 1; JSR HK_TICK
;                if BUSY bit 4 (ramp): DRVRAMP - it moves the drive speed one
;                  step up only on ticks where TICKS & $1F = 0 (every 32 ticks,
;                  31.25 ms) and one step down only where TICKS & $03 = 0
;                  (every 4 ticks); it rewrites DRIVE every tick
;                if BUSY bit 0 (drive): JSR HK_DRIVE
;                STEERHOLD: steering coils held or released while idle
;                CLI - from here on encoder/sonar interrupts may nest
;                if BUSY bit 1: decrement CCB_STEER+7; on zero CHSTEP (one phase
;                  step every N ticks, N = 2..7 by motor and speed, see $F0EF)
;                if BUSY bit 2: the same for CCB_ARM
;                if BUSY bit 3: SPEECH (feeds one phoneme when the SC-01 asks)
; A finished channel returns C=1 and its BUSY bit is cleared here.
; Emulator: logged $C260/$C280 writes every 3 ticks for medium steering,
; $C2A0 +1 every 32 ticks while accelerating and -1 every 4 ticks while
; stopping; worst-case IRQ time with drive+steering+arm+speech was 652
; cycles, under the 874-cycle tick, so the tick never re-entered itself.
;
; In:        BUSY, TICKS
; Out:       A preserved                                       (contract)
; Memory:    TICKS, BUSY; see DRVRAMP, STEERHOLD, CHSTEP, SPEECH
;
; Changes:   B, X, flags H I N Z V C
; Preserves: A   [static + measured: 630,083 calls, 10/10 branches]
; Stack:     6 bytes max, including callees (observed 6)
; Cycles:    observed 125-455 E cycles over 630,083 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     DRVRAMP, STEERHOLD, CHSTEP, SPEECH, RAM hook $001B, RAM hook $001E
; Called from: IRQ
;---------------------------------------------------------------
TICK:        PSHA  
             LDAB  TICKS   ; bump the tick counter; B = new count, used by DRVRAMP
             INCB  
             STAB  TICKS
             JSR   >HK_TICK   ; hook HK_TICK (default RTS; must preserve B or the ramp timing shifts)
             LDAA  BUSY
             BITA  #$10   ; bit 4: drive ramp running?
             BEQ   LF02A
             JSR   DRVRAMP   ; DRVRAMP: step DRIVE toward DRVTARGET
LF02A:       BITA  #$01   ; bit 0: drive distance still counting?
             BEQ   LF031
             JSR   >HK_DRIVE   ; hook HK_DRIVE (default RTS)
LF031:       JSR   STEERHOLD   ; STEERHOLD: hold/release steering coils when steering is idle
             CLI      ; interrupts on: encoder and sonar can now nest inside the tick
             LDAA  #$02   ; A = steering busy bit
             BITA  BUSY
             BEQ   LF04B
             LDX   #$0EE4   ; steering control block
             DEC   $07,X   ; step prescaler expired?
             BNE   LF04B
             JSR   CHSTEP   ; CHSTEP: one phase step; C=1 when the move is over (A comes back = ~$02)
             BCC   LF04B
             ANDA  BUSY   ; clear the steering busy bit
             STAA  BUSY
LF04B:       LDAA  #$04   ; A = arm channel busy bit
             BITA  BUSY
             BEQ   LF061
             LDX   #$0EF0   ; arm control block
             DEC   $07,X   ; step prescaler expired?
             BNE   LF061
             JSR   CHSTEP   ; CHSTEP: one phase step; C=1 when done (A = ~$04)
             BCC   LF061
             ANDA  BUSY   ; clear the arm busy bit
             STAA  BUSY
LF061:       LDAA  #$08   ; speech busy?
             BITA  BUSY
             BEQ   LF072
             JSR   SPEECH   ; SPEECH: feed the SC-01; C=1 when the utterance is finished
             BCC   LF072
             LDAA  BUSY
             ANDA  #$F7   ; clear the speech busy bit
             STAA  BUSY
LF072:       PULA  
             RTS   

;---------------------------------------------------------------
; DRVRAMP - ramp the drive motor one step toward its target
;
; DRIVE byte: bit 7 reverse, bit 6 on, bits 5-0 speed; $3F/$BF = off.
; Speeding up (same direction, |current| < |target|) adds 1 only when
; TICKS & $1F = 0: one step per 32 ticks, $40 -> $7F in about 2 s.
; Slowing down, or any direction change, subtracts 1 when TICKS & 3 = 0
; (every 4 ticks, about 250 ms from full speed). A direction change
; therefore runs down to off ($3F), takes the new direction bit there and
; then ramps up. When the output reaches off and ABORTREQ bit 0 is set
; the stop is complete: BUSY and ABORTREQ bits 0 and 4 are cleared.
; DRIVE is rewritten on every call, even when nothing changed.
;
; In:        B = TICKS (from TICK); DRVNOW, DRVTARGET, ABORTREQ
; Out:       A preserved                                       (contract)
; Memory:    DRVNOW, DRIVE port, BUSY/ABORTREQ bits 0 and 4
;
; Changes:   B, flags N Z V C ; on some paths: B
; Preserves: A, X   [static + measured: 2,723 calls, 5/7 branches]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 45-127 E cycles over 2,723 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: TICK
;---------------------------------------------------------------
DRVRAMP:     PSHA  
             LDAA  DRVTARGET   ; target
             CMPA  DRVNOW   ; already there? just refresh the port
             BEQ   DRV_OUT
             PSHB  
             EORA  DRVNOW   ; direction bits differ (N set)?
             BMI   DRV_DECEL   ; yes: slow down first
             LDAA  DRVNOW   ; compare magnitudes (bits 6-0)
             ANDA  #$7F
             LDAB  DRVTARGET
             ANDB  #$7F
             CBA      ; current < target (C set): speed up
             BCS   DRV_ACCEL
DRV_DECEL:   PULB     ; B = tick count again
             BITB  #$03   ; slow down only on every 4th tick
             BNE   LF0C8
             LDAA  DRVNOW
             DECA     ; one step slower
             BRA   DRV_OUT
DRV_ACCEL:   PULB  
             BITB  #$1F   ; speed up only on every 32nd tick
             BNE   LF0C8
             LDAA  DRVNOW
             INCA     ; one step faster
DRV_OUT:     TAB      ; B = magnitude of the new output
             ANDB  #$7F
             CMPB  #$3F   ; above $3F means the motor is on (bit 6)
             BGT   LF0C2
             LDAA  ABORTREQ   ; motor is off: was a stop requested?
             BITA  #$01
             BEQ   LF0BB
             ANDA  #$EE   ; stop done: clear request bits 0 and 4
             STAA  ABORTREQ
             LDAA  BUSY
             ANDA  #$EE   ; and the drive busy/ramp bits
             STAA  BUSY
LF0BB:       LDAA  DRVTARGET   ; off, but already showing the target's direction bit
             ANDA  #$80
             ORAA  #$3F
LF0C2:       STAA  DRVNOW   ; remember the output
             STAA  DRIVE   ; and drive the motor
LF0C8:       PULA  
             RTS   

;---------------------------------------------------------------
; STEERHOLD - steering coils while the steering motor is idle
;
; With steering idle (BUSY bit 1 clear): while the drive is busy or
; ramping (BUSY bits 0/4) the steering phases are held at ~$66 = $9_ (the
; steering's phase-0 pattern), which locks the wheel straight against the
; drive torque; otherwise they are released ($F_, the steering driver is
; active low). The low nibble (pivot/rotate) is kept from MOTA_SH.
; Emulator: $C260 high nibble goes $F -> $9 when a drive starts and back
; to $F when it ends.
;
; In:        BUSY, MOTA_SH
; Memory:    MOTA (port), MOTA_SH
;
; Changes:   A, B, flags H N Z V C ; on some paths: B
; Preserves: X   [static + measured: 630,088 calls, 2/3 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 20-50 E cycles over 630,088 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: TICK
;---------------------------------------------------------------
STEERHOLD:   LDAA  BUSY
             BITA  #$11   ; drive busy or ramping?
             BEQ   LF0DA
             BITA  #$02   ; steering moving: its own phases are on the port
             BNE   LF0EE
             LDAA  PHASETAB   ; hold pattern: ~$66 = $99 (inverted like all steering patterns)
             COMA  
             BRA   LF0E0
LF0DA:       BITA  #$02   ; steering moving: leave it alone
             BNE   LF0EE
             LDAA  #$F0   ; release: all four steering lines high
LF0E0:       ANDA  #$F0   ; keep the steering nibble
             LDAB  MOTA_SH   ; plus the pivot/rotate nibble now on the port
             ANDB  #$0F
             ABA   
             STAA  MOTA
             STAA  MOTA_SH
LF0EE:       RTS   

;---------------------------------------------------------------
; CHSTEP - advance one stepper channel by one phase step
;
; Channel control block (12 bytes, at CCB_STEER $0EE4 and CCB_ARM $0EF0; +0..+6
; copied from the motor's descriptor at $E2AA by $E224):
;   +0     phase mask on the port ($F0 high nibble, $0F low nibble)
;   +1     steps-per-unit mask ($1F = 32, $07 = 8, $03 = 4 phase steps)
;   +2,+3  port address (MOTA $C260 or MOTB $C280)
;   +4,+5  address of the motor's position byte ($0000-$0006)
;   +6     limit-switch mask for MOTA input bits (e.g. head $12, steering $48)
;   +7     step prescaler, counted down by TICK
;   +8     prescaler reload = ticks per step (descriptor byte 8/9/10 for
;          speed 1/2/3, e.g. steering 6/3/2 = 171/341/512 steps/s; speed 0,
;          undocumented, reloads from byte 7 (the select byte): $80 = 128,
;          $40 = 64, $00 = 256 ticks per step; head at speed 0 stepped every
;          128 ticks in the emulator)
;   +9     bit 2 = direction (1 = position decreasing), bits 1-0 = phase index
;   +10,11 phase steps still to go (16-bit, = units << log2(steps per unit))
; Each call: stop if the count is 0; stop if a limit switch for the current
; direction is closed (bits 6-4 when decreasing, 3-1 when increasing; a
; decreasing-side switch also re-zeroes the position byte); else output
; PHASETAB[+9], advance the index, decrement the count, and on every unit
; boundary (count & mask = 0) INC/DEC the position byte. An abort request
; (ABORTREQ bit = channel bit) is honoured only at a unit boundary, by
; zeroing the count, so the position byte stays exact.
;
; In:        X = control block; A = channel's BUSY bit ($02 or $04)
; Out:       C=0 still moving; C=1 finished, A = ~bit (mask to clear BUSY)
; Memory:    CB_PTR, block +7/+9/+10/+11, position byte, ABORTREQ, port
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: B, X
; Preserves: none   [static + measured: 39,536 calls, 7/7 branches]
; Stack:     3 bytes max, including callees (observed 3)
; Cycles:    observed 106-310 E cycles over 39,536 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PHASEOUT
; Called from: TICK
;---------------------------------------------------------------
CHSTEP:      STX   CB_PTR   ; remember the block
             PSHA     ; save the channel bit
             LDAA  $0A,X   ; steps left = 0?
             ORAA  $0B,X
             BEQ   CH_STOP   ; yes: release coils and report done
             LDAB  MOTA   ; limit switches are active low: invert
             COMB  
             ANDB  $06,X   ; keep this motor's switches
             LDAA  $09,X   ; A = direction/phase index
             BITA  #$04   ; decreasing?
             BEQ   LF109
             ANDB  #$70   ; decreasing-side switches (steer CW, arm up, head CCW)
             BRA   LF10B
LF109:       ANDB  #$0E   ; increasing-side switches (steer CCW, arm down, head CW)
LF10B:       BNE   CH_LIMIT   ; a switch is closed: stop
             CLRB     ; B:A = PHASETAB + index (16-bit add)
             ADDA  #LO(PHASETAB)
             ADCB  #HI(PHASETAB)
             STAA  $0F55   ; build the pointer in $0F54
             STAB  $0F54
             LDX   $0F54
             LDAA  $00,X   ; phase pattern for this step
             BSR   PHASEOUT   ; PHASEOUT: put the pattern on this motor's nibble
             LDX   CB_PTR   ; X = block again
             LDAA  $09,X
             TAB      ; B = direction bit
             ANDB  #$04
             INCA     ; next phase, wrapping 0-3
             ANDA  #$03
             ABA      ; same direction
             STAA  $09,X
             LDAA  $0B,X   ; count -= 1 (16-bit)
             LDAB  $0A,X
             SUBA  #$01
             SBCB  #$00
             STAA  $0B,X
             STAB  $0A,X
             PULB     ; B = channel bit
             ANDA  $01,X   ; low count bits all zero = one whole position unit done
             BNE   LF15C
             LDAA  $09,X   ; A = direction
             LDX   $04,X   ; X = position byte
             BITA  #$04
             BEQ   LF14A
             DEC   $00,X   ; decreasing: position - 1
             BRA   LF14C
LF14A:       INC   $00,X   ; increasing: position + 1
LF14C:       LDX   CB_PTR   ; X = block
             BITB  ABORTREQ   ; abort requested for this channel?
             BEQ   LF15C
             COMB     ; yes: drop the request
             ANDB  ABORTREQ
             STAB  ABORTREQ
             CLR   $0A,X   ; and the remaining count (next call stops)
             CLR   $0B,X
LF15C:       LDAA  $08,X   ; restart the prescaler
             STAA  $07,X
             CLC      ; C=0: still running
             RTS   
CH_LIMIT:    BITB  #$70   ; limit hit: on the decreasing side?
             BEQ   CH_STOP
             LDX   $04,X   ; yes: the motor is at its zero end, position = 0
             CLR   $00,X
CH_STOP:     CLRA     ; pattern 0 = coils released (steering: inverted to $F)
             BSR   PHASEOUT   ; PHASEOUT
             PULA     ; A = channel bit
             COMA     ; A = mask that clears it
             SEC      ; C=1: finished
             RTS   

;---------------------------------------------------------------
; PHASEOUT - write a phase pattern to the current channel's port nibble
;
; Steering ($C260 high nibble) is driven inverted: its pattern is
; complemented first, so "0 = released" becomes $F. For MOTA the other
; nibble is merged from MOTA_SH under SEI so the steering and pivot/rotate
; channels never overwrite each other. For MOTB the other nibble is
; written as 0 (only one arm channel runs at a time). Ends with CLI.
;
; In:        A = pattern (both nibbles), CB_PTR = control block
; Memory:    port, MOTA_SH; leaves I=0
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 39,536 calls, 3/3 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 59-82 E cycles over 39,536 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: CHSTEP
;---------------------------------------------------------------
PHASEOUT:    LDX   CB_PTR
             LDAB  $00,X   ; B = nibble mask
             LDX   $02,X   ; X = port
             CPX   #$C260
             BNE   LF182   ; steering (MOTA, high nibble)?
             CMPB  #$F0
             BNE   LF182
             COMA     ; yes: invert the pattern
LF182:       LDX   CB_PTR
             ANDA  $00,X   ; keep this motor's nibble
             LDX   $02,X
             CPX   #$C260
             BNE   LF197
             COMB     ; B = the other nibble's mask
             SEI      ; masked: read-modify-write of the shadow
             ANDB  MOTA_SH   ; other channel's nibble
             ABA   
             STAA  MOTA_SH   ; update the shadow
LF197:       STAA  $00,X   ; output
             CLI      ; interrupts back on (also when called with I=0)
             RTS   

;---------------------------------------------------------------
; PHASETAB - stepper phase patterns (same pattern in both nibbles)
;
; Index 0-3 (position increasing): $66 $55 $99 $AA -> nibbles 6 5 9 A.
; Index 4-7 (decreasing):          $66 $AA $99 $55 -> nibbles 6 A 9 5.
; Two-coil full stepping (coil A on bits 3/2, B on bits 1/0). Steering gets
; the complement (9 A 6 5 / 9 5 6 A). Every move starts at index 0, so
; moves of whole units (multiples of 4 phases) chain seamlessly; after a
; direction reversal the first pattern is one phase off (emulator: head
; ended 1 phase step = 1/32 unit off, not cumulative).
;---------------------------------------------------------------
PHASETAB:    FCB   $66,$55,$99,$AA,$66,$AA,$99,$55

;---------------------------------------------------------------
; SPEECH - phoneme sequencer, one phoneme per SC-01 request
;
; Speech lists are phoneme bytes (bits 7-6 inflection, 5-0 phoneme) ending
; in $FF. $BF hi lo calls another list (SPEAK's "jump when speaking" is a
; call): a new slot is pushed on a call stack of 2-byte slots holding
; list pointers, from SPK_BASE ($0F13) down to $0F05 - the outer list plus 7
; nested calls; a call that would use SPKLIM ($0F03) ends the whole
; utterance instead (emulator: a self-calling list spoke its first phoneme
; 8 times, then stopped; M-call-A-call-O nesting returned correctly). $FF in a called list pops and skips the 3-byte $BF in the
; caller. $FF and $BF can never be spoken (they are STOP with inflection).
; Handshake: MOTA bit 0 = 1 when the SC-01 wants a phoneme; the phoneme
; goes to SENSE $C240 and CTRL bit 5 is pulsed high and back to latch it.
;
; In:        SPKSP, SPK_BASE, SPKLIM, MOTA bit 0
; Out:       C=0 still speaking; C=1 finished (speech power turned off)
; Memory:    SPKSP, the slots, SENSE, CTRL, POWER, POWER_SH; may leave I=1
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: B, X
; Preserves: none   [static + measured: 82,659 calls, 4/5 branches]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 17-294 E cycles over 82,659 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into SPK_PUSH; falls into SPK_ADV
; Calls:     SPK_ADV
; Called from: TICK, LOGIC_LOW, LGLO_WAKE
;---------------------------------------------------------------
SPEECH:      LDAA  MOTA   ; SC-01 asking for a phoneme (A/R high)?
             BITA  #$01
             BEQ   LF21A   ; no: nothing to do, C=0
             LDX   SPKSP   ; X = current slot
SPK_FETCH:   LDX   $00,X   ; X = list pointer from the slot
             LDAA  $00,X   ; next byte
             CMPA  #$FF   ; end of list?
             BNE   SPK_NOTFF
             LDX   SPKSP   ; at the bottom slot?
             CPX   SPK_BASE
             BNE   SPK_RET
SPK_END:     LDX   #$0000   ; done: mark not speaking
             STX   SPKSP
             SEI      ; masked: speech power off (POWER bit 3)
             LDAA  POWER_SH
             ANDA  #$F7
             STAA  POWER_SH
             STAA  POWER
             CLI   
             SEC      ; C=1: utterance finished
             RTS   
SPK_RET:     INX      ; pop to the caller's slot
             INX   
             STX   SPKSP
             BSR   SPK_ADV   ; SPK_ADV x3: skip the caller's $BF hi lo
             BSR   SPK_ADV
             BSR   SPK_ADV
             BRA   SPK_FETCH   ; fetch the caller's next byte now
SPK_NOTFF:   CMPA  #$BF   ; $BF = call another list?
             BNE   SPK_OUT
             LDAA  $02,X   ; A = low, B = high byte of the called list
             LDAB  $01,X
             LDX   SPKSP   ; push a slot
             DEX   
             DEX   
             CPX   SPKLIM   ; stack full: end the whole utterance
             BEQ   SPK_END

;---------------------------------------------------------------
; SPK_PUSH - start an utterance (entry inside SPEECH's $BF handler)
;
; With X = SPK_BASE contents this puts the list address in the bottom slot
; and immediately outputs its first phoneme without waiting for the
; SC-01's request; later phonemes are fed by SPEECH on request.
;
; In:        X = slot ($0F13 from SPK_BASE), A = list low, B = list high
; Out:       C=0 speaking (caller sets BUSY bit 3); C=1 list was empty
; Memory:    SPKSP, the slot; see SPEECH
;
; Changes:   A, B, X, flags H I N Z V C ; on some paths: B, X
; Preserves: none   [static + measured: 73 calls]
;            measured: B written but equal at exit on every call
; Stack:     2 bytes max, including callees (observed 1)
; Cycles:    observed 114-191 E cycles over 73 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into SPK_ADV
; Calls:     SPK_ADV
; Called from: SPK_IDX_W, SPK_IDX, SPK_EXT_W, SPK_EXT, SPEAK_AB, LOGIC_LOW, LGLO_WAKE
;---------------------------------------------------------------
SPK_PUSH:    STX   SPKSP   ; (entry SPK_PUSH) slot <- list pointer
             STAA  $01,X
             STAB  $00,X
             BRA   SPK_FETCH   ; fetch its first byte
SPK_OUT:     STAA  SENSE   ; phoneme to the SC-01 data latch
             SEI      ; masked (no CLI follows: I stays set until the caller's RTI/CLI)
             LDAB  CTRL_SH
             PSHB  
             ORAB  #$20   ; CTRL bit 5 high: strobe
             STAB  CTRL
             PULB  
             STAB  CTRL   ; and low again

;---------------------------------------------------------------
; SPK_ADV - advance the current slot's list pointer by one byte
;
; In:        SPKSP
; Out:       C=0; X = SPKSP slot address                       (contract)
; Memory:    the slot word
;
; Changes:   A, B, X, flags H N Z V C
; Preserves: none   [static + measured: 6 calls]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 38 E cycles on every call over 6 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: SPEECH, SPK_PUSH
;---------------------------------------------------------------
SPK_ADV:     LDX   SPKSP
             LDAA  $01,X   ; step the slot's pointer by one (16-bit)
             LDAB  $00,X
             ADDA  #$01
             ADCB  #$00
             STAA  $01,X
             STAB  $00,X
LF21A:       CLC      ; C=0: still speaking
             RTS   

;---------------------------------------------------------------
; ENCODER - drive wheel encoder pulse
;
; Counts DRVDIST down; on a pulse that arrives with DRVDIST already 0 and
; the drive busy, it ends the move: BUSY bit 0 cleared at once (the robot
; program continues), stop requested (ABORTREQ bit 0) and DRVTARGET = $3F so
; DRVRAMP ramps the motor down. Every pulse, busy or not, bumps DRVCOUNT and
; ODOMETER. Emulator: a move of $040 counts stopped at DRVCOUNT = 64 and the
; ramp-down coasted 5 more counts (DRVCOUNT = 69 at rest).
;
; In:        DRVDIST, BUSY
; Out:       A preserved                                       (contract)
; Memory:    DRVDIST, BUSY, ABORTREQ, DRVTARGET, DRVCOUNT, ODOMETER
;
; Changes:   B, X, flags N Z V ; on some paths: B
; Preserves: A   [static + measured: 51 calls, 1/2 branches]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 63-87 E cycles over 51 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     ODO_BUMP
; Called from: IRQ
;---------------------------------------------------------------
ENCODER:     LDX   DRVDIST   ; distance left
             BNE   ENC_COUNT   ; still counting
             LDAB  BUSY   ; reached: is a drive move active?
             BITB  #$01
             BEQ   LF238
             LDAB  #$01   ; request the stop (DRVRAMP finishes it)
             ORAB  ABORTREQ
             STAB  ABORTREQ
             LDAB  BUSY   ; distance done: drive no longer busy
             ANDB  #$FE
             STAB  BUSY
             LDAB  #$3F   ; target = off
             STAB  DRVTARGET
LF238:       BSR   ODO_BUMP   ; ODO_BUMP
             RTS   
ENC_COUNT:   DEX      ; one count less
             STX   DRVDIST
             BSR   ODO_BUMP   ; ODO_BUMP
             RTS   

;---------------------------------------------------------------
; ODO_BUMP - add one to DRVCOUNT and ODOMETER
;
; Memory:    DRVCOUNT, ODOMETER
;
; Changes:   X, flags N Z V
; Preserves: A, B   [static + measured: 51 calls]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 31 E cycles on every call over 51 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: ENCODER
;---------------------------------------------------------------
ODO_BUMP:    LDX   DRVCOUNT
             INX   
             STX   DRVCOUNT
             LDX   ODOMETER
             INX   
             STX   ODOMETER
             RTS   

;---------------------------------------------------------------
; SONAR - sonar echo (or counter overflow): latch the range
;
; Range count = 32 kHz clock periods from ping to echo (theory chapter).
;
; Out:       A preserved                                       (contract)
; Memory:    SONARRANGE, SONARHITS
;
; Changes:   B, flags N Z V
; Preserves: A, X   [static + measured: 131 calls]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 19 E cycles on every call over 131 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: IRQ
;---------------------------------------------------------------
SONAR:       LDAB  SONARCNT   ; time-of-flight count
             STAB  SONARRANGE
             INC   >SONARHITS   ; one more echo
             RTS   

;---------------------------------------------------------------
; LOGIC_LOW - logic battery low warning
;
; Unless HK_LOGLO returns C=0, stops the drive, masks every interrupt,
; shows "LG Lo." and says "low voltage" (polling SPEECH itself, since no
; ticks run). Then waits about 10 s ($FFFF key polls) for a key. With the
; sleep switch at Normal it repeats the warning; at Sleep it sleeps 4
; periods (40 s) with BATSLEEP = $FF and SP saved in BATSP; the wake-up
; RESET resumes at LGLO_WAKE on the same stack, so the warning repeats every
; ~50 s (confirmed in the emulator). A key press disables this interrupt
; (IRQMASK = $F7), restores drive and power and returns.
; Problems found in the emulator: (1) after a sleep, RESET's HWINIT has
; cleared BUSY, so the restored drive byte keeps the motor running with no
; ramp or distance control (drive stayed $7F indefinitely); (2) BATSLEEP is
; never cleared except by RAMINIT, so a later SLEEP (87) by a robot program
; wakes into this warning instead of resuming the program.
;
; In:        A = IRQ flags (kept)
; Out:       A preserved                                       (contract)
; Memory:    IRQMASK, IRQFLAGS, BUSY bit 3, BATSLEEP, SLEEPCNT, BATSP,
;            DRIVE, POWER, display, speech
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call, 3/5 branches]
;            measured: A written but equal at exit on every call
; Stack:     10 bytes max, including callees (observed 10)
; Cycles:    observed 2,786,054 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; WAI
; Calls:     SPEECH, SPK_PUSH, PWR_SAVE, PWR_DISP, PWR_REST, KEYUP, KEYPOLL, OUTSTR, RAM hook $0021
; Called from: IRQ
;---------------------------------------------------------------
LOGIC_LOW:   JSR   >HK_LOGLO   ; hook HK_LOGLO: C=1 (default) = let the ROM handle it
             BCS   LF25C   ; C=0: user handled it
             RTS   
LF25C:       PSHA     ; keep the IRQ flags
             JSR   PWR_SAVE   ; PWR_SAVE: masked, drive off, A = power, B = drive byte
             PSHA     ; saved power and drive under the flags
             PSHB  
LGLO_LOOP:   JSR   PWR_DISP   ; PWR_DISP: power = display only, settle, clear display
             JSR   OUTSTR   ; OUTSTR: show the inline string
             FCB   $0E,$5E,$00,$0E,$9D   ; display "LG Lo."
             CLR   IRQFLAGS   ; all interrupts off (no ticks while warning)
             LDAA  #$18   ; power: display + speech
             STAA  POWER
             LDX   #$2710   ; ~90 ms for the speech board to power up
LF278:       DEX   
             BNE   LF278
             LDAA  #LO(LOWVOLT_PH)
             LDAB  #HI(LOWVOLT_PH)
             LDX   SPK_BASE   ; X = bottom speech slot
             JSR   SPK_PUSH   ; SPK_PUSH: start "low voltage"
LF285:       JSR   SPEECH   ; SPEECH: poll it directly until done
             BCC   LF285
             SEI      ; (SPEECH turned speech power off)
             LDAA  BUSY   ; speech no longer busy
             ANDA  #$F7
             STAA  BUSY
             LDX   #$FFFF   ; about 10 s of key polling
LF294:       JSR   KEYPOLL   ; key pressed (debounced)?
             BCS   LGLO_ACK   ; yes: acknowledge
             DEX   
             BNE   LF294
             LDAA  MOTB   ; sleep switch at Normal?
             BITA  #$02
             BNE   LGLO_LOOP   ; yes: warn again
             LDAA  #$FF   ; mark "battery sleep"
             STAA  BATSLEEP
             LDX   #$0004   ; sleep 4 periods of 10 s
             STX   SLEEPCNT
             STS   BATSP   ; the stack survives in battery-backed RAM
             LDAA  #$40   ; power = sleep only: +5 V goes off
             STAA  POWER
             WAI      ; park; the sleep timer later RESETs the CPU

;---------------------------------------------------------------
; LGLO_WAKE - resume the battery warning after a battery sleep
;
; Reached by JMP from RESET ($F39C) when the last sleep period ends and
; BATSLEEP is set: reloads the stack saved before sleeping and repeats
; the warning.
;
; In:        BATSP
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     7 bytes max, including callees
; Exit:      RTS; WAI; pulls caller stack; resets SP
; Calls:     SPEECH, SPK_PUSH, PWR_DISP, PWR_REST, KEYUP, KEYPOLL, OUTSTR
; Called from: RESET
;---------------------------------------------------------------
LGLO_WAKE:   LDS   BATSP
             BRA   LGLO_LOOP
LGLO_ACK:    JSR   KEYUP   ; wait for the key to be released
             LDAA  #$F7   ; disable the logic-battery interrupt from now on
             STAA  IRQMASK
             STAA  IRQFLAGS
             PULB     ; B = drive byte, A = power
             PULA  
             JSR   PWR_REST   ; PWR_REST: restore drive and power
             PULA     ; IRQ flags back for the dispatcher
             RTS   

;---------------------------------------------------------------
; LOWVOLT_PH - phonemes for "low voltage" (L O W STOP V O L T I T CH PA1)
;---------------------------------------------------------------
LOWVOLT_PH:  FCB   $18,$26,$2D,$3F,$0F,$26,$18,$2A,$27,$2A,$10,$3E,$FF   ; speech: L O W STOP V O L T I T CH PA1 [end]

;---------------------------------------------------------------
; MOTOR_LOW - motor battery low warning
;
; Unless HK_MOTLO returns C=0, stops the drive, shows "dr Lo." and waits
; with interrupts masked (motors frozen) until a key is pressed, then
; disables this interrupt (IRQMASK = $FB) and restores drive and power;
; BUSY is untouched, so a drive move continues afterwards. No speech, no
; sleep.
;
; In:        A = IRQ flags (kept)
; Out:       A preserved                                       (contract)
; Memory:    IRQMASK, IRQFLAGS, DRIVE, POWER, display
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call, 1/2 branches]
;            measured: A written but equal at exit on every call
; Stack:     10 bytes max, including callees (observed 10)
; Cycles:    observed 2,785,858 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     PWR_SAVE, PWR_DISP, PWR_REST, KEYUP, KEYPOLL, OUTSTR, RAM hook $0024
; Called from: IRQ
;---------------------------------------------------------------
MOTOR_LOW:   JSR   >HK_MOTLO   ; hook HK_MOTLO: C=1 (default) = let the ROM handle it
             BCS   LF2DF   ; C=0: user handled it
             RTS   
LF2DF:       PSHA  
             JSR   PWR_SAVE   ; PWR_SAVE: masked, drive off, A = power, B = drive byte
             PSHA  
             PSHB  
             JSR   PWR_DISP   ; PWR_DISP: display only, clear display
             JSR   OUTSTR   ; OUTSTR: show the inline string
             FCB   $3D,$05,$00,$0E,$9D   ; display "dr Lo."
LF2F0:       JSR   KEYPOLL   ; wait for a key (debounced)
             BCC   LF2F0
             JSR   KEYUP   ; wait for its release
             LDAA  #$FB   ; disable the motor-battery interrupt from now on
             STAA  IRQMASK
             STAA  IRQFLAGS
             PULB  
             PULA  
             JSR   PWR_REST   ; PWR_REST: restore drive and power
             PULA  
             RTS   

;---------------------------------------------------------------
; PWR_SAVE - mask interrupts, stop the drive, return what to restore
;
; Out:       A = POWER_SH, B = DRVNOW; I=1
; Memory:    DRIVE port (0 = off)
;
; Changes:   A, B, flags I N Z V C
; Preserves: X   [static + measured: 2 calls]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 39 E cycles on every call over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: LOGIC_LOW, MOTOR_LOW
;---------------------------------------------------------------
PWR_SAVE:    SEI      ; masked (left masked)
             NOP   
             LDAA  POWER_SH
             LDAB  DRVNOW
             PSHA  
             PSHB  
             CLR   DRIVE   ; drive off; DRVNOW still holds the old value
             PULB  
             PULA  
             RTS   

;---------------------------------------------------------------
; PWR_DISP - power only the display, let it settle, clear it
;
; Memory:    POWER (DRVNOW/POWER_SH untouched), display
;
; Changes:   A, B, X, flags N Z V C
; Preserves: none   [static + measured: 2 calls, 1/1 branches]
; Stack:     5 bytes max, including callees (observed 5)
; Cycles:    observed 100,467 E cycles on every call over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     CLRDIS
; Called from: LOGIC_LOW, LGLO_WAKE, MOTOR_LOW
;---------------------------------------------------------------
PWR_DISP:    LDAA  #$10   ; POWER = display only
             STAA  POWER
             LDX   #$3000   ; ~110 ms
LF31F:       DEX   
             BNE   LF31F
             JSR   CLRDIS   ; CLRDIS: blank the display
             RTS   

;---------------------------------------------------------------
; PWR_REST - clear the display and restore drive and power
;
; In:        A = power byte, B = drive byte (from PWR_SAVE)
; Memory:    DRIVE, DRVNOW, POWER, POWER_SH, display
;
; Changes:   flags N Z V C
; Preserves: A, B, X   [static + measured: 2 calls]
; Stack:     7 bytes max, including callees (observed 7)
; Cycles:    observed 2,189 E cycles on every call over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     CLRDIS
; Called from: LOGIC_LOW, LGLO_WAKE, MOTOR_LOW
;---------------------------------------------------------------
PWR_REST:    PSHA  
             PSHB  
             JSR   CLRDIS   ; CLRDIS: blank the display
             PULB  
             PULA  
             STAB  DRIVE
             STAB  DRVNOW
             STAA  POWER_SH
             STAA  POWER
             RTS   

;---------------------------------------------------------------
; NMI - ABORT button
;
; Resets the hardware, shows "Abor7." (the last digit is a 7-like t) for
; about 1.8 s, then "Pc." and the address from $0EE2, and hangs until
; RESET. In Robot Language ($0EE1 <> 0) $0EE2 already holds the address
; of the robot instruction being run (set at $E000), which is shown
; correctly. In machine language the code means to fetch the stacked PC
; into A/B but then stores X (the stack frame address) instead: bug.
; Emulator: aborting a native loop at $0300 showed "Pc.0F98", aborting a
; robot program at $0400 showed "Pc.0400".
;
; In:        ROBOTMODE $0EE1 (nonzero = Robot Language), CURPC $0EE2
;
; Changes:   flags N Z V C
; Preserves: A, B, X   [static]
; Stack:     9 bytes max, including callees
; Exit:      resets SP
; Calls:     HWINIT, CLRDIS, OUTBYT, OUTSTR
;---------------------------------------------------------------
NMI:         TST   ROBOTMODE   ; running Robot Language?
             BNE   LF347
             TSX      ; X = interrupt frame (CC B A XH XL PCH PCL)
             LDAA  $06,X   ; A = PC low, B = PC high ... (unused)
             LDAB  $05,X
             STX   CURPC   ; ... bug: saves the frame address, not A/B
LF347:       LDS   #$0FD7
             JSR   HWINIT   ; HWINIT: drive off, phases off, busy bits cleared
             LDAA  #$10   ; power = display only
             STAA  POWER
             JSR   CLRDIS   ; CLRDIS: blank the display
             JSR   OUTSTR   ; OUTSTR: show the inline string
             FCB   $77,$1F,$1D,$05,$F0   ; display "Abor7."
             LDAB  #$03   ; 3 x 65535 x 8 cycles = about 1.8 s
LF35F:       LDX   #$FFFF
LF362:       DEX   
             BNE   LF362
             DECB  
             BNE   LF35F
             JSR   CLRDIS   ; CLRDIS: blank the display
             JSR   OUTSTR   ; OUTSTR: show the inline string
             FCB   $67,$8D   ; display "Pc."
             LDAA  CURPC   ; OUTBYT: high byte of the address
             JSR   OUTBYT
             LDAA  $0EE3   ; OUTBYT: low byte
             JSR   OUTBYT
NMI_HANG:    BRA   NMI_HANG   ; wait here for RESET

;---------------------------------------------------------------
; RESET - power-on, RESET key, and wake-up from sleep
;
; After HWINIT the sleep switch decides. Normal: cold start through
; RAMINIT into the Executive. Sleep: this reset is the sleep timer's
; 10-second wake-up. SLEEPCNT is decremented; if periods remain the robot
; sleeps again at once (power = $40, WAI; the power-down ends the CPU and
; the next timer reset comes back here). On the last period it either
; resumes the battery warning (BATSLEEP set) or resumes the robot program
; at $F5B5 with $F423 (Executive) pushed as return address; the program's
; PC was already moved past the 87 instruction by $E450. RAM, the hooks
; and the vectors survive a wake-up (RAMINIT does not run).
; Note: RESET with the switch at Sleep and SLEEPCNT = 0 decrements it to
; $FFFF, so the robot naps in 10 s periods until the switch is moved to
; Normal (emulator: power = $40 with SLEEPCNT = $FFFF).
;
; In:        MOTB bit 1 (sleep switch, 1 = Normal), SLEEPCNT, BATSLEEP
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     16 bytes max, including callees
; Exit:      RTS; WAI; falls into EXEC; falls into KEYDISP; falls into LF488; resets SP; tail-JMP to LGLO_WAKE; tail-JMP to RUN_STEP
; Calls:     LGLO_WAKE, HWINIT, SAY_READY, IDLE_ANIM, RUN_STEP, KEYUP, KEYPOLL
; Called from: UT_SAVE, UT_LOAD, UT_SETTIME, UT_SETDATE
;---------------------------------------------------------------
RESET:       LDS   #$0FDF   ; temporary stack
             BSR   HWINIT   ; HWINIT: ports, shadows and busy bits to rest
             LDAA  MOTB   ; sleep switch at Normal?
             BITA  #$02
             BNE   RAMINIT   ; yes: cold start
             LDX   SLEEPCNT   ; one sleep period over
             DEX   
             STX   SLEEPCNT
             BEQ   WAKE_DONE   ; all done: wake up
             LDAA  #$40   ; POWER = sleep only: +5 V goes off for another 10 s
             STAA  POWER
             WAI      ; park until the power-down
WAKE_DONE:   TST   >BATSLEEP   ; woke from a battery-warning sleep?
             BEQ   LF39F
             JMP   LGLO_WAKE   ; yes: back to the warning loop
LF39F:       LDS   #$0FD7   ; the interpreter's stack
             LDAA  #LO(EXEC)   ; push $F423 (Executive) as the return address
             LDAB  #HI(EXEC)
             PSHA  
             PSHB  
             JMP   RUN_STEP   ; continue the sleeping robot program

;---------------------------------------------------------------
; HWINIT - put all output ports and their shadows in the rest state
;
; DRIVE/DRVNOW/DRVTARGET = $3F (off); MOTA = $F0 (steering released, pivot
; and rotate off) and MOTA_SH; CTRL = $0F (no arm motor selected, speech
; strobe low, clock register $F) and CTRL_SH; CLOCK port = $AF (the same
; value the manual's clock example writes first); BUSY = ABORTREQ = 0;
; IRQFLAGS written $00 (reset all flip-flops) then $FF (enable all), and
; IRQMASK = $FF. The I flag is not changed.
;
; Out:       B = $FF                                           (contract)
; Memory:    DRIVE, MOTA, CTRL, CLOCK, IRQFLAGS and their shadows,
;            DRVTARGET, BUSY, ABORTREQ, IRQMASK
;
; Changes:   A, B, flags N Z V C
; Preserves: X   [static + measured: 83 calls, 1/1 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 80 E cycles on every call over 83 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: NMI, RESET
;---------------------------------------------------------------
HWINIT:      LDAB  #$3F   ; drive off
             STAB  DRIVE
             STAB  DRVNOW
             STAB  DRVTARGET
             CLRB     ; B = 0 for the clears below
             LDAA  #$F0   ; steering lines high (released), low nibble off
             STAA  MOTA
             STAA  MOTA_SH
             COMA     ; $0F: select bits 7/6 = 0, strobe low, clock register $F
             STAA  CTRL
             STAA  CTRL_SH
             LDAA  #$AF   ; MSM5832 control byte
             STAA  CLOCK
             STAB  BUSY   ; nothing busy
             STAB  ABORTREQ   ; no stop requests
             STAB  IRQFLAGS   ; reset every interrupt flip-flop
             LDAB  #$FF   ; then enable all eight sources
             STAB  IRQFLAGS
             STAB  IRQMASK   ; and remember the mask
             RTS   

;---------------------------------------------------------------
; RAMINIT - cold-start RAM setup, falls into the Executive at $F423
;
; Sets (and nothing else; positions $0000-$0006, DRVCOUNT, ODOMETER and the
; user keys $0030-$0038 are left as they are):
;   TICKS ($0EFC) = 0            tick counter restarts
;   BATSLEEP ($000F) = 0         not in a battery sleep
;   SPK_BASE ($0F15) = $0F13      bottom slot of the speech call stack
;   SPKLIM ($0F17) = $0F03       overflow mark of that stack
;   $0FF4 = $0F97                user register frame pointer / initial user SP
;   $0FE0-$0FEB = $FF            four 3-byte breakpoint entries (saved byte,
;                                address) cleared, as $F5C2 reads them
;   $0FF6 = $7E                  JMP opcode: the SWI vector points at $0FF6,
;                                the monitor fills in the target at $0FF7
;   $0012 = RTS                  interpreter per-instruction hook ($E000)
;   $0015 = SEC,RTS              interpreter unknown-opcode hook (C=1: not handled)
;   HK_IRQ $0018 = RTS
;   HK_TICK $001B = RTS
;   HK_DRIVE $001E = RTS
;   HK_LOGLO $0021 = SEC,RTS     ROM handles the logic-battery warning
;   HK_MOTLO $0024 = SEC,RTS     ROM handles the motor-battery warning
;   VEC_MOTION $0027, VEC_TRIG $002A, VEC_EXP $002D = RTS
; Only the first byte(s) are written, so the hooks are three-byte slots
; meant for a JMP. They are reset only by this cold start (RESET with the
; switch at Normal), not on every return to the Executive as the manual
; says.
;---------------------------------------------------------------
RAMINIT:     CLR   TICKS
             CLR   >BATSLEEP
             LDX   #$0F13   ; speech stack bottom slot
             STX   SPK_BASE
             LDX   #$0F03   ; speech stack overflow mark
             STX   SPKLIM
             LDX   #$0F97   ; initial user stack / register frame
             STX   USERFRAME
             LDAA  #$FF   ; fill byte
             LDAB  #$0C   ; 12 bytes: the four breakpoint entries
             LDX   #$0FE0
RAMI_FILL:   STAA  $00,X   ; clear one byte
             INX   
             DECB  
             BNE   RAMI_FILL
             LDAA  #$7E   ; JMP opcode in front of the SWI target
             STAA  SWIJMP
             LDAA  #$39   ; A = RTS, B = SEC
             LDAB  #$0D
             STAB  RI_BADOP   ; $0015: SEC
             STAA  $16   ; $0016: RTS
             STAA  HK_TICK   ; HK_TICK: RTS
             STAA  RI_HOOK   ; $0012: RTS
             STAB  HK_LOGLO   ; HK_LOGLO: SEC
             STAA  $22   ; then RTS
             STAB  HK_MOTLO   ; HK_MOTLO: SEC
             STAA  $25   ; then RTS
             STAA  HK_IRQ   ; HK_IRQ: RTS
             STAA  VEC_MOTION   ; VEC_MOTION: RTS
             STAA  VEC_TRIG   ; VEC_TRIG: RTS
             STAA  HK_DRIVE   ; HK_DRIVE: RTS
             STAA  VEC_EXP   ; VEC_EXP: RTS; falls into the Executive at $F423

;---------------------------------------------------------------
; EXEC - the executive ("ready") loop
;
; Every return to the executive lands here. Resets the stack, turns on
; only the display, waits about 65 ms for the supplies, shows
; "HEro 1.0" and says "ready", then waits for a key. While no key comes,
; IDLE_ANIM walks a single lit segment along the display after about
; a minute. A key runs entry key+1 of KEYCMDS by RTS dispatch, with
; EXEC's own address left on the stack so a command that returns comes
; back here.
;
; In:        none
; Out:       never returns
; Memory:    writes POWER, POWER_SH, IDLE_CNT, IDLE_RATE, ANIM_ADR, ANIM_DIR
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     9 bytes max, including callees
; Exit:      RTS; falls into KEYDISP; falls into LF488; resets SP
; Calls:     SAY_READY, IDLE_ANIM, KEYUP, KEYPOLL
; Called from: R_EXEC
;---------------------------------------------------------------
EXEC:        LDS   #$0FD7
             LDAA  #$10
             STAA  POWER
             STAA  POWER_SH
             LDX   #$3FFF   ; settling delay: $3FFF passes of DEX/BNE, about 65 ms [hand count]
LF431:       DEX   
             BNE   LF431
             JSR   SAY_READY   ; SAY_READY: "HEro 1.0" and "ready"
             LDX   #$FFFF   ; idle time before the animation starts
             STX   IDLE_CNT
             LDX   #$0001
             STX   IDLE_RATE
             LDX   #$C16F
             STX   ANIM_ADR   ; animation starts at the leftmost digit
             CLR   ANIM_DIR
             LDAA  #LO(EXEC)   ; push EXEC as the return address for every command
             LDAB  #HI(EXEC)
             PSHA  
             PSHB  
EXEC_IDLE:   JSR   KEYPOLL   ; KEYPOLL: C set when a key is down
             BCS   EXEC_KEY
             LDX   IDLE_CNT
             BEQ   LF462
             DEX   
             STX   IDLE_CNT
             BRA   EXEC_IDLE
LF462:       LDX   IDLE_RATE
             DEX   
             STX   IDLE_RATE
             BNE   EXEC_IDLE
             BSR   IDLE_ANIM
             BRA   EXEC_IDLE
EXEC_KEY:    PSHA  
             JSR   KEYUP   ; KEYUP: wait for the key to be released (debounced)
             PULA  
             LDX   #KEYCMDS-2   ; command table minus 2
* KEYDISP - X steps two bytes per key from the table base; the word found there is pushed
* and the RTS below "returns" into the command. A = key on entry; X and A are restored first.

;---------------------------------------------------------------
; KEYDISP - RTS dispatch: push the word at X + 2*(A+1) and return into it
;
; In:        A = key 0-15, X = table base minus 2, XSAVE = X to restore
; Out:       enters the routine with A = SAVESP, X = XSAVE
;
; Changes:   A, X, flags N Z V
; Preserves: B   [static + measured: 25 calls, 1/1 branches]
; Stack:     2 bytes max, including callees (observed 2)
; Cycles:    observed 46-256 E cycles over 25 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into LF488
; Called from: UTIL, MON_ML, MON_RL
;---------------------------------------------------------------
KEYDISP:     INX   
             INX   
             DECA  
             BPL   KEYDISP
             LDAA  $01,X
             PSHA  
             LDAA  $00,X
             PSHA  
             LDX   XSAVE
             LDAA  SAVESP

;---------------------------------------------------------------
; (RTS) - KEYCMDS entry for monitor key 0: does nothing, back to MON_LOOP
;
; Changes:   nothing
; Preserves: A, B, X   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS
;---------------------------------------------------------------
LF488:       RTS      ; RTS dispatch into the command; also the monitor's "key 0" no-op

;---------------------------------------------------------------
; SAY_READY - show "HEro 1.0" and say "ready"
;
; In:        none
; Out:       display = H E r o 1. 0
; Memory:    writes WAITMASK
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 65 calls]
; Stack:     7 bytes max, including callees (observed 6)
; Cycles:    observed 82,373 E cycles on every call over 65 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     SPEAK_AB, OUTSTR0, OUTCH
; Called from: RESET, EXEC
;---------------------------------------------------------------
SAY_READY:   JSR   OUTSTR0
             FCB   $37,$4F,$05,$1D,$B0   ; inline string: "HEro1." (the 1 carries the decimal point)
             LDAA  #$7E   ; then a "0": the ROM version, 1.0
             JSR   OUTCH   ; OUTCH
             LDAA  #LO(PH_READY)   ; phoneme string PH_READY
             LDAB  #HI(PH_READY)
             CLR   WAITMASK   ; do not wait for the speech to finish
             JSR   SPEAK_AB   ; SPEAK_AB: start speaking
             RTS   
PH_READY:    FCB   $2B,$3B,$1E,$2C,$03,$FF   ; R EH D E PA0: "ready"

;---------------------------------------------------------------
; IDLE_ANIM - move the idle animation one step
;
; Clears the lit segment and lights the next one: along the bottom of
; the digits to the right, then back along the top, and so on.
;
; Memory:    writes ANIM_ADR, ANIM_DIR, IDLE_RATE, DIGADD; display latches
;
; Changes:   A, X, flags H N Z V C
; Preserves: B   [static + measured: 141 calls, 3/3 branches]
; Stack:     3 bytes max, including callees (observed 3)
; Cycles:    observed 738-750 E cycles over 141 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Calls:     OUTCH
; Called from: RESET, EXEC
;---------------------------------------------------------------
IDLE_ANIM:   LDX   #$0200
             STX   IDLE_RATE
             LDX   ANIM_ADR
             STX   DIGADD
             CLRA  
             JSR   OUTCH
             TST   ANIM_DIR
             BNE   LF4D3
             LDX   DIGADD
             STX   ANIM_ADR
             LDAA  #$01
             JSR   OUTCH
             LDX   DIGADD
             CPX   #$C10F
             BNE   LF4D2
             COM   ANIM_DIR
LF4D2:       RTS   
LF4D3:       LDAA  $0FFA
             ADDA  #$10
             STAA  $0FFA
             LDX   ANIM_ADR
             STX   DIGADD
             LDAA  #$01
             JSR   OUTCH
             CPX   #$C16F
             BNE   LF4EE
             CLR   ANIM_DIR
LF4EE:       RTS   

;---------------------------------------------------------------
; MON_ML - executive key 1: the monitor, Machine Language
;
; Shows "1." and clears ROBOTMODE, then falls into MON_LOOP.
;
; Changes:   A, B, X, flags H N Z V C
; Preserves: none   [static]
; Stack:     11 bytes max, including callees
; Exit:      tail-JMP to KEYDISP
; Calls:     KEYDISP, CLRDIS, INCH, OUTSTR
;---------------------------------------------------------------
MON_ML:      JSR   CLRDIS
             JSR   OUTSTR   ; inline string: "1."
             FCB   $B0   ; display "1."
             CLR   ROBOTMODE

;---------------------------------------------------------------
; MON_LOOP - monitor command loop
;
; Waits for a key and dispatches it through the second half of KEYCMDS:
; 1 A, 2 B, 3 PC, 4 X, 5 CC, 6 SP, 7 resume, 8 single step,
; 9 breakpoint, A autoload, B back, C change, D do, E examine,
; F forward. Its own address is pushed first, so every command returns
; to the loop. While showing a memory byte (SAVESP non-zero), F and B
; step through memory instead of being treated as commands.
;
; Out:       never returns
;---------------------------------------------------------------
MON_LOOP:    STAA  SAVESP
             STAB  $0FF1
             LDAA  #LO(MON_LOOP)
             LDAB  #HI(MON_LOOP)
             PSHA  
             PSHB  
             LDAB  $0FF1
LF508:       JSR   INCH   ; INCH
             TST   SAVESP
             BEQ   LF518
             CMPA  #$0F
             BEQ   LF508
             CMPA  #$0B
             BEQ   LF508
LF518:       STX   XSAVE
             LDX   #KEYCMDS+30   ; second half of the command table
             JMP   KEYDISP

;---------------------------------------------------------------
; MON_RL - executive key A: the monitor, Robot Language
;
; Shows "A.", sets ROBOTMODE and falls into MON_LOOP.
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     11 bytes max, including callees
; Exit:      tail-JMP to KEYDISP
; Calls:     KEYDISP, CLRDIS, INCH, OUTSTR
;---------------------------------------------------------------
MON_RL:      JSR   CLRDIS
             JSR   OUTSTR   ; inline string: "A."
             FCB   $F7   ; display "A."
             LDAA  #$FF
             STAA  ROBOTMODE
             CLI   
             BRA   MON_LOOP

;---------------------------------------------------------------
; OPTROM - executive key D: start an optional ROM
;
; If the byte at $2000 is $55, jumps to $2001. That is the signature an
; accessory ROM in socket U417 (mapped at $2000) uses to make itself
; startable from the keypad.
;
; Changes:   A, B, X, flags N Z V C ; on some paths: B, X
; Preserves: none   [static]
; Stack:     0 bytes max, including callees
; Exit:      RTS; indirect JMP at $F537
;---------------------------------------------------------------
OPTROM:      LDAA  $2000
             CMPA  #$55
             BNE   LF53A
             JMP   $2001
LF53A:       RTS   

;---------------------------------------------------------------
; USERKEY9 / USERKEYC / USERKEYF - executive keys 9, C, F
;
; Run the three bytes at $0030 (key 9), $0033 (key C) or $0036 (key F)
; in Robot Language. Confirmed in the emulator; the owners' FAQ has 9
; and F the other way round. RAMINIT puts $3A (return to executive)
; there, so an unprogrammed key does nothing.
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     14 bytes max, including callees
; Exit:      tail-JMP to MON_RUN
; Calls:     MON_RUN
;---------------------------------------------------------------
USERKEY9:    LDAA  #$30
             LDAB  #$00
             BRA   USERKEY

;---------------------------------------------------------------
; USERKEYC - executive key C: run the Robot Language bytes at $0033
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     14 bytes max, including callees
; Exit:      tail-JMP to MON_RUN
; Calls:     MON_RUN
;---------------------------------------------------------------
USERKEYC:    LDAA  #$33
             LDAB  #$00
             BRA   USERKEY

;---------------------------------------------------------------
; USERKEYF - executive key F: run the Robot Language bytes at $0036
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     14 bytes max, including callees
; Exit:      tail-JMP to MON_RUN
; Calls:     MON_RUN
;---------------------------------------------------------------
USERKEYF:    LDAA  #$36
             LDAB  #$00
USERKEY:     LDX   USERFRAME   ; set the user PC in the register frame
             STAA  $07,X
             STAB  $06,X
             LDAA  #$FF
             STAA  ROBOTMODE
             JMP   MON_RUN   ; start the Robot Language run loop

;---------------------------------------------------------------
; MON_BREAK - monitor key 9: set a breakpoint
;
; Finds a free slot (address $FFFF) among the four at $0FE0, prompts
; "br." and reads the address. All four in use: shows "FULL".
;
; Changes:   A, B, X, flags H N Z V C
; Preserves: none   [static]
; Stack:     15 bytes max, including callees
; Exit:      RTS
; Calls:     ASK_ADDR, OUTSTR4, OUTSTR0
;---------------------------------------------------------------
MON_BREAK:   LDX   #$0FDD
             LDAA  #$FF
             LDAB  #$04
LF561:       INX   
             INX   
             INX   
             CMPA  $01,X
             BNE   LF56C
             CMPA  $02,X
             BEQ   LF57A
LF56C:       DECB  
             BNE   LF561
             JSR   OUTSTR0
             FCB   $00,$47,$3E,$0E,$0E,$A0   ; inline string: " FULL!"
             INCA  
             RTS   
LF57A:       INX   
             STX   SAVESP
             BSR   OUTSTR4
             FCB   $1F,$85   ; inline string: "br."
             BSR   ASK_ADDR
             INCA  
             RTS   

;---------------------------------------------------------------
; ASK_DO - prompt "do." and read a two-byte address into (X)
;
; Changes:   A, B, X, flags H N Z V C
; Preserves: none   [static + measured: 4 calls]
;            measured: X written but equal at exit on every call
; Stack:     13 bytes max, including callees (observed 13)
; Cycles:    observed 732,606-732,816 E cycles over 4 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      falls into ASK_ADDR; tail-JMP to KEYBYTES
; Calls:     OUTSTR4, REDIS, KEYBYTES
; Called from: MON_DO
;---------------------------------------------------------------
ASK_DO:      STX   SAVESP
             BSR   OUTSTR4
             FCB   $3D,$9D   ; display "do."

;---------------------------------------------------------------
; ASK_ADDR - home the display and read two bytes from the keypad into (SAVESP)
;
; Changes:   A, B, X, flags H N Z V C
; Preserves: none   [static + measured: 1 call]
;            measured: A written but equal at exit on every call
; Stack:     13 bytes max, including callees (observed 13)
; Cycles:    observed 730,488 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      tail-JMP to KEYBYTES
; Calls:     REDIS, KEYBYTES
; Called from: MON_BREAK
;---------------------------------------------------------------
ASK_ADDR:    JSR   REDIS
             LDX   SAVESP
             LDAB  #$02
             JMP   KEYBYTES

;---------------------------------------------------------------
; ASK_AD - prompt "Ad." and read a two-byte address into (X)
;
; Changes:   A, B, X, flags H N Z V C
; Preserves: none   [static + measured: 2 calls]
;            measured: A, X written but equal at exit on every call
; Stack:     13 bytes max, including callees (observed 13)
; Cycles:    observed 726,625-734,176 E cycles over 2 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      falls into ASK_ADDR; tail-JMP to KEYBYTES
; Calls:     OUTSTR4, REDIS, KEYBYTES
; Called from: ASK_ADDR0
;---------------------------------------------------------------
ASK_AD:      STX   SAVESP
             BSR   OUTSTR4
             FCB   $77,$BD   ; display "Ad."
             BRA   ASK_ADDR

;---------------------------------------------------------------
; OUTSTR4 - display the inline string that follows the call, starting at digit 4
;
; Changes:   A, B, X, flags N Z V C
; Preserves: none   [static + measured: 9 calls]
;            measured: B written but equal at exit on every call
; Stack:     1 byte max, including callees (observed 1)
; Cycles:    observed 372 E cycles on every call over 9 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      tail-JMP to OUTSTR_AT
; Calls:     OUTSTR_AT
; Called from: UT_SAVE, MON_BREAK, ASK_DO, ASK_AD
;---------------------------------------------------------------
OUTSTR4:     LDX   #$C12F
             JMP   OUTSTR_AT

;---------------------------------------------------------------
; MON_DO - monitor key D: run from an address
;
; Prompts "do." and puts the address straight into the PC slot of the
; register frame, then runs it (MON_RUN).
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     15 bytes max, including callees
; Exit:      RTI; falls into MON_RUN; falls into RUN_STEP; resets SP; tail-JMP to SHOW_ADDR; tail-JMP to SS_SHOW
; Calls:     RSTEP, ASK_DO, CLRDIS, SHOW_ADDR, SS_SHOW, SSTEP
;---------------------------------------------------------------
MON_DO:      LDX   USERFRAME
             INX   
             INX   
             INX   
             INX   
             INX   
             INX   
             BSR   ASK_DO

;---------------------------------------------------------------
; MON_RUN / RUN_STEP - monitor key 7 (resume) and the run loop
;
; Single-steps the first instruction (so a breakpoint at the start
; address does not stop it at once), then:
;  Machine Language: plants SWI ($3F) at each breakpoint address,
;    saving the original bytes, and RTIs into the program at full
;    speed. BRK_TRAP catches the SWI.
;  Robot Language: RSTEP one instruction at a time, comparing the PC
;    with the four breakpoints between passes.
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     14 bytes max, including callees
; Exit:      RTI; falls into RUN_STEP; resets SP; tail-JMP to SHOW_ADDR; tail-JMP to SS_SHOW
; Calls:     RSTEP, CLRDIS, SHOW_ADDR, SS_SHOW, SSTEP
; Called from: USERKEY9, USERKEYC, USERKEYF
;---------------------------------------------------------------
MON_RUN:     JSR   CLRDIS

;---------------------------------------------------------------
; RUN_STEP - the run loop proper (MON_RUN without clearing the display; see MON_RUN)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     14 bytes max, including callees
; Exit:      RTI; resets SP; tail-JMP to SHOW_ADDR; tail-JMP to SS_SHOW
; Calls:     RSTEP, SHOW_ADDR, SS_SHOW, SSTEP
; Called from: UT_INIT, UT_REST, RESET
;---------------------------------------------------------------
RUN_STEP:    JSR   SSTEP   ; SSTEP: run one instruction
             TST   ROBOTMODE
             BNE   RUN_ROBOT
             LDAB  #$3F
             LDX   #$0FDD
LF5C2:       INX      ; for each slot: swap the code byte with $3F (SWI)
             INX   
             INX   
             STX   XSAVE
             LDX   $01,X
             LDAA  $00,X
             STAB  $00,X
             LDX   XSAVE
             STAA  $00,X
             CPX   #$0FE9
             BNE   LF5C2
             LDX   #BRK_TRAP   ; a breakpoint SWI now enters BRK_TRAP
             STX   SWIVEC
             STS   MONSP
             LDS   USERFRAME   ; switch to the user's stack and registers
             RTI      ; run the program at full speed
RUN_ROBOT:   JSR   RSTEP   ; RSTEP: one Robot Language instruction
             BCS   LF606
             LDX   USERFRAME
             LDX   $06,X
             CPX   $0FE1   ; stop when the PC reaches any of the four breakpoints
             BEQ   LF603
             CPX   $0FE4
             BEQ   LF603
             CPX   $0FE7
             BEQ   LF603
             CPX   $0FEA
             BNE   RUN_STEP
LF603:       JMP   SHOW_ADDR
LF606:       JMP   SS_SHOW

;---------------------------------------------------------------
; BRK_SWAP - put the original bytes back at the four breakpoint addresses
;
; Out:       C set if XSAVE was one of the breakpoint addresses
;
; Changes:   A, B, X, flags N Z V C
; Preserves: none   [static + measured: 6 calls, 3/4 branches]
; Stack:     0 bytes max, including callees (observed 0)
; Cycles:    observed 232-234 E cycles over 6 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
;---------------------------------------------------------------
BRK_SWAP:    LDAB  #$04
             LDX   #$0FDD
             CLC   
LF60F:       INX   
             INX   
             INX   
             STX   SAVESP
             LDAA  $00,X
             LDX   $01,X
             STAA  $00,X
             CPX   XSAVE
             BNE   LF621
             SEC   
LF621:       LDX   SAVESP
             DECB  
             BNE   LF60F
             RTS   

;---------------------------------------------------------------
; BRK_TRAP - a planted SWI fired
;
; Backs the saved PC up by one (to the breakpoint address), restores
; the original bytes and shows the address. An SWI that was not a
; breakpoint is the program's own: enter Robot Language there.
;---------------------------------------------------------------
BRK_TRAP:    CLI   
             TSX   
             STS   USERFRAME
             LDAA  $06,X
             BNE   LF633
             DEC   $05,X
LF633:       DECA  
             STAA  $06,X
             LDAB  $05,X
             LDS   MONSP
             STAB  XSAVE
             STAA  $0FEF
             BSR   BRK_SWAP
             BCS   LF648
             JMP   RUN_STEP
LF648:       LDX   XSAVE
             JMP   SHOW_ADDR

;---------------------------------------------------------------
