;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: KEYUP, KEYPOLL, KEYDOWN, INHEX2
;---------------------------------------------------------------
KEYSCAN:     PSHB  
             LDAB  KEYROW2
             LDAA  KEYROW0
             ASLA  
             ASLA  
             ASLA  
             ROLB  
             ASLA  
             ROLB  
             ASLA  
             ROLB  
             PSHB  
             LDAB  KEYROW1
             ANDB  #$1F
             ABA   
             PULB  
             COMA  
             COMB  
             STX   XSAVE
             LDX   #HEXSEG+15
             CBA   
             BEQ   LF76F
             BCC   LF766
             PSHA  
             TBA   
             PULB  
             LDX   #KEYCODE1+7
LF766:       TSTB  
             BNE   LF76F
LF769:       INX   
             ASLA  
             BHI   LF769
             BEQ   LF770
LF76F:       CLC   
LF770:       LDAA  $00,X
             LDX   XSAVE
             PULB  
             RTS   

