; Exit:      RTS
; Calls:     OUTCH_X
; Called from: UTIL, MON_CC, INHEX2, OUTBYT, UT_SETTIME, UT_SETDATE, UT_SHOWDATE, UT_SHOWTIME
;---------------------------------------------------------------
OUTHEX:      PSHA  
             ANDA  #$0F
             STX   XSAVE
             LDX   #HEXSEG-1   ; HEXSEG table minus 1
LF7BE:       INX   
             DECA  
             BPL   LF7BE
             LDAA  $00,X
             BSR   OUTCH_X
             PULA  
             RTS   

;---------------------------------------------------------------
; OUTCH - light one digit with a raw segment pattern
;
; Each digit is a 74LS259 latch that takes one segment per write on data
; bit 0, at 16 consecutive addresses (the latch ignores address bit 3,
; so only the last 8 writes count). The loop rotates A left through the
; carry before each write. After 2 + 16 = 18 rotations of the 9-bit
; ring (A and C), A is back to its original value.
;
; In:        A = segments (bit 6 a ... bit 0 g, bit 7 point), DIGADD = digit
; Out:       DIGADD = next digit to the right
; Memory:    writes XSAVE, DIGADD; 16 latch addresses
;
; Changes:   A, flags N Z V C
; Preserves: B, X   [static + measured: 21,323 calls]
;            measured: A written but equal at exit on every call
; Stack:     1 byte max, including callees (observed 1)
; Cycles:    observed 329 E cycles on every call over 21,323 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS; falls into OUTCH_X
; Called from: LRN_SHOWPTR, MAN_SHOW, MAN_SHOWNOW, SAY_READY, IDLE_ANIM, CLRDIS, KEYBYTES, OUTSTR_AT, OUTSTR
;---------------------------------------------------------------
OUTCH:       STX   XSAVE

;---------------------------------------------------------------
; OUTCH_X - OUTCH without saving X first (callers that saved X themselves)
;
; Changes:   A, X, flags N Z V C
; Preserves: B   [static + measured: 26,943 calls, 1/1 branches]
;            measured: A written but equal at exit on every call
; Stack:     1 byte max, including callees (observed 1)
; Cycles:    observed 323 E cycles on every call over 26,943 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: OUTBYT, OUTHEX
;---------------------------------------------------------------
OUTCH_X:     LDX   DIGADD
             PSHB  
             ROLA     ; two extra rotations line the bits up with the latch order
             ROLA  
             LDAB  #$10
LF7D3:       ROLA  
             STAA  $00,X   ; latch bit 0 of A at this address
             DEX   
             DECB  
             BNE   LF7D3
             STX   DIGADD   ; the next digit's latch block is $10 lower
             LDX   XSAVE
             PULB  
             RTS   

;---------------------------------------------------------------
; OUTSTR_AT / OUTSTR - display the string that follows the call
;
; OUTSTR takes its caller's return address as a pointer to segment
; patterns, shows them until one has bit 7 (the decimal point) set, and
; returns to the byte after the string. OUTSTR_AT first sets DIGADD from X.
;
; In:        inline string after the JSR
; Out:       A = 0; returns past the string
;
; Changes:   A, B, X, flags N Z V C
; Preserves: none   [static]
; Stack:     1 byte max, including callees
; Exit:      falls into OUTSTR; indirect JMP at $F7F3
; Calls:     OUTCH
; Called from: OUTSTR4, OUTSTR0B, OUTSTR0
;---------------------------------------------------------------
OUTSTR_AT:   STX   DIGADD

;---------------------------------------------------------------
; OUTSTR - display the inline string after the call at DIGADD (see OUTSTR_AT)
;
; Changes:   A, B, X, flags N Z V C
; Preserves: none   [static + measured: 87 calls, 1/1 branches]
;            measured: B written but equal at exit on every call
; Stack:     1 byte max, including callees (observed 1)
; Cycles:    observed 14-360 E cycles over 87 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      indirect JMP at $F7F3
; Calls:     OUTCH
; Called from: UTIL, UT_LOAD, LRN_SETUP, LRN_ADDR, MAN_SETUP, ROOM_CHK, LOGIC_LOW, LGLO_WAKE, MOTOR_LOW, NMI, MON_ML, MON_RL
;---------------------------------------------------------------
OUTSTR:      TSX   
             LDX   $00,X   ; X = return address = the string
             INS      ; drop the return address
             INS   
LF7EA:       LDAA  $00,X
             BSR   OUTCH
             INX   
             TSTA     ; bit 7 set: last character
             BPL   LF7EA
             CLRA  
             JMP   $00,X   ; "return" past the string

;---------------------------------------------------------------
; OPLEN - classify a 6800 opcode: legal?, length, relative branch?
;
; Looks the opcode up in OPBITMAP (one bit per opcode, MSB first; 1 = not a 6800
; instruction).  For a legal opcode the length comes from the opcode's
; addressing-mode bits: $20-$2F and $8D (BSR) are 2-byte relative branches,
; other $00-$5F are 1 byte, $8C/$8E/$CE (16-bit immediates) and the extended
; columns ($x where bits 5-4 = 11) are 3, everything else is 2.  The SBCB #$FF
; turns the carry of the last compare into "+1 if 3 bytes".
;
; In:        A = opcode
; Out:       A preserved; B = length (1-3), Z = 0              (contract)
;            not 6800: B = 0, Z = 1, C = 1
;            C = 0 only for relative branches (incl. BSR)
;
; Changes:   A, B, X, flags N Z V C ; on some paths: A
; Preserves: none   [static + measured: 24,276 calls, 7/8 branches]
; Stack:     1 byte max, including callees (observed 1)
; Cycles:    observed 61-379 E cycles over 24,276 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTS
; Called from: SSTEP
;---------------------------------------------------------------
OPLEN:       PSHA  
             TAB   
             LDX   #OPBITMAP-1   ; X = bitmap - 1 (pre-incremented below)
OL_BYTE:     INX      ; X = OPBITMAP + opcode / 8
             SUBB  #$08   ; B ends as (opcode & 7) - 8
             BCC   OL_BYTE
             LDAA  $00,X   ; bitmap byte
OL_BIT:      RORA     ; rotate 8 - (opcode & 7) times: C = bit 7 - (opcode & 7)
             INCB  
             BNE   OL_BIT
             PULA  
             BCS   OL_DONE   ; C = 1: not a 6800 opcode (B = 0, Z = 1)
             CMPA  #$30   ; $30-$5F: inherent
             BCC   OL_NOTBR
             CMPA  #$20   ; $20-$2F: relative branch, 2 bytes (C = 0)
             BCC   OL_LEN2
OL_NOTBR:    CMPA  #$60   ; $00-$1F, $30-$5F: 1 byte (C = 1)
             BCS   OL_LEN1
             CMPA  #$8D   ; BSR: 2 bytes, relative (C = 0)
             BEQ   OL_LEN2
             ANDA  #$BD   ; $8C/$8E/$CC/$CE all become $8C
             CMPA  #$8C   ; CPX/LDS/LDX # : 3 bytes (C = 0 here)
             BEQ   OL_SIZE
             ANDA  #$30   ; bits 5-4 = 11: extended (C = 0), else C = 1
             CMPA  #$30
OL_SIZE:     SBCB  #$FF   ; B = 1 if C = 0 (3 bytes), 0 if C = 1 (2 bytes); C = 1 after
OL_LEN2:     INCB  
OL_LEN1:     INCB  
OL_DONE:     RTS   

;---------------------------------------------------------------
; KEY_SS - SS key: single-step the user program and show the next instruction
;
; In Robot Language one step is one RSTEP (a robot instruction or one native
; instruction); otherwise one SSTEP.  Then shows the new PC and its opcode.
;
; Memory:    as RSTEP / SSTEP; display
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     14 bytes max, including callees
; Exit:      falls into SS_SHOW; tail-JMP to SHOW_ADDR
; Calls:     RSTEP, SHOW_ADDR, SSTEP
;---------------------------------------------------------------
KEY_SS:      TST   ROBOTMODE   ; Robot Language?
             BEQ   SS_NATIVE
             JSR   RSTEP   ; RSTEP: one robot or native instruction
             BRA   SS_SHOW
SS_NATIVE:   JSR   SSTEP   ; SSTEP: one native instruction (an illegal opcode is just not run)

;---------------------------------------------------------------
; SS_SHOW - show the user's PC and the byte there (after a single step or a stop)
;
; Changes:   A, B, X, flags N Z V C
; Preserves: none   [static]
; Stack:     12 bytes max, including callees
; Exit:      tail-JMP to SHOW_ADDR
; Calls:     SHOW_ADDR
; Called from: MON_DO, MON_RUN, RUN_STEP
;---------------------------------------------------------------
SS_SHOW:     LDX   USERFRAME
             LDX   $06,X   ; X = user PC
             JMP   SHOW_ADDR   ; show address and data

;---------------------------------------------------------------
; SSTEP - execute one native 6800 instruction of the user program
;
; Copies the instruction into a 7-byte buffer on the monitor stack:
;     op  b1  b2  SWI  SWI  next-PC(hi)  next-PC(lo)
; with unused operand bytes replaced by NOP ($01).  A relative branch gets its
; offset rewritten to 2, so if taken it skips the first SWI and lands on the
; second; the trap can tell the cases apart by which SWI fired.  Calls and
; control transfers that must not run from the buffer are simulated instead:
; BSR/JSR (SS_CALL), JMP (SS_JMPX, SS_SKIP2), RTS (SS_RTS), RTI (SS_RTI) and
; SWI (SS_SWI).  Anything else is run for real: the RAM SWI vector is pointed
; at SS_TRAP and an RTI is done from the user frame with its PC = the buffer, so
; the instruction runs with the user's own A, B, X, CC and stack pointer (frame
; + 7); its SWI then pushes the new user frame on the user stack.  Emulator:
; BSR, JSR ext, JMP idx, JMP ext, RTS, RTI and taken/untaken Bcc all traced
; through these paths with the expected PC and frame.
;
; In:        USERFRAME -> user registers, PC = instruction
; Out:       C = 0 executed: USERFRAME, user PC and registers updated
;            C = 1 not a 6800 opcode: nothing done              (contract)
; Memory:    SAVESP, SWIVEC, user frame, user stack, ROBOTMODE (SWI)
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 24,276 calls, 7/12 branches]
; Stack:     10 bytes max, including callees (observed 58)
; Cycles:    observed 157-658 E cycles over 24,276 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      RTI; RTS; resets SP; runs into data $F8F6
; Calls:     OPLEN
; Called from: RSTEP, MON_DO, MON_RUN, RUN_STEP, KEY_SS
;---------------------------------------------------------------
SSTEP:       STS   SAVESP   ; SAVESP = stack top above the buffer
             LDX   USERFRAME
             LDAA  $07,X   ; buffer +5/+6: user PC (made next-PC below)
             PSHA  
             LDAA  $06,X
             PSHA  
             LDX   $06,X   ; X = user PC
             LDAA  #$3F   ; buffer +3/+4: two SWIs
             PSHA  
             PSHA  
             LDAA  $02,X   ; buffer +0..+2: the instruction's three bytes
             PSHA  
             LDAA  $01,X
             PSHA  
             LDAA  $00,X
             PSHA  
             BSR   OPLEN   ; OPLEN: B = length, C = 0 for relative branches, Z = 1 if not 6800
             BNE   SS_PATCH   ; legal 6800 instruction
             LDS   SAVESP   ; not 6800: drop the buffer
             SEC      ; C = 1: let the interpreter have it
             RTS   
SS_PATCH:    TSX      ; X -> buffer
             BCS   SS_NOPS   ; not a relative branch
             STAB  $01,X   ; Bcc/BSR offset := 2 (taken lands on the second SWI)
SS_NOPS:     LDAA  #$01   ; NOP
             CMPB  #$02
             BGT   SS_NEXTPC   ; 3 bytes: nothing to pad
             BEQ   SS_NOP2   ; 2 bytes: pad b2
             STAA  $01,X   ; 1 byte: pad b1
SS_NOP2:     STAA  $02,X
SS_NEXTPC:   CLRA     ; buffer next-PC = PC + length
             ADDB  $06,X
             ADCA  $05,X
             STAA  $05,X
             STAB  $06,X
SS_SETPC:    LDX   USERFRAME   ; user frame PC = A:B (next PC; SS_CALL re-enters with junk, overwritten later)
             STAA  $06,X
             STAB  $07,X
             LDAB  #$06   ; B = 6: frame copy count for SS_CALL / SS_RTS
             PULA     ; peek at the opcode
             PSHA  
             ANDA  #$CF   ; $8D/$9D/$AD/$BD: BSR or JSR
             CMPA  #$8D
             PULA  
             BEQ   SS_CALL
             CMPA  #$6E   ; JMP idx
             BEQ   SS_JMPX
             CMPA  #$7E   ; JMP ext
             BEQ   SS_SKIP2+1
             CMPA  #$39   ; RTS
             BEQ   SS_RTS
             CMPA  #$3B   ; RTI
             BEQ   SS_RTI
             CMPA  #$3F   ; SWI
             BEQ   SS_SWI
             STS   $06,X   ; user PC = buffer address (S = buffer after the PULA)
             PSHA     ; opcode back in place
             LDX   #SS_TRAP   ; SWI will now come to SS_TRAP
             STX   SWIVEC
             LDS   USERFRAME   ; S = user frame
             RTI      ; run the instruction in the buffer with the user's registers

;---------------------------------------------------------------
; SS_TRAP - SWI after a stepped instruction (entered via SWIJMP)
;
; The stacked PC is one past the SWI that fired.  First SWI: the instruction
; fell through, so the user PC is the next-PC word stored behind the SWIs.
; Second SWI (only a taken branch gets there): the PC is next-PC plus the
; branch's original offset, read back from the user's code because the buffer
; copy was patched to 2.  The new frame address becomes USERFRAME.
;
; In:        S = user frame just pushed by SWI
; Out:       C = 0 to SSTEP's caller                            (contract)
; Memory:    USERFRAME, user frame PC
;---------------------------------------------------------------
SS_TRAP:     CLI      ; back on, IRQs were masked by SWI
             TSX      ; X -> new user frame
             LDX   $05,X   ; X = PC after the SWI that fired
             INX      ; + 1
             CLRA  
             CLRB  
             CPX   SAVESP   ; = SAVESP only for the second SWI (taken branch)
             BNE   SS_ADDPC   ; fell through: X -> next-PC word
             DEX      ; taken: X -> next-PC word
             LDX   $00,X   ; X = next PC
             DEX      ; X -> offset byte in the user's code
             LDAB  $00,X   ; B = original offset
             BPL   SS_TARGET
             COMA     ; negative: A = $FF (sign extend)
SS_TARGET:   TSX   
             LDX   $05,X   ; X -> next-PC word again
SS_ADDPC:    ADDB  $01,X   ; A:B = next PC (+ offset if taken)
             ADCA  $00,X
             TSX   
             STAA  $05,X   ; frame PC = result
             STAB  $06,X
             DEX      ; X = S convention (frame at +1..+7)
SS_SAVEFR:   STX   USERFRAME   ; USERFRAME = new frame
SS_EXIT:     LDS   SAVESP   ; back on the monitor stack
             CLC      ; C = 0: instruction executed
             RTS   
SS_CALL:     CMPA  #$8D   ; BSR?
             BNE   SS_CALLJ
             LDAA  #$5F   ; BSR $8D -> $5F so that -$3F gives BRA $20
SS_CALLJ:    SUBA  #$3F   ; $AD -> $6E JMP idx, $BD -> $7E JMP ext, $8D -> $20 BRA
             PSHA     ; move the user frame down 2 bytes ...
             DEX   
             DEX   
             STX   USERFRAME   ; ... USERFRAME follows it
SS_PUSHRET:  LDAA  $03,X   ; copy 7 bytes down; the old PC slot (= next PC) stays above
             STAA  $01,X   ; the new frame as the pushed return address
             INX   
             DECB  
             BPL   SS_PUSHRET
             BRA   SS_SETPC   ; now treat the call as the jump it was changed into
SS_JMPX:     PULA     ; A = index offset
             CLRB  
             ADDA  $05,X   ; B:A = user X + offset
             ADCB  $04,X
SS_SKIP2:    CPX   #$3332   ; skip trick: CPX # hides $33 $32 = PULB, PULA (JMP ext enters at +1 to pull its operand)
             STAA  $07,X   ; user PC = jump target
             STAB  $06,X
             BRA   SS_SAVEFR   ; done (no instruction is run)
SS_RTS:      INX      ; frame moves up 2 bytes over the return address
             INX   
             STX   USERFRAME
SS_RTSCP:    LDAA  $03,X   ; copy CC..XL up 2 (6th byte is scratch); the return address becomes the frame's PC
             STAA  $05,X
             DEX   
             DECB  
             BGT   SS_RTSCP   ; B = 6..1
             BRA   SS_EXIT   ; USERFRAME already updated
SS_RTI:      INX      ; drop the current frame: the user's RTI frame above it becomes the registers
             DECB  
             BPL   SS_RTI
             BRA   SS_SAVEFR   ; USERFRAME = frame + 7
SS_SWI:      LDAA  #$FF   ; SWI ($3F) in a user program = switch to Robot Language
             STAA  ROBOTMODE   ; ROBOTMODE on; PC already past the SWI
SS_SWIX:     BRA   SS_EXIT
* Opcode bitmap for OPLEN: bit (7 - op&7) of byte op/8 is 1 for each of the 59 opcodes
* the 6800 does not define (checked: identical to the emulator core's undefined set).
* Every Robot Language opcode is in this set; that is what lets one instruction stream
* mix native and robot instructions.
OPBITMAP:    FCB   $BC,$00,$3C,$AF,$40,$00,$00,$AC
             FCB   $64,$12,$64,$12,$64,$10,$64,$10
             FCB   $11,$01,$10,$04,$10,$00,$10,$00
             FCB   $11,$0D,$10,$0C,$10,$0C,$10,$0C
HEXSEG:      FCB   $7E,$30,$6D,$79,$33,$5B,$5F,$70   ; hex digits 0-9 A b C d E F as segment patterns (bit 6 = a ... bit 0 = g)
             FCB   $7F,$7B,$77,$1F,$4E,$3D,$4F,$47
KEYCODE1:    FCB   $07,$0A,$0D,$02,$05,$08,$0B,$0E   ; key codes for the 15 keypad positions (see KEYSCAN)
             FCB   $03,$06,$09,$0C,$0F,$00,$01,$04
KEYCMDS:     FDB   EXEC,MON_ML,EXEC,UTIL,MANUAL,EXEC,EXEC,LEARN   ; 32 command routines, pushed and entered with RTS: 16 executive keys, then 16 monitor keys
             FDB   EXEC,USERKEY9,MON_RL,EXEC,USERKEYC,OPTROM,EXEC,USERKEYF
             FDB   LF488,MON_A,MON_B,MON_PC,MON_X,MON_CC,MON_SP,MON_RUN
             FDB   KEY_SS,MON_BREAK,MON_AUTO,MON_BACK,MON_CHANGE,MON_DO,MON_EXAM,MON_FWD
             FCB   $FF,$FF,$FF,$FF,$FF,$FF

;---------------------------------------------------------------
; UT_SETTIME - utility 5 (keys 3 5): set the clock time
;
; Prompts "HH  SS." and reads six digits (hours, minutes, seconds) into
; $0064-$0069, then "A P 24." for the mode: D = AM, E = PM, F = 24-hour.
; Writes the digits into the MSM5832 registers through $C300 (write
; strobe) with the register number on $C2C0, then restarts via RESET.
;
; Memory:    writes $000F/$0010 (register range), $0064-$0069; CLOCK, CTRL
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static]
; Stack:     16 bytes max, including callees
; Exit:      tail-JMP to RESET
; Calls:     RESET, REDIS, OUTSTR0, INCH, OUTHEX
;---------------------------------------------------------------
UT_SETTIME:  JSR   OUTSTR0
             FCB   $37,$37,$00,$00,$5B,$DB   ; display "HH  SS."
             LDX   #$05FF
             STX   BATSLEEP
             BRA   LF9BE

;---------------------------------------------------------------
; UT_SETDATE - utility 6 (keys 3 6): set the date
;
; Prompts "yy  dd." and reads six digits (year, month, day) into the
; clock's date registers, as UT_SETTIME does for the time.
;
; Changes:   A, B, X, flags H I N Z V C
; Preserves: none   [static + measured: 1 call, 3/3 branches]
; Stack:     16 bytes max, including callees (observed 9)
; Cycles:    observed 3,680,628 E cycles on every call over 1 calls, including callees and waits,
;            excluding interrupts taken meanwhile   [measured]
; Exit:      tail-JMP to RESET
; Calls:     RESET, REDIS, OUTSTR0, INCH, OUTHEX
;---------------------------------------------------------------
UT_SETDATE:  JSR   OUTSTR0
             FCB   $3B,$3B,$00,$00,$3D,$BD   ; display "yy  dd."
             LDX   #$0C06
             STX   BATSLEEP
LF9BE:       LDAA  #$40
             STAA  CLOCK
             JSR   REDIS
             LDX   #$0000
LF9C9:       JSR   INCH
             STAA  $64,X
             JSR   OUTHEX
             INX   
             CPX   #$0006
             BNE   LF9C9
             LDAA  BATSLEEP
             CMPA  #$0C
             BEQ   LFA07
             JSR   OUTSTR0
             FCB   $77,$00,$67,$00,$6D,$B3   ; display "A P 24."
             LDAB  $64
LF9E8:       JSR   INCH
             CMPA  #$0F
             BNE   LF9F5
             ORAB  #$08
             STAB  $64
             BRA   LFA07
LF9F5:       CMPA  #$0D
             BNE   LF9FF
             ANDB  #$03
             STAB  $64
             BRA   LFA07
LF9FF:       CMPA  #$0E
             BNE   LF9E8
             ORAB  #$04
             STAB  $64
LFA07:       LDX   #$0000
             LDAB  BATSLEEP
LFA0C:       STAB  CTRL
             LDAA  $64,X
             ORAA  #$50
             STAA  CLOCK
             INX   
             DECB  
             CMPB  SONARHITS
             BNE   LFA0C
             JMP   RESET

;---------------------------------------------------------------
; UT_SHOWDATE - utility 8 (keys 3 8): show the date from the clock, continuously
;
; Reads clock registers $C down to $7 (year, month, day) and shows them
; as six hex digits, over and over until RESET.
;
; Changes:   flags N Z V C
; Preserves: A, B, X   [static]
; Stack:     6 bytes max, including callees
; Exit:      none
; Calls:     REDIS, OUTHEX
;---------------------------------------------------------------
UT_SHOWDATE: LDX   #$0C06
             STX   BATSLEEP
             BRA   LFA2B

;---------------------------------------------------------------
; UT_SHOWTIME - utility 7 (keys 3 7): show the time from the clock, continuously
;
; Reads clock registers $5 down to $0 (hours, minutes, seconds); the
; hours-tens register's AM/PM and 24-hour flag bits are masked off.
;
; Changes:   flags N Z V C
; Preserves: A, B, X   [static]
; Stack:     6 bytes max, including callees
; Exit:      none
; Calls:     REDIS, OUTHEX
;---------------------------------------------------------------
UT_SHOWTIME: LDX   #$05FF
             STX   BATSLEEP
LFA2B:       LDAA  #$A0
             STAA  CLOCK
LFA30:       JSR   REDIS
             LDAB  BATSLEEP
LFA35:       STAB  CTRL
             LDAA  CLOCK
             CMPB  #$05
             BNE   LFA41
             ANDA  #$03
LFA41:       JSR   OUTHEX
             DECB  
             CMPB  SONARHITS
             BNE   LFA35
             BRA   LFA30
* ===============================================================
* SPEECH PHRASE DICTIONARY ($FA4B-$FED2)
* 28 canned SC-01 phoneme strings for user programs (Speak 71/72 aaaa, or BF aaaa chains).
* Each byte: bits 5-0 = SC-01 phoneme, bits 7-6 = inflection (pitch); $FF ends a string.
* Phoneme $3F is the SC-01 STOP phoneme (a silence inside a phrase), not a terminator.
* None of the phrases uses BF chaining, and nothing in the ROM refers to them: there is no
* phrase address table and no code in this block (checked: no 16-bit reference to any phrase
* start anywhere in $E000-$FFFF). The manual's BF example starts its chain at $FAB4, which
* lands inside PH_MOVEARM ("...ove my arm") - probably a typo for one of the phrase starts.
* ===============================================================
* PH_MYNAME says: "Hello, my name is Hero."
PH_MYNAME:   FCB   $1B,$01,$18,$26,$2D,$3E,$0C,$15,$00,$3C,$0D,$20,$09,$0C,$03,$0B,$12,$03,$1B,$2C,$2B,$26,$2D,$3F,$FF   ; speech: H EH2 L O W PA1 M AH1 EH3 E1 N A I3 M PA0 I1 Z PA0 H E R O W STOP [end]
* PH_HEATHBOT says: "Hello, I am Hero, the Heath educational robot."
